window.CGL_DATA=window.CGL_DATA||{};window.CGL_DATA["CGL-28-OCT-2026-SHIFT-2"]={"id":"CGL-28-OCT-2026-SHIFT-2","title":"CGL 28 OCT 2026 SHIFT 2","order":["REASONING","GK","MATH","ENGLISH"],"marking":{"correct":2,"negative":0.5},"qualifying":[],"sections":{"REASONING":{"seconds":900,"questions":[{"no":1,"local_id":"50001","quid":"Q1000070781","section":"REASONING","topic":"Number Analogy","question":{"en":"If 4 &#8594; 64, 5 &#8594; 125, then 6 &#8594; ? [SSC CGL 28/10/26 Shift 2]","hi":"यदि 4 &#8594; 64, 5 &#8594; 125, तो 6 &#8594; ? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"196"},"2":{"en":"216"},"3":{"en":"256"},"4":{"en":"324"}},"answer":"2","solution":{"en":"Each number is written as its own cube: 4³ = 64 and 5³ = 125<br>So 6 is written as 6³ = 216<br>Hence the missing number is 216<br><br><b>Hence, the correct answer is option (2): 216.</b>","hi":"प्रत्येक संख्या को उसके घन के रूप में लिखा जाता है: 4³ = 64 तथा 5³ = 125<br>अतः 6 को 6³ = 216 के रूप में लिखा जाएगा<br>इसलिए लुप्त संख्या 216 है<br><br><b>अतः सही उत्तर विकल्प (2): 216 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":2,"local_id":"50002","quid":"Q1000070782","section":"REASONING","topic":"Miscellaneous","question":{"en":"A shopkeeper allows a discount of 10% on the marked price of a product but still gains 20%. If the marked price is Rs. 600, find the cost price. [SSC CGL 28/10/26 Shift 2]","hi":"एक दुकानदार किसी वस्तु के अंकित मूल्य पर 10% छूट देता है, फिर भी 20% लाभ कमाता है। यदि अंकित मूल्य 600 रुपये है, तो लागत मूल्य ज्ञात कीजिए। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"480","hi":"480 रुपये"},"2":{"en":"450","hi":"450 रुपये"},"3":{"en":"420","hi":"420 रुपये"},"4":{"en":"400","hi":"400 रुपये"}},"answer":"2","solution":{"en":"After a discount of 10% the selling price is 600 × 0.9 = 540<br>The selling price gives a profit of 20%, so 540 = cost price × 1.2<br>Hence the cost price is 540 ÷ 1.2 = 450<br><br><b>Hence, the correct answer is option (2): 450.</b>","hi":"10% छूट के बाद विक्रय मूल्य 600 × 0.9 = 540 है<br>विक्रय मूल्य पर 20% लाभ है, अतः 540 = लागत मूल्य × 1.2<br>इसलिए लागत मूल्य 540 ÷ 1.2 = 450 है<br><br><b>अतः सही उत्तर विकल्प (2): 450 रुपये है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":3,"local_id":"50003","quid":"Q1000070783","section":"REASONING","topic":"Syllogism","question":{"en":"Read the following statement carefully and identify the conclusion that follows.<br><b>Statement:</b><br>All laptops are devices. No device is disposable.<br><b>Conclusions:</b><br>I. All laptops are disposable.<br>II. No laptop is disposable. [SSC CGL 28/10/26 Shift 2]","hi":"निम्नलिखित कथन को ध्यान से पढ़िए और वह निष्कर्ष पहचानिए जो निकलता है।<br><b>कथन:</b><br>सभी लैपटॉप उपकरण हैं। कोई उपकरण डिस्पोजेबल नहीं है।<br><b>निष्कर्ष:</b><br>I. सभी लैपटॉप डिस्पोजेबल हैं।<br>II. कोई लैपटॉप डिस्पोजेबल नहीं है। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Only I follows","hi":"केवल I निकलता है"},"2":{"en":"Only II follows","hi":"केवल II निकलता है"},"3":{"en":"Both I and II follow","hi":"I और II दोनों निकलते हैं"},"4":{"en":"Neither I nor II follows","hi":"कोई नहीं निकलता"}},"answer":"2","solution":{"en":"Every laptop is a device and no device is disposable, so a laptop can never be disposable<br>That is exactly conclusion II, so II follows<br>Conclusion I says the opposite, so it does not follow<br>Hence only conclusion II follows<br><br><b>Hence, the correct answer is option (2): Only II follows.</b>","hi":"प्रत्येक लैपटॉप उपकरण है और कोई उपकरण डिस्पोजेबल नहीं है, अतः लैपटॉप कभी डिस्पोजेबल नहीं हो सकता<br>यही निष्कर्ष II है, अतः II निकलता है<br>निष्कर्ष I इसका विपरीत कहता है, अतः वह नहीं निकलता<br>इसलिए केवल निष्कर्ष II निकलता है<br><br><b>अतः सही उत्तर विकल्प (2): केवल II निकलता है है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":4,"local_id":"50004","quid":"Q1000070784","section":"REASONING","topic":"Number Series","question":{"en":"Complete the series by filling in the blank.<br>25, 21, ___, 13, 9 [SSC CGL 28/10/26 Shift 2]","hi":"रिक्त स्थान भरकर श्रेणी पूरी कीजिए।<br>25, 21, ___, 13, 9 [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"18"},"2":{"en":"17"},"3":{"en":"16"},"4":{"en":"15"}},"answer":"2","solution":{"en":"Every term is 4 less than the term before it: 25 − 4 = 21, 21 − 4 = 17 and 17 − 4 = 13, 13 − 4 = 9 ✔<br>So the blank carries 17<br>Hence the missing number is 17<br><br><b>Hence, the correct answer is option (2): 17.</b>","hi":"प्रत्येक पद अपने पहले के पद से 4 कम है: 25 − 4 = 21, 21 − 4 = 17 तथा 17 − 4 = 13, 13 − 4 = 9 ✔<br>अतः रिक्त स्थान में 17 आएगा<br>इसलिए लुप्त संख्या 17 है<br><br><b>अतः सही उत्तर विकल्प (2): 17 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":5,"local_id":"50005","quid":"Q1000070785","section":"REASONING","topic":"Number Analogy","question":{"en":"Select the option that is related to the third term in the same way as the second term is related to the first term and the sixth term is related to the fifth term.<br>16238 : 17339 :: 48375 : ? :: 23492 : 33593 [SSC CGL 28/10/26 Shift 2]","hi":"उस विकल्प का चयन कीजिए जो तीसरे पद से उसी प्रकार संबंधित है जिस प्रकार दूसरा पद पहले पद से तथा छठा पद पाँचवें पद से संबंधित है।<br>16238 : 17339 :: 48375 : ? :: 23492 : 33593 [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"59372"},"2":{"en":"59375"},"3":{"en":"37375"},"4":{"en":"59373"}},"answer":"2","solution":{"en":"Every even digit increases by 1 and every odd digit stays the same<br>16238 → 1, 6→7, 2→3, 3, 8→9 = 17339<br>23492 → 2→3, 3, 4→5, 9, 2→3 = 33593<br>48375 → 4→5, 8→9, 3, 7, 5 = 59375<br><br><b>Hence, the correct answer is option (2): 59375.</b>","hi":"प्रत्येक सम अंक में 1 जुड़ता है और विषम अंक वैसा ही रहता है<br>16238 → 1, 6→7, 2→3, 3, 8→9 = 17339<br>23492 → 2→3, 3, 4→5, 9, 2→3 = 33593<br>48375 → 4→5, 8→9, 3, 7, 5 = 59375<br><br><b>अतः सही उत्तर विकल्प (2): 59375 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":6,"local_id":"50006","quid":"Q1000070786","section":"REASONING","topic":"Coding & Decoding","question":{"en":"If \"APPLE\" is coded as 1-16-16-12-5, how will \"PEPAL\" be coded? [SSC CGL 28/10/26 Shift 2]","hi":"यदि \"APPLE\" का कूट 1-16-16-12-5 है, तो \"PEPAL\" का कूट क्या होगा? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"16-5-16-1-12"},"2":{"en":"16-5-1-16-12"},"3":{"en":"1-5-16-16-12"},"4":{"en":"12-1-16-5-16"}},"answer":"1","solution":{"en":"Each letter is written as its alphabet position: A = 1, P = 16, P = 16, L = 12 and E = 5, which gives 1-16-16-12-5 ✔<br>So PEPAL is written as P = 16, E = 5, P = 16, A = 1 and L = 12<br>Hence the code is 16-5-16-1-12<br><br><b>Hence, the correct answer is option (1): 16-5-16-1-12.</b>","hi":"प्रत्येक अक्षर को उसके वर्णमाला स्थान के रूप में लिखा जाता है: A = 1, P = 16, P = 16, L = 12 तथा E = 5, जिससे 1-16-16-12-5 मिलता है ✔<br>अतः PEPAL को P = 16, E = 5, P = 16, A = 1 तथा L = 12 के रूप में लिखा जाएगा<br>इसलिए कूट 16-5-16-1-12 है<br><br><b>अतः सही उत्तर विकल्प (1): 16-5-16-1-12 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":7,"local_id":"50007","quid":"Q1000070787","section":"REASONING","topic":"Mathematical Operations","question":{"en":"If 'P' denotes '+', 'B' denotes '−', 'Q' denotes '×' and 'D' denotes '÷', find the value of 100D(20B15)P(5Q4). [SSC CGL 28/10/26 Shift 2]","hi":"यदि 'P' का अर्थ '+', 'B' का अर्थ '−', 'Q' का अर्थ '×' तथा 'D' का अर्थ '÷' है, तो 100D(20B15)P(5Q4) का मान ज्ञात कीजिए। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"20"},"2":{"en":"40"},"3":{"en":"30"},"4":{"en":"10"}},"answer":"2","solution":{"en":"Replacing the letters, the expression becomes 100 ÷ (20 − 15) + (5 × 4)<br>20 − 15 = 5 and 5 × 4 = 20, so it is 100 ÷ 5 + 20<br>100 ÷ 5 = 20 and 20 + 20 = 40<br>Hence the value is 40<br><br><b>Hence, the correct answer is option (2): 40.</b>","hi":"अक्षरों को बदलने पर व्यंजक 100 ÷ (20 − 15) + (5 × 4) बनता है<br>20 − 15 = 5 तथा 5 × 4 = 20, अतः यह 100 ÷ 5 + 20 है<br>100 ÷ 5 = 20 तथा 20 + 20 = 40<br>इसलिए मान 40 है<br><br><b>अतः सही उत्तर विकल्प (2): 40 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":8,"local_id":"50008","quid":"Q1000070788","section":"REASONING","topic":"Address/Sentence Matching","question":{"en":"Carefully examine the address below and identify which of the following alternatives matches the given address.<br>Mr. P. Kumar<br>6723 Lake View Apartments, 14th Floor, Sarjapur Road<br>Bengaluru, Karnataka - 560100<br><b>Alternatives:</b><br>A) Mr. P. Kumar, 6723 Lake View Apartments, 14th Floor, Sarjapur Road, Bengaluru, Karnataka - 560100<br>B) Mr. P. Kumar, 6723 Lake View Apartments, 13th Floor, Sarjapur Road, Bengaluru, Karnataka - 560100<br>C) Mr. P. Kumar, 6723 Lake View Apartments, 14th Floor, Sarjapur Road, Bengaluru, Karnataka - 560101<br>D) Mr. P. Kumar, 6723 Lake View Apartments, 14th Floor, Sarjapur Road, Bengaluru, Karnataka - 560110 [SSC CGL 28/10/26 Shift 2]","hi":"नीचे दिए पते को ध्यान से देखिए और पहचानिए कि निम्नलिखित में से कौन-सा विकल्प दिए गए पते से मेल खाता है।<br>Mr. P. Kumar<br>6723 Lake View Apartments, 14th Floor, Sarjapur Road<br>Bengaluru, Karnataka - 560100<br><b>विकल्प:</b><br>A) Mr. P. Kumar, 6723 Lake View Apartments, 14th Floor, Sarjapur Road, Bengaluru, Karnataka - 560100<br>B) Mr. P. Kumar, 6723 Lake View Apartments, 13th Floor, Sarjapur Road, Bengaluru, Karnataka - 560100<br>C) Mr. P. Kumar, 6723 Lake View Apartments, 14th Floor, Sarjapur Road, Bengaluru, Karnataka - 560101<br>D) Mr. P. Kumar, 6723 Lake View Apartments, 14th Floor, Sarjapur Road, Bengaluru, Karnataka - 560110 [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Only C","hi":"केवल C"},"2":{"en":"B and C","hi":"B और C"},"3":{"en":"A and D","hi":"A और D"},"4":{"en":"Only A","hi":"केवल A"}},"answer":"4","solution":{"en":"The given address has 6723 Lake View Apartments, the 14th Floor and the pin code 560100<br>Alternative B changes the floor to the 13th, alternative C changes the pin code to 560101 and alternative D changes it to 560110<br>Only alternative A matches every part of the given address<br>Hence only A is correct<br><br><b>Hence, the correct answer is option (4): Only A.</b>","hi":"दिए गए पते में 6723 Lake View Apartments, 14वीं मंजिल तथा पिन कोड 560100 है<br>विकल्प B में मंजिल 13वीं है, विकल्प C में पिन कोड 560101 है तथा विकल्प D में 560110 है<br>केवल विकल्प A दिए गए पते के प्रत्येक भाग से मेल खाता है<br>अतः केवल A सही है<br><br><b>अतः सही उत्तर विकल्प (4): केवल A है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":9,"local_id":"50009","quid":"Q1000070789","section":"REASONING","topic":"Coding & Decoding","question":{"en":"In a certain code language, \"STONE\" is written as \"ENOTS.\" How will \"PEACE\" be written in the same code language? [SSC CGL 28/10/26 Shift 2]","hi":"एक निश्चित कूट भाषा में \"STONE\" को \"ENOTS\" लिखा जाता है। उसी कूट भाषा में \"PEACE\" कैसे लिखा जाएगा? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"ECAEP"},"2":{"en":"EPEAC"},"3":{"en":"AEPCD"},"4":{"en":"ECAPE"}},"answer":"1","solution":{"en":"STONE written backwards reads E N O T S, which is exactly the code ENOTS<br>So the letters of the word are simply reversed<br>PEACE reversed reads E C A E P<br>Hence PEACE is written as ECAEP<br><br><b>Hence, the correct answer is option (1): ECAEP.</b>","hi":"STONE को उल्टा लिखने पर E N O T S मिलता है, जो ठीक कूट ENOTS है<br>अतः शब्द के अक्षरों को केवल उलट दिया जाता है<br>PEACE उल्टा लिखने पर E C A E P मिलता है<br>इसलिए PEACE को ECAEP लिखा जाएगा<br><br><b>अतः सही उत्तर विकल्प (1): ECAEP है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":10,"local_id":"50010","quid":"Q1000070790","section":"REASONING","topic":"Coding & Decoding","question":{"en":"In a certain code language, if 'JAPAN IS GOOD' is written as '# ! %', 'GOOD IS HEAVEN' is written as '# ! &#36;', and 'HEAVEN IS BEAUTIFUL' is written as '! &#36; &amp;', then what is the code for 'GOOD HEAVEN' in that language? [SSC CGL 28/10/26 Shift 2]","hi":"एक निश्चित कूट भाषा में यदि 'JAPAN IS GOOD' का कूट '# ! %' है, 'GOOD IS HEAVEN' का कूट '# ! &#36;' है तथा 'HEAVEN IS BEAUTIFUL' का कूट '! &#36; &amp;' है, तो उस भाषा में 'GOOD HEAVEN' का कूट क्या है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"# &#36;"},"2":{"en":"# !"},"3":{"en":"&#36; %"},"4":{"en":"% !"}},"answer":"1","solution":{"en":"The words GOOD and IS appear in both the first and the second codes, and the symbols # and ! appear in both of them<br>IS and HEAVEN appear together in the second and the third codes, whose common symbols are ! and &#36;, so ! stands for IS and &#36; stands for HEAVEN<br>That leaves # for GOOD, so GOOD HEAVEN is written as # &#36;<br><br><b>Hence, the correct answer is option (1): # &#36;.</b>","hi":"GOOD तथा IS दोनों पहले और दूसरे कूट में आते हैं, और दोनों में साझा चिह्न # तथा ! हैं<br>IS और HEAVEN दूसरे तथा तीसरे कूट में साथ आते हैं, जिनके साझा चिह्न ! और &#36; हैं, अतः ! का अर्थ IS तथा &#36; का अर्थ HEAVEN है<br>शेष चिह्न # का अर्थ GOOD है, अतः GOOD HEAVEN का कूट # &#36; है<br><br><b>अतः सही उत्तर विकल्प (1): # &#36; है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":11,"local_id":"50011","quid":"Q1000070791","section":"REASONING","topic":"Miscellaneous","question":{"en":"A dealer marks an article 80% above cost price. He allows two successive discounts of 15% and 20%. What is his overall profit percentage? [SSC CGL 28/10/26 Shift 2]","hi":"एक विक्रेता किसी वस्तु को लागत मूल्य से 80% अधिक पर अंकित करता है। वह 15% तथा 20% की दो क्रमिक छूट देता है। उसका कुल लाभ प्रतिशत क्या है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"18.4%"},"2":{"en":"20.6%"},"3":{"en":"22.4%"},"4":{"en":"24.8%"}},"answer":"3","solution":{"en":"Let the cost price be 100, so the marked price is 180<br>After discounts of 15% and 20% the selling price is 180 × 0.85 × 0.8 = 122.4<br>So the profit is 122.4 − 100 = 22.4 on a cost of 100<br>Hence the overall profit percentage is 22.4%<br><br><b>Hence, the correct answer is option (3): 22.4%.</b>","hi":"मान लीजिए लागत मूल्य 100 है, तो अंकित मूल्य 180 है<br>15% तथा 20% छूट के बाद विक्रय मूल्य 180 × 0.85 × 0.8 = 122.4 है<br>अतः लाभ 122.4 − 100 = 22.4 है<br>इसलिए कुल लाभ प्रतिशत 22.4% है<br><br><b>अतः सही उत्तर विकल्प (3): 22.4% है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":12,"local_id":"50012","quid":"Q1000070792","section":"REASONING","topic":"Address/Sentence Matching","question":{"en":"Choose the option that perfectly matches the given address.<br><b>Original Address:</b><br>Apartment No 904Silver Crown Residency Block 8Madison Avenue WestManhattan New York NY 10022United States of America [SSC CGL 28/10/26 Shift 2]","hi":"वह विकल्प चुनिए जो दिए गए पते से पूर्णतः मेल खाता है।<br><b>मूल पता:</b><br>Apartment No 904Silver Crown Residency Block 8Madison Avenue WestManhattan New York NY 10022United States of America [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Apartment No 904Silver Crown Residency Block 8Madisson Avenue WestManhattan New York NY 10022United States of America"},"2":{"en":"Apartment No 904Silver Crown Residency Block 8Madison Avenue WestManhattan New York NY 10002United States of America"},"3":{"en":"Apartment No 904Silver Crown Residency Block 8Madison Avenue WestManhattan New York NY 10022United State of America"},"4":{"en":"Apartment No 904Silver Crown Residency Block 8Madison Avenue WestManhattan New York NY 10022United States of America"}},"answer":"4","solution":{"en":"The original address has Madison Avenue, the code 10022 and the words United States of America<br>The first option writes Madisson, the second changes the code to 10002 and the third writes United State of America<br>Only the fourth option repeats the given address exactly<br>Hence the fourth option perfectly matches the given address<br><br><b>Hence, the correct answer is option (4): Apartment No 904Silver Crown Residency Block 8Madison Avenue WestManhattan New York NY 10022United States of America.</b>","hi":"मूल पते में Madison Avenue, कोड 10022 तथा United States of America लिखा है<br>पहले विकल्प में Madisson है, दूसरे में कोड 10002 है तथा तीसरे में United State of America है<br>केवल चौथा विकल्प दिए गए पते को ठीक वैसा ही दोहराता है<br>अतः चौथा विकल्प दिए गए पते से पूर्णतः मेल खाता है<br><br><b>अतः सही उत्तर विकल्प (4): Apartment No 904Silver Crown Residency Block 8Madison Avenue WestManhattan New York NY 10022United States of America है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":13,"local_id":"50013","quid":"Q1000070793","section":"REASONING","topic":"Blood Relations","question":{"en":"A household includes six members: P, Q, R, S, T, and U. P and R are husband and wife. Q is the son of R, although R is not Q's mother. T is the brother of R. S is the daughter of P, and U is the brother of Q. Based on the information provided, determine the number of children P has. [SSC CGL 28/10/26 Shift 2]","hi":"एक परिवार में छह सदस्य हैं: P, Q, R, S, T तथा U। P और R पति-पत्नी हैं। Q, R का पुत्र है, यद्यपि R, Q की माता नहीं है। T, R का भाई है। S, P की पुत्री है तथा U, Q का भाई है। दी गई जानकारी के आधार पर P के बच्चों की संख्या निर्धारित कीजिए। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"1"},"2":{"en":"2"},"3":{"en":"3"},"4":{"en":"4"}},"answer":"3","solution":{"en":"<svg width=\"293\" height=\"134\" viewBox=\"0 0 293 134\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><g fill=\"#fff3c4\" stroke=\"#e0a000\"><rect x=\"184\" y=\"34\" width=\"27\" height=\"20\" rx=\"4\"/></g><path d=\"M160 40H182M160 44H182M171 44V76M122 76H220M122 76V88M171 76V88M220 76V88M73 24H144M73 24V34M144 24V34\"/><g fill=\"#000\" stroke=\"none\" text-anchor=\"middle\"><text x=\"73\" y=\"48\">T+</text><text x=\"144\" y=\"48\">R+</text><text x=\"197\" y=\"48\">P−</text><text x=\"122\" y=\"102\">Q+</text><text x=\"171\" y=\"102\">U+</text><text x=\"220\" y=\"102\">S−</text></g><text x=\"146\" y=\"129\" fill=\"#555\" stroke=\"none\" font-size=\"10\" text-anchor=\"middle\">+ Male  − Female  — Sibling  = Couple  | Generation</text></svg><br>Q, U and S are the children of P and R, so P has 3 children.<br><br><b>Hence, the correct answer is option (3): 3.</b>","hi":"<svg width=\"293\" height=\"134\" viewBox=\"0 0 293 134\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><g fill=\"#fff3c4\" stroke=\"#e0a000\"><rect x=\"184\" y=\"34\" width=\"27\" height=\"20\" rx=\"4\"/></g><path d=\"M160 40H182M160 44H182M171 44V76M122 76H220M122 76V88M171 76V88M220 76V88M73 24H144M73 24V34M144 24V34\"/><g fill=\"#000\" stroke=\"none\" text-anchor=\"middle\"><text x=\"73\" y=\"48\">T+</text><text x=\"144\" y=\"48\">R+</text><text x=\"197\" y=\"48\">P−</text><text x=\"122\" y=\"102\">Q+</text><text x=\"171\" y=\"102\">U+</text><text x=\"220\" y=\"102\">S−</text></g><text x=\"146\" y=\"129\" fill=\"#555\" stroke=\"none\" font-size=\"10\" text-anchor=\"middle\">+ पुरुष  − स्त्री  — भाई-बहन  = पति-पत्नी  | पीढ़ी</text></svg><br>Q, U तथा S, P और R की संतान हैं, अतः P की 3 संतानें हैं।<br><br><b>अतः सही उत्तर विकल्प (3): 3 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":14,"local_id":"50014","quid":"Q1000070794","section":"REASONING","topic":"Miscellaneous","question":{"en":"A coding system assigns centre IDs where the cube of the first digit must equal the last two digits. Identify the invalid centre ID. [SSC CGL 28/10/26 Shift 2]","hi":"एक कूट प्रणाली ऐसे केंद्र आईडी देती है जिनमें पहले अंक का घन अंतिम दो अंकों के बराबर होना चाहिए। अमान्य केंद्र आईडी पहचानिए। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"2-08"},"2":{"en":"3-27"},"3":{"en":"4-64"},"4":{"en":"5-15"}},"answer":"4","solution":{"en":"2³ = 8, which is written as 08 ✔; 3³ = 27 ✔ and 4³ = 64 ✔<br>5³ = 125, whose last two digits are 25, but the code shows 15 ✘<br>So 5-15 is the invalid centre ID<br><br><b>Hence, the correct answer is option (4): 5-15.</b>","hi":"2³ = 8, जिसे 08 लिखा जाता है ✔; 3³ = 27 ✔ तथा 4³ = 64 ✔<br>5³ = 125 है, जिसके अंतिम दो अंक 25 हैं, परंतु कूट में 15 है ✘<br>अतः 5-15 अमान्य केंद्र आईडी है<br><br><b>अतः सही उत्तर विकल्प (4): 5-15 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":15,"local_id":"50015","quid":"Q1000070795","section":"REASONING","topic":"Missing Number","question":{"en":"In the following question, a matrix of numbers is given. These numbers follow a certain pattern either row-wise or column-wise. Identify this pattern and choose the missing number accordingly.<br><table style=\"border-collapse:collapse\"><tr><td style=\"border:1px solid #888;padding:3px 6px\">5</td><td style=\"border:1px solid #888;padding:3px 6px\">2</td><td style=\"border:1px solid #888;padding:3px 6px\">3</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">10</td><td style=\"border:1px solid #888;padding:3px 6px\">8</td><td style=\"border:1px solid #888;padding:3px 6px\">9</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">20</td><td style=\"border:1px solid #888;padding:3px 6px\">4</td><td style=\"border:1px solid #888;padding:3px 6px\">27</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">?</td><td style=\"border:1px solid #888;padding:3px 6px\">4</td><td style=\"border:1px solid #888;padding:3px 6px\">9</td></tr></table> [SSC CGL 28/10/26 Shift 2]","hi":"निम्नलिखित प्रश्न में संख्याओं का एक आव्यूह दिया गया है। ये संख्याएँ पंक्ति-वार या स्तंभ-वार किसी निश्चित पैटर्न का पालन करती हैं। इस पैटर्न को पहचानिए और उसके अनुसार लुप्त संख्या चुनिए।<br><table style=\"border-collapse:collapse\"><tr><td style=\"border:1px solid #888;padding:3px 6px\">5</td><td style=\"border:1px solid #888;padding:3px 6px\">2</td><td style=\"border:1px solid #888;padding:3px 6px\">3</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">10</td><td style=\"border:1px solid #888;padding:3px 6px\">8</td><td style=\"border:1px solid #888;padding:3px 6px\">9</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">20</td><td style=\"border:1px solid #888;padding:3px 6px\">4</td><td style=\"border:1px solid #888;padding:3px 6px\">27</td></tr><tr><td style=\"border:1px solid #888;padding:3px 6px\">?</td><td style=\"border:1px solid #888;padding:3px 6px\">4</td><td style=\"border:1px solid #888;padding:3px 6px\">9</td></tr></table> [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"5"},"2":{"en":"10"},"3":{"en":"20"},"4":{"en":"15"}},"answer":"2","solution":{"en":"Reading the matrix column-wise, every column is multiplied by the same number twice and is then brought back to the value of its second entry<br>Column I: 5 × 2 = 10 and 10 × 2 = 20, so the fourth entry is 20 ÷ 2 = 10 ✔<br>Column III: 3 × 3 = 9 and 9 × 3 = 27, and 27 ÷ 3 = 9 matches the fourth entry ✔<br>So the same step in the first column gives 10 as the missing number<br>Hence the missing number is 10<br><br><b>Hence, the correct answer is option (2): 10.</b>","hi":"आव्यूह को स्तंभ-वार पढ़ने पर प्रत्येक स्तंभ को दो बार उसी संख्या से गुणा किया जाता है और फिर उसे अपने दूसरे पद के मान पर लौटाया जाता है<br>स्तंभ I: 5 × 2 = 10 तथा 10 × 2 = 20, अतः चौथा पद 20 ÷ 2 = 10 है ✔<br>स्तंभ III: 3 × 3 = 9 तथा 9 × 3 = 27, और 27 ÷ 3 = 9 चौथे पद से मेल खाता है ✔<br>अतः पहले स्तंभ में वही चरण लुप्त संख्या 10 देता है<br>इसलिए लुप्त संख्या 10 है<br><br><b>अतः सही उत्तर विकल्प (2): 10 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":16,"local_id":"50016","quid":"Q1000070796","section":"REASONING","topic":"Letter & Alphanumeric Series","question":{"en":"Study the pattern in the given series and find the next set of letters in the series.<br>RIS, VHW, ZGA, ? [SSC CGL 28/10/26 Shift 2]","hi":"दी गई श्रेणी का पैटर्न जाँचिए और श्रेणी में अगला अक्षर-समूह ज्ञात कीजिए।<br>RIS, VHW, ZGA, ? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"DFE"},"2":{"en":"DDF"},"3":{"en":"DFD"},"4":{"en":"DFC"}},"answer":"1","solution":{"en":"The first letters R, V, Z move four places ahead each time, so the next first letter is D<br>The second letters I, H, G move one place back each time, so the next second letter is F<br>The third letters S, W, A move four places ahead each time, so after A the next third letter is E<br>Hence the next set of letters is DFE<br><br><b>Hence, the correct answer is option (1): DFE.</b>","hi":"पहले अक्षर R, V, Z प्रत्येक बार चार स्थान आगे बढ़ते हैं, अतः अगला पहला अक्षर D है<br>दूसरे अक्षर I, H, G प्रत्येक बार एक स्थान पीछे जाते हैं, अतः अगला दूसरा अक्षर F है<br>तीसरे अक्षर S, W, A प्रत्येक बार चार स्थान आगे बढ़ते हैं, अतः A के बाद अगला तीसरा अक्षर E है<br>इसलिए अगला अक्षर-समूह DFE है<br><br><b>अतः सही उत्तर विकल्प (1): DFE है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":17,"local_id":"50017","quid":"Q1000070797","section":"REASONING","topic":"Situational Judgement","question":{"en":"A highly valued, long-term client angrily threatens to cancel a &#8377;5,00,000 procurement contract due to a minor delivery delay that was entirely out of your team's control. Which action demonstrates the highest level of cognitive empathy and relationship management? [SSC CGL 28/10/26 Shift 2]","hi":"एक अत्यंत महत्वपूर्ण दीर्घकालिक ग्राहक एक छोटी डिलीवरी देरी के कारण, जो पूरी तरह आपकी टीम के नियंत्रण से बाहर थी, क्रोधित होकर 5,00,000 रुपये का खरीद अनुबंध रद्द करने की धमकी देता है। कौन-सी कार्यवाही सर्वोच्च स्तर की संज्ञानात्मक सहानुभूति तथा संबंध प्रबंधन दर्शाती है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Defend the team's efforts by explaining the external reasons for the delay.","hi":"देरी के बाहरी कारण बताकर टीम के प्रयासों का बचाव करना।"},"2":{"en":"Validate the client's frustration and collaboratively negotiate a revised timeline.","hi":"ग्राहक की नाराज़गी को मान्यता देना और सहयोगपूर्वक संशोधित समय-सीमा पर बातचीत करना।"},"3":{"en":"Immediately offer a financial discount to prevent the contract cancellation.","hi":"अनुबंध रद्द होने से बचाने के लिए तुरंत वित्तीय छूट देना।"},"4":{"en":"Transfer the hostile client directly to the legal and compliance department.","hi":"क्रोधित ग्राहक को सीधे कानूनी तथा अनुपालन विभाग को भेज देना।"}},"answer":"2","solution":{"en":"The client's anger is real even though the delay was not the team's fault, so arguing about the cause only increases the conflict<br>Accepting the frustration and then working together on a new timeline shows that the client's position is understood and gives a practical way forward<br>Giving a discount at once gives away money without solving anything, and passing the client to legal ends the relationship<br>So validating the frustration and negotiating a revised timeline is the highest level of cognitive empathy and relationship management<br><br><b>Hence, the correct answer is option (2): Validate the client's frustration and collaboratively negotiate a revised timeline.</b>","hi":"ग्राहक का क्रोध वास्तविक है, भले ही देरी टीम की गलती न हो, अतः कारण पर बहस करना केवल टकराव बढ़ाता है<br>नाराज़गी को स्वीकार करके फिर नई समय-सीमा पर साथ मिलकर बात करना दर्शाता है कि ग्राहक की स्थिति समझी गई है और आगे का व्यावहारिक रास्ता भी देता है<br>तुरंत छूट देना बिना समस्या सुलझाए धन खोना है, तथा ग्राहक को कानूनी विभाग भेजना संबंध समाप्त करना है<br>अतः नाराज़गी को मान्यता देकर संशोधित समय-सीमा पर बातचीत करना संज्ञानात्मक सहानुभूति तथा संबंध प्रबंधन का सर्वोच्च स्तर है<br><br><b>अतः सही उत्तर विकल्प (2): ग्राहक की नाराज़गी को मान्यता देना और सहयोगपूर्वक संशोधित समय-सीमा पर बातचीत करना। है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":18,"local_id":"50018","quid":"Q1000070798","section":"REASONING","topic":"Address/Sentence Matching","question":{"en":"Choose the option which is exactly similar to: 15-08-2026, Flat 302, Anant Residency, Dhole Patil Road, Pune-411001 [SSC CGL 28/10/26 Shift 2]","hi":"उस विकल्प को चुनिए जो ठीक इसके समान है: 15-08-2026, Flat 302, Anant Residency, Dhole Patil Road, Pune-411001 [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"15-08-2026, Flat 302, Anant Residency, Dhole Patil Road, Pune-411001"},"2":{"en":"15-07-2026, Flat 302, Anant Residency, Dhole Patil Road, Pune-411001"},"3":{"en":"25-08-2026, Flat 302, Anant Residency, Dhole Patil Road, Pune-411001"},"4":{"en":"15-08-2026, Flat 320, Anant Residency, Dhole Patil Road, Pune-411001"}},"answer":"1","solution":{"en":"The given address has the date 15-08-2026, the flat number 302 and the pin code 411001<br>The second option changes the month to 07, the third changes the day to 25 and the fourth changes the flat number to 320<br>Only the first option matches every part of the given address<br>Hence the first option is exactly similar<br><br><b>Hence, the correct answer is option (1): 15-08-2026, Flat 302, Anant Residency, Dhole Patil Road, Pune-411001.</b>","hi":"दिए गए पते में तिथि 15-08-2026, फ्लैट संख्या 302 तथा पिन कोड 411001 है<br>दूसरे विकल्प में महीना 07 है, तीसरे में दिन 25 है तथा चौथे में फ्लैट संख्या 320 है<br>केवल पहला विकल्प दिए गए पते के प्रत्येक भाग से मेल खाता है<br>अतः पहला विकल्प ठीक इसके समान है<br><br><b>अतः सही उत्तर विकल्प (1): 15-08-2026, Flat 302, Anant Residency, Dhole Patil Road, Pune-411001 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":19,"local_id":"50019","quid":"Q1000070799","section":"REASONING","topic":"Letter/Alphabetical Analogy","question":{"en":"What should come in place of the question mark (?) in the following analogy?<br>ACEG : IKMO :: QSUW : ? [SSC CGL 28/10/26 Shift 2]","hi":"निम्नलिखित सादृश्य में प्रश्नवाचक चिह्न (?) के स्थान पर क्या आएगा?<br>ACEG : IKMO :: QSUW : ? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"YWAC"},"2":{"en":"YXAC"},"3":{"en":"YACE"},"4":{"en":"ZWAC"}},"answer":"3","solution":{"en":"The two groups are placed at the same distance in the alphabet: A&#8594;I, C&#8594;K, E&#8594;M and G&#8594;O all move eight places ahead, and the one-letter gap inside a group is kept<br>Applying the same eight-place step to QSUW: Q&#8594;Y, S&#8594;A, U&#8594;C and W&#8594;E, counting ahead of Z<br>So the answer is YACE<br><br><b>Hence, the correct answer is option (3): YACE.</b>","hi":"दोनों समूह वर्णमाला में समान दूरी पर हैं: A&#8594;I, C&#8594;K, E&#8594;M तथा G&#8594;O सभी आठ स्थान आगे जाते हैं और समूह के भीतर एक अक्षर का अंतर बना रहता है<br>QSUW पर वही आठ स्थान का चरण लगाने से Q&#8594;Y, S&#8594;A, U&#8594;C तथा W&#8594;E, Z के आगे गिनते हुए<br>अतः उत्तर YACE है<br><br><b>अतः सही उत्तर विकल्प (3): YACE है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":20,"local_id":"50020","quid":"Q1000070800","section":"REASONING","topic":"Situational Judgement","question":{"en":"During a department-wide strategy meeting, a senior executive makes a sharp, sarcastic joke at the expense of a newly hired junior team member. The entire room bursts into laughter, and the junior colleague laughs along with them. However, right after the laughter stops, you notice the junior colleague briefly flinches, breaks eye contact, and stares down at their notebook for the rest of the session.<br>Which of the following responses demonstrates the highest level of emotional intelligence (EQ)? [SSC CGL 28/10/26 Shift 2]","hi":"एक विभागव्यापी रणनीति बैठक में एक वरिष्ठ अधिकारी नवनियुक्त कनिष्ठ टीम सदस्य की कीमत पर तीखा, व्यंग्यपूर्ण मज़ाक करता है। पूरा कक्ष हँस पड़ता है और वह कनिष्ठ सहकर्मी भी उनके साथ हँसता है। परंतु हँसी रुकने के तुरंत बाद आप देखते हैं कि वह कनिष्ठ सहकर्मी क्षण भर के लिए सिकुड़ता है, आँखें चुरा लेता है और शेष सत्र में अपनी नोटबुक में देखता रहता है।<br>निम्नलिखित में से कौन-सी प्रतिक्रिया भावनात्मक बुद्धिमत्ता (EQ) का उच्चतम स्तर दर्शाती है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Disregard the incident completely because the room's collective laughter and the junior colleague's participation prove that no real harm was done.","hi":"घटना को पूरी तरह अनदेखा करना क्योंकि कक्ष की सामूहिक हँसी तथा कनिष्ठ सहकर्मी की भागीदारी सिद्ध करती है कि कोई वास्तविक हानि नहीं हुई।"},"2":{"en":"Immediately interrupt the meeting to loudly accuse the senior executive of workplace bullying to defend the junior colleague's honour.","hi":"कनिष्ठ सहकर्मी के सम्मान की रक्षा के लिए बैठक को तुरंत रोककर वरिष्ठ अधिकारी पर ज़ोर से कार्यस्थल उत्पीड़न का आरोप लगाना।"},"3":{"en":"Observe the mismatch between their social laughter and withdrawn body language, and find a private, safe moment after the meeting to check in on them.","hi":"सामाजिक हँसी तथा सिकुड़ी हुई भंगिमा के बीच के अंतर को पहचानना और बैठक के बाद निजी, सुरक्षित समय में उनका हाल जानना।"},"4":{"en":"Approach the junior colleague during a lunch break and explicitly advise them to be less sensitive if they want to survive in a highly competitive corporate culture.","hi":"दोपहर के भोजन के समय कनिष्ठ सहकर्मी के पास जाकर स्पष्ट सलाह देना कि अत्यधिक प्रतिस्पर्धी कॉर्पोरेट संस्कृति में टिकने के लिए उन्हें कम संवेदनशील होना चाहिए।"}},"answer":"3","solution":{"en":"The junior colleague laughed only because everyone else did, and the flinch and the withdrawn posture afterwards show that the joke did hurt<br>Ignoring this misses the harm, accusing the senior loudly in front of everyone creates a new conflict and embarrasses the junior further, and advising them to be less sensitive blames the person who was hurt<br>Noticing the gap between the public laughter and the private body language and then checking on them quietly protects their dignity and offers real support<br>So the third response shows the highest emotional intelligence<br><br><b>Hence, the correct answer is option (3): Observe the mismatch between their social laughter and withdrawn body language, and find a private, safe moment after the meeting to check in on them.</b>","hi":"कनिष्ठ सहकर्मी ने केवल इसलिए हँसी की क्योंकि बाकी सब हँस रहे थे, और बाद में सिकुड़ना तथा सिमटी भंगिमा दर्शाते हैं कि मज़ाक ने वास्तव में चोट पहुँचाई<br>इसे अनदेखा करने से हानि छूट जाती है, सबके सामने वरिष्ठ पर ज़ोर से आरोप लगाने से नया टकराव बनता है और कनिष्ठ और असहज होता है, तथा कम संवेदनशील होने की सलाह देने से पीड़ित व्यक्ति को ही दोष मिलता है<br>सार्वजनिक हँसी और निजी भंगिमा के अंतर को पहचानकर चुपचाप हाल जानना उनकी गरिमा बचाता है और वास्तविक सहयोग देता है<br>अतः तीसरी प्रतिक्रिया भावनात्मक बुद्धिमत्ता का उच्चतम स्तर दर्शाती है<br><br><b>अतः सही उत्तर विकल्प (3): सामाजिक हँसी तथा सिकुड़ी हुई भंगिमा के बीच के अंतर को पहचानना और बैठक के बाद निजी, सुरक्षित समय में उनका हाल जानना। है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":21,"local_id":"50021","quid":"Q1000070801","section":"REASONING","topic":"Eligibility","question":{"en":"Read the eligibility criteria given for the post carefully and answer the question that follows.<br><b>Eligibility Criteria for Bank Probationary Officer (PO):</b><br>1. Must be a Graduate with at least 60% aggregate.<br>2. Age limit: 21–30 years.<br>3. Must possess basic computer knowledge.<br><b>Case:</b> Simran is 24 years old, a graduate with 58% marks, and has a computer certificate.<br>What should be done in Simran's case? [SSC CGL 28/10/26 Shift 2]","hi":"पद के लिए दी गई पात्रता शर्तें ध्यान से पढ़िए और आगे दिए प्रश्न का उत्तर दीजिए।<br><b>बैंक प्रोबेशनरी ऑफ़िसर (PO) के लिए पात्रता शर्तें:</b><br>1. स्नातक होना चाहिए और न्यूनतम 60% कुल अंक होने चाहिए।<br>2. आयु सीमा: 21–30 वर्ष।<br>3. बुनियादी कंप्यूटर ज्ञान होना चाहिए।<br><b>मामला:</b> सिमरन 24 वर्ष की है, 58% अंकों के साथ स्नातक है और उसके पास कंप्यूटर प्रमाणपत्र है।<br>सिमरन के मामले में क्या किया जाना चाहिए? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Eligible","hi":"पात्र"},"2":{"en":"Not Eligible (Marks less)","hi":"अपात्र (अंक कम)"},"3":{"en":"Not Eligible (Age less)","hi":"अपात्र (आयु कम)"},"4":{"en":"Not Eligible (Computer knowledge lacking)","hi":"अपात्र (कंप्यूटर ज्ञान नहीं)"}},"answer":"2","solution":{"en":"Simran is 24 years old and lies within the age limit of 21 to 30 years, so the age condition is satisfied<br>She holds a computer certificate, so the computer knowledge condition is also satisfied<br>Her graduation marks are 58%, which is below the required 60%, so the marks condition fails<br>Hence she is not eligible because her marks are less<br><br><b>Hence, the correct answer is option (2): Not Eligible (Marks less).</b>","hi":"सिमरन 24 वर्ष की है और 21 से 30 वर्ष की आयु सीमा में है, अतः आयु की शर्त पूरी होती है<br>उसके पास कंप्यूटर प्रमाणपत्र है, अतः कंप्यूटर ज्ञान की शर्त भी पूरी होती है<br>उसके स्नातक अंक 58% हैं, जो आवश्यक 60% से कम हैं, अतः अंकों की शर्त पूरी नहीं होती<br>इसलिए वह अंक कम होने के कारण अपात्र है<br><br><b>अतः सही उत्तर विकल्प (2): अपात्र (अंक कम) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":22,"local_id":"50022","quid":"Q1000070802","section":"REASONING","topic":"Eligibility","question":{"en":"Read the given conditions carefully and determine the appropriate outcome for the case provided. If any exception applies, identify the authority to whom the case should be referred.<br><b>Criteria for a manager position:</b><br>1. Age requirement: 25 to 35 years on 01.01.2026.<br>2. Qualification: Graduate from any institution with at least 60 percent marks.<br>3. Experience: 2 years of work experience in the related field.<br><b>Exception:</b> If a candidate does not meet the qualification criteria but has 5+ years of experience, the case is referred to the HR Head.<br><b>Case:</b> Rohan was born on 15.05.1995. He is a graduate with 55% marks and has 6 years of experience. [SSC CGL 28/10/26 Shift 2]","hi":"दी गई शर्तें ध्यान से पढ़िए और दिए गए मामले के लिए उपयुक्त परिणाम निर्धारित कीजिए। यदि कोई अपवाद लागू होता है, तो वह प्राधिकारी पहचानिए जिसे मामला भेजा जाना चाहिए।<br><b>प्रबंधक पद के लिए मानदंड:</b><br>1. आयु शर्त: 01.01.2026 को 25 से 35 वर्ष।<br>2. योग्यता: किसी भी संस्थान से स्नातक, न्यूनतम 60 प्रतिशत अंकों के साथ।<br>3. अनुभव: संबंधित क्षेत्र में 2 वर्ष का कार्य अनुभव।<br><b>अपवाद:</b> यदि अभ्यर्थी योग्यता मानदंड पूरा नहीं करता परंतु उसके पास 5+ वर्ष का अनुभव है, तो मामला मानव संसाधन प्रमुख को भेजा जाता है।<br><b>मामला:</b> रोहन का जन्म 15.05.1995 को हुआ। वह 55% अंकों के साथ स्नातक है और उसके पास 6 वर्ष का अनुभव है। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Selected","hi":"चयनित"},"2":{"en":"Not selected","hi":"अचयनित"},"3":{"en":"Data inadequate to make any decision","hi":"निर्णय के लिए डेटा अपर्याप्त"},"4":{"en":"Referred to HR Head","hi":"मानव संसाधन प्रमुख को भेजा गया"}},"answer":"4","solution":{"en":"On 01.01.2026 Rohan is 30 years old, which is within the age limit of 25 to 35 years, so the age condition is satisfied<br>His experience of 6 years is more than the required 2 years, so the experience condition is satisfied<br>His marks are 55%, which is less than the required 60%, so the qualification condition fails, but he has more than 5 years of experience and the exception covers exactly this case<br>Hence the case must be referred to the HR Head<br><br><b>Hence, the correct answer is option (4): Referred to HR Head.</b>","hi":"01.01.2026 को रोहन 30 वर्ष का है, जो 25 से 35 वर्ष की आयु सीमा में है, अतः आयु की शर्त पूरी होती है<br>उसका 6 वर्ष का अनुभव आवश्यक 2 वर्ष से अधिक है, अतः अनुभव की शर्त पूरी होती है<br>उसके अंक 55% हैं, जो आवश्यक 60% से कम हैं, अतः योग्यता की शर्त पूरी नहीं होती, परंतु उसके पास 5 वर्ष से अधिक अनुभव है और अपवाद ठीक इसी स्थिति के लिए है<br>इसलिए मामला मानव संसाधन प्रमुख को भेजा जाना चाहिए<br><br><b>अतः सही उत्तर विकल्प (4): मानव संसाधन प्रमुख को भेजा गया है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":23,"local_id":"50023","quid":"Q1000070803","section":"REASONING","topic":"Statement & Conclusion","question":{"en":"Read the statement carefully and assume it to be true. Then examine the two conclusions given below it and decide which conclusion(s), if any, logically follow from the statement.<br><b>Statement:</b><br>A technology firm has upgraded its cloud infrastructure and expanded server capacity to accommodate rapidly increasing user demand across its digital platforms.<br><b>Conclusions:</b><br>I. The firm anticipates continued growth in user traffic.<br>II. Existing infrastructure was insufficient to handle peak demand. [SSC CGL 28/10/26 Shift 2]","hi":"कथन को ध्यान से पढ़िए और उसे सत्य मानिए। फिर उसके नीचे दिए दो निष्कर्षों की जाँच कीजिए और निर्णय कीजिए कि कौन-सा/से निष्कर्ष कथन से तार्किक रूप से निकलता/निकलते हैं।<br><b>कथन:</b><br>एक प्रौद्योगिकी कंपनी ने अपने डिजिटल मंचों पर तेज़ी से बढ़ती उपयोगकर्ता माँग को पूरा करने के लिए अपनी क्लाउड अवसंरचना उन्नत की है तथा सर्वर क्षमता बढ़ाई है।<br><b>निष्कर्ष:</b><br>I. कंपनी उपयोगकर्ता ट्रैफ़िक में निरंतर वृद्धि की अपेक्षा करती है।<br>II. पर्याप्त अवसंरचना चरम माँग संभालने के लिए अपर्याप्त थी। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Only conclusion I follows","hi":"केवल निष्कर्ष I निकलता है"},"2":{"en":"Both conclusions I and II follow","hi":"निष्कर्ष I और II दोनों निकलते हैं"},"3":{"en":"Only conclusion II follows","hi":"केवल निष्कर्ष II निकलता है"},"4":{"en":"Neither conclusion I nor conclusion II follows","hi":"न तो निष्कर्ष I और न ही निष्कर्ष II निकलता है"}},"answer":"2","solution":{"en":"The company expands capacity to accommodate rapidly increasing demand, which shows that it expects the number of users to keep growing, so I follows<br>Capacity was expanded because the existing set-up could not carry the peak load, so II also follows<br>Hence both conclusions follow<br><br><b>Hence, the correct answer is option (2): Both conclusions I and II follow.</b>","hi":"कंपनी तेज़ी से बढ़ती माँग को पूरा करने के लिए क्षमता बढ़ाती है, जिससे दिखता है कि वह उपयोगकर्ताओं की संख्या बढ़ते रहने की अपेक्षा करती है, अतः I निकलता है<br>क्षमता इसलिए बढ़ाई गई कि मौजूदा व्यवस्था चरम भार नहीं उठा सकती थी, अतः II भी निकलता है<br>इसलिए दोनों निष्कर्ष निकलते हैं<br><br><b>अतः सही उत्तर विकल्प (2): निष्कर्ष I और II दोनों निकलते हैं है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":24,"local_id":"50024","quid":"Q1000070804","section":"REASONING","topic":"Statement, Assumption & Argument","question":{"en":"Read the given statement carefully and the following assumptions based on it. Decide which of the assumptions are implicit in the statement.<br><b>Statement:</b><br>The railway department has announced that passengers must book their tickets at least 48 hours in advance to avoid last-minute cancellations and overcrowding.<br><b>Assumptions:</b><br>I. Advance booking will help the authorities manage passenger volume more efficiently.<br>II. Most passengers prefer to travel without planning their journeys in advance. [SSC CGL 28/10/26 Shift 2]","hi":"दिया गया कथन तथा उस पर आधारित निम्नलिखित अवधारणाएँ ध्यान से पढ़िए और निर्णय कीजिए कि कौन-सी अवधारणाएँ कथन में निहित हैं।<br><b>कथन:</b><br>रेलवे विभाग ने घोषित किया है कि अंतिम समय की रद्दीकरण तथा भीड़ से बचने के लिए यात्रियों को कम से कम 48 घंटे पहले टिकट बुक करना होगा।<br><b>अवधारणाएँ:</b><br>I. पहले से बुकिंग करने से प्राधिकरण यात्री संख्या का अधिक कुशलता से प्रबंधन कर पाएँगे।<br>II. अधिकांश यात्री यात्रा की योजना पहले से बनाए बिना ही यात्रा करना पसंद करते हैं। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Only Assumption I is implicit","hi":"केवल अवधारणा I निहित है"},"2":{"en":"Only Assumption II is implicit","hi":"केवल अवधारणा II निहित है"},"3":{"en":"Both Assumptions I and II are implicit","hi":"अवधारणा I और II दोनों निहित हैं"},"4":{"en":"Neither Assumption I nor II is implicit","hi":"न तो अवधारणा I और न ही II निहित है"}},"answer":"1","solution":{"en":"The rule asks for booking 48 hours ahead so that cancellations and crowding come down, which is possible only if advance booking really helps the authorities manage the rush, so assumption I is implicit<br>The statement does not say anything about what most passengers prefer, so assumption II is not implicit<br>Hence only assumption I is implicit<br><br><b>Hence, the correct answer is option (1): Only Assumption I is implicit.</b>","hi":"नियम 48 घंटे पहले बुकिंग इसलिए कहता है कि रद्दीकरण तथा भीड़ कम हो, जो तभी संभव है जब पहले से बुकिंग से प्राधिकरण को भीड़ प्रबंधन में सहायता मिले, अतः अवधारणा I निहित है<br>कथन यह नहीं कहता कि अधिकांश यात्री क्या पसंद करते हैं, अतः अवधारणा II निहित नहीं है<br>इसलिए केवल अवधारणा I निहित है<br><br><b>अतः सही उत्तर विकल्प (1): केवल अवधारणा I निहित है है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":25,"local_id":"50025","quid":"Q1000070805","section":"REASONING","topic":"Word Analogy","question":{"en":"Select the option that is related to the third word in the same way as the second word is related to the first word. (The words must be considered as meaningful English words and must not be related to each other based on the number of letters/number of consonants/vowels in the word.)<br>Amused : Ecstatic :: Annoyed : ? [SSC CGL 28/10/26 Shift 2]","hi":"उस विकल्प का चयन कीजिए जो तीसरे शब्द से उसी प्रकार संबंधित है जिस प्रकार दूसरा शब्द पहले शब्द से संबंधित है। (शब्दों को अर्थपूर्ण अंग्रेज़ी शब्द मानना है और उनके अक्षरों की संख्या/व्यंजनों/स्वरों की संख्या के आधार पर परस्पर संबंध नहीं मानना है।)<br>Amused : Ecstatic :: Annoyed : ? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Irritated","hi":"चिढ़ा हुआ"},"2":{"en":"Livid","hi":"अत्यंत क्रुद्ध"},"3":{"en":"Upset","hi":"व्यथित"},"4":{"en":"Bothered","hi":"परेशान"}},"answer":"2","solution":{"en":"Amused means pleased and ecstatic means extremely pleased, so the pair shows a feeling and its much stronger form<br>Livid means extremely angry, which is the much stronger form of annoyed, so it fits the same relation<br>Irritated, upset and bothered are all milder forms and do not show this rise in intensity<br>Hence the answer is Livid<br><br><b>Hence, the correct answer is option (2): Livid.</b>","hi":"Amused का अर्थ प्रसन्न तथा Ecstatic का अर्थ अत्यधिक प्रसन्न है, अतः युग्म एक भावना और उसका बहुत तीव्र रूप दर्शाता है<br>Livid का अर्थ अत्यंत क्रुद्ध है, जो Annoyed का बहुत तीव्र रूप है और उसी संबंध में बैठता है<br>Irritated, Upset तथा Bothered सभी हल्के रूप हैं और तीव्रता की यह वृद्धि नहीं दर्शाते<br>अतः उत्तर Livid है<br><br><b>अतः सही उत्तर विकल्प (2): अत्यंत क्रुद्ध है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false}]},"GK":{"seconds":900,"questions":[{"no":26,"local_id":"50026","quid":"Q1000070806","section":"GK","topic":"Static GK: International Organisations","question":{"en":"The New Development Bank (NDB), established by BRICS, has its headquarters in which city? [SSC CGL 28/10/26 Shift 2]","hi":"ब्रिक्स (BRICS) द्वारा स्थापित न्यू डेवलपमेंट बैंक (NDB) का मुख्यालय किस शहर में है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"New Delhi, India","hi":"नई दिल्ली, भारत"},"2":{"en":"Moscow, Russia","hi":"मॉस्को, रूस"},"3":{"en":"Shanghai, China","hi":"शंघाई, चीन"},"4":{"en":"Cape Town, South Africa","hi":"केप टाउन, दक्षिण अफ्रीका"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Shanghai, China</b><br>The <b>New Development Bank (NDB)</b>, set up by the <b>BRICS</b> countries, has its headquarters at <b>Shanghai in China</b>.<br><br><br><b><u>Important Points:</u></b><br>• The bank was announced at the <b>6th BRICS Summit at Fortaleza (Brazil) in July 2014</b> and began operations in <b>2015</b>.<br>• It was created with an authorised capital of <b>USD 100 billion</b> and subscribed capital of <b>USD 50 billion</b>, shared equally by the five founders.<br>• Its <b>first President was K. V. Kamath</b> of India; the current President is <b>Dilma Rousseff</b> of Brazil, and an African regional centre works from Johannesburg.<br>• The NDB is also called the <b>BRICS Development Bank</b>; Bangladesh, the UAE, Egypt and Uruguay have since joined it.","hi":"<b>सही उत्तर: विकल्प (3) – शंघाई, चीन</b><br><b>ब्रिक्स</b> देशों द्वारा स्थापित <b>न्यू डेवलपमेंट बैंक (NDB)</b> का मुख्यालय <b>चीन के शंघाई</b> में है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• इस बैंक की घोषणा <b>जुलाई 2014 में फोर्टालेजा (ब्राजील) के छठे ब्रिक्स शिखर सम्मेलन</b> में हुई और इसने <b>2015</b> में कार्य आरंभ किया।<br>• इसकी अधिकृत पूंजी <b>100 अरब अमेरिकी डॉलर</b> तथा अभिदत्त पूंजी <b>50 अरब डॉलर</b> है, जिसमें पाँच संस्थापकों का समान अंश है।<br>• इसके <b>प्रथम अध्यक्ष के. वी. कामथ</b> (भारत) थे; वर्तमान अध्यक्ष ब्राजील की <b>दिल्मा रूसेफ</b> हैं तथा अफ्रीकी क्षेत्रीय केंद्र जोहान्सबर्ग से कार्य करता है।<br>• एनडीबी को <b>ब्रिक्स विकास बैंक</b> भी कहा जाता है; बाद में बांग्लादेश, संयुक्त अरब अमीरात, मिस्र तथा उरुग्वे भी इसके सदस्य बने।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":27,"local_id":"50027","quid":"Q1000070807","section":"GK","topic":"Current Affairs: International News","question":{"en":"What is the name of the port in Pakistan that is seen as a competitor to Chabahar port? [SSC CGL 28/10/26 Shift 2]","hi":"पाकिस्तान में किस बंदरगाह को चाबहार बंदरगाह का प्रतिस्पर्धी माना जाता है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Gwadar port","hi":"ग्वादर बंदरगाह"},"2":{"en":"Karachi port","hi":"कराची बंदरगाह"},"3":{"en":"Qasim port","hi":"कासिम बंदरगाह"},"4":{"en":"Ormara port","hi":"ओरमाड़ा बंदरगाह"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – Gwadar port</b><br><b>Gwadar port</b>, on the <b>Makran coast of Balochistan province in Pakistan</b>, is projected as a rival to Iran’s <b>Chabahar port</b>, since both lie near the <b>Gulf of Oman</b> and the approach to the Strait of Hormuz.<br><br><br><b><u>Important Points:</u></b><br>• Gwadar is a <b>deep-sea, warm-water port</b> developed with Chinese assistance and is the terminal point of the <b>China-Pakistan Economic Corridor (CPEC)</b>.<br>• <b>Chabahar</b> lies in Iran’s <b>Sistan-Baluchestan province</b>; India, Iran and Afghanistan signed a trilateral transit agreement in <b>2016</b> for its development.<br>• Chabahar gives India access to <b>Afghanistan and Central Asia bypassing Pakistan</b>, and the <b>Shahid Beheshti terminal</b> is operated by India Ports Global.<br>• Gwadar’s operations were handed over to a Chinese company in <b>2013</b>, and the port is often described as part of the so-called <b>String of Pearls</b>.","hi":"<b>सही उत्तर: विकल्प (1) – ग्वादर बंदरगाह</b><br><b>पाकिस्तान के बलूचिस्तान प्रांत के मकरान तट</b> पर स्थित <b>ग्वादर बंदरगाह</b> को ईरान के <b>चाबहार बंदरगाह</b> का प्रतिद्वंद्वी माना जाता है, क्योंकि दोनों <b>ओमान की खाड़ी</b> तथा हार्मुज़ जलडमरूमध्य के समीप हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• ग्वादर <b>गहरे पानी का गर्म जलवायु वाला बंदरगाह</b> है, जिसे चीनी सहायता से विकसित किया गया है और यह <b>चीन-पाकिस्तान आर्थिक गलियारे (CPEC)</b> का अंतिम बिंदु है।<br>• <b>चाबहार</b> ईरान के <b>सिस्तान-बलूचिस्तान प्रांत</b> में है; भारत, ईरान तथा अफगानिस्तान ने इसके विकास हेतु <b>2016</b> में त्रिपक्षीय पारगमन समझौता किया।<br>• चाबहार भारत को <b>पाकिस्तान को छोड़कर अफगानिस्तान व मध्य एशिया</b> तक पहुँच देता है; <b>शाहिद बेहेश्ती टर्मिनल</b> का संचालन इंडिया पोर्ट्स ग्लोबल करता है।<br>• ग्वादर का संचालन <b>2013</b> में एक चीनी कंपनी को सौंपा गया और इस बंदरगाह को तथाकथित <b>स्ट्रिंग ऑफ पर्ल्स</b> का भाग माना जाता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":28,"local_id":"50028","quid":"Q1000070808","section":"GK","topic":"Static GK: Sports(Static & Current)","question":{"en":"How many players from each team are on a basketball court at a time? [SSC CGL 28/10/26 Shift 2]","hi":"बास्केटबॉल कोर्ट पर एक समय में प्रत्येक टीम के कितने खिलाड़ी होते हैं? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"5"},"2":{"en":"6"},"3":{"en":"7"},"4":{"en":"8"}},"answer":"1","solution":{"en":"<b>Correct Answer: Option (1) – 5</b><br>In basketball each team fields <b>five players</b> at a time, so <b>ten players</b> are on the court.<br><br><br><b><u>Important Points:</u></b><br>• A basket from inside the arc scores <b>2 points</b>, from beyond the arc <b>3 points</b>, and a free throw <b>1 point</b>.<br>• The game was invented by <b>James Naismith in 1891</b> at Springfield, USA, and is governed internationally by <b>FIBA</b>.<br>• A standard court is about <b>28 m by 15 m</b>, and a match has four quarters of <b>10 minutes</b> each under FIBA rules (12 minutes in the NBA).<br>• India’s professional league is the <b>Basketball Federation of India</b>-run national championship, and the sport entered the Olympics in <b>1936</b>.","hi":"<b>सही उत्तर: विकल्प (1) – 5</b><br>बास्केटबॉल में प्रत्येक टीम एक समय में <b>पाँच खिलाड़ी</b> मैदान में उतारती है, अर्थात् कोर्ट पर <b>दस खिलाड़ी</b> होते हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• चाप के भीतर से बास्केट पर <b>2 अंक</b>, चाप के बाहर से <b>3 अंक</b> तथा फ्री थ्रो पर <b>1 अंक</b> मिलता है।<br>• यह खेल <b>1891</b> में जेम्स नाइस्मिथ ने स्प्रिंगफील्ड (अमेरिका) में आरंभ किया; अंतर्राष्ट्रीय स्तर पर इसका संचालन <b>फीबा</b> करता है।<br>• मानक कोर्ट लगभग <b>28 मीटर गुणा 15 मीटर</b> होता है और फीबा नियमों में मैच <b>10–10 मिनट</b> के चार क्वार्टर का होता है (एनबीए में 12 मिनट)।<br>• भारत में राष्ट्रीय प्रतियोगिता <b>बास्केटबॉल फेडरेशन ऑफ इंडिया</b> द्वारा आयोजित होती है और यह खेल <b>1936</b> में ओलंपिक में शामिल हुआ।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":29,"local_id":"50029","quid":"Q1000070809","section":"GK","topic":"Static GK: Awards and Honours","question":{"en":"Who among the following authors has <b>NEVER</b> received the Sahitya Akademi Award? [SSC CGL 28/10/26 Shift 2]","hi":"निम्नलिखित लेखकों में से किसने <b>कभी</b> साहित्य अकादमी पुरस्कार प्राप्त नहीं किया? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Amitav Ghosh","hi":"अमिताव घोष"},"2":{"en":"Shashi Tharoor","hi":"शशि थरूर"},"3":{"en":"Ruskin Bond","hi":"रस्किन बॉन्ड"},"4":{"en":"Chetan Bhagat","hi":"चेतन भगत"}},"answer":"4","solution":{"en":"<b>Correct Answer: Option (4) – Chetan Bhagat</b><br><b>Chetan Bhagat</b>, known for <b>Five Point Someone</b> and <b>2 States</b>, has <b>not received</b> the Sahitya Akademi Award, while the other three authors have.<br><br><br><b><u>Important Points:</u></b><br>• The <b>Sahitya Akademi Award</b> was instituted in <b>1954</b> and is given for an outstanding literary work in one of the <b>24 languages</b> recognised by the Akademi.<br>• <b>Amitav Ghosh</b> received it in <b>1986</b> for <b>The Circle of Reason</b> and <b>Ruskin Bond</b> in <b>1992</b> for <b>Our Trees Still Grow in Dehra</b>.<br>• <b>Shashi Tharoor</b> received the award in <b>2019</b> for <b>An Era of Darkness: The British Empire in India</b>.<br>• The Sahitya Akademi is India’s <b>National Academy of Letters</b>, and its highest honour, the <b>Jnanpith</b>, is conferred by the Bharatiya Jnanpith trust, not the Akademi.","hi":"<b>सही उत्तर: विकल्प (4) – चेतन भगत</b><br><b>फाइव पॉइंट समवन</b> तथा <b>2 स्टेट्स</b> के लिए प्रसिद्ध <b>चेतन भगत</b> को साहित्य अकादमी पुरस्कार <b>नहीं</b> मिला है, जबकि शेष तीनों लेखकों को यह प्राप्त हुआ है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>साहित्य अकादमी पुरस्कार</b> <b>1954</b> में स्थापित हुआ और अकादमी द्वारा मान्यता प्राप्त <b>24 भाषाओं</b> में से किसी एक में उत्कृष्ट साहित्यिक कृति पर दिया जाता है।<br>• <b>अमिताव घोष</b> को <b>1986</b> में <b>द सर्कल ऑफ रीज़न</b> तथा <b>रस्किन बॉन्ड</b> को <b>1992</b> में <b>अवर ट्रीज़ स्टिल ग्रो इन देहरा</b> के लिए यह पुरस्कार मिला।<br>• <b>शशि थरूर</b> को <b>2019</b> में <b>एन एरा ऑफ डार्कनेस: द ब्रिटिश एम्पायर इन इंडिया</b> के लिए यह पुरस्कार प्राप्त हुआ।<br>• साहित्य अकादमी भारत की <b>राष्ट्रीय पत्र अकादमी</b> है; इसका सर्वोच्च सम्मान <b>ज्ञानपीठ</b> भारतीय ज्ञानपीठ न्यास द्वारा दिया जाता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":30,"local_id":"50030","quid":"Q1000070810","section":"GK","topic":"Static GK: Sports(Static & Current)","question":{"en":"“Pin” is a winning position in which sport? [SSC CGL 28/10/26 Shift 2]","hi":"“पिन” किस खेल में विजयी स्थिति मानी जाती है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Boxing","hi":"मुक्केबाज़ी"},"2":{"en":"Wrestling","hi":"कुश्ती"},"3":{"en":"Weightlifting","hi":"भारोत्तोलन"},"4":{"en":"Shooting","hi":"निशानेबाज़ी"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Wrestling</b><br>In <b>wrestling</b> a <b>pin</b> (also called a <b>fall</b>) is a winning position in which both shoulders of the opponent are held on the mat, ending the bout.<br><br><br><b><u>Important Points:</u></b><br>• A fall is awarded when the opponent’s shoulders are held down for about <b>two seconds</b> in freestyle and Greco-Roman wrestling.<br>• Other scoring terms are <b>takedown, escape, reversal and near fall</b>, and a bout can also be won on technical superiority or points.<br>• Wrestling was in the ancient Olympics and <b>Greco-Roman</b> featured in the first modern Games at Athens in <b>1896</b>; freestyle entered in <b>1904</b>.<br>• India’s Olympic wrestling medallists include <b>K. D. Jadhav (1952), Sushil Kumar (2008, 2012), Yogeshwar Dutt (2012), Sakshi Malik (2016)</b> and <b>Ravi Dahiya (2020)</b>.","hi":"<b>सही उत्तर: विकल्प (2) – कुश्ती</b><br><b>कुश्ती</b> में <b>पिन</b> (फॉल) एक विजयी स्थिति है, जिसमें प्रतिद्वंद्वी के दोनों कंधे मैट पर दबे रहने से बाउट समाप्त हो जाती है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• फ्रीस्टाइल तथा ग्रीको-रोमन कुश्ती में प्रतिद्वंद्वी के कंधे लगभग <b>दो सेकंड</b> तक दबे रहने पर फॉल दिया जाता है।<br>• अन्य अंकन शब्द <b>टेकडाउन, एस्केप, रिवर्सल तथा नियर फॉल</b> हैं; बाउट तकनीकी श्रेष्ठता या अंकों पर भी जीती जा सकती है।<br>• कुश्ती प्राचीन ओलंपिक में थी; <b>ग्रीको-रोमन</b> शैली <b>1896</b> के एथेंस में प्रथम आधुनिक खेलों में शामिल हुई और फ्रीस्टाइल <b>1904</b> में।<br>• भारत के ओलंपिक कुश्ती पदक विजेताओं में <b>के. डी. जाधव (1952), सुशील कुमार (2008, 2012), योगेश्वर दत्त (2012), साक्षी मलिक (2016)</b> तथा <b>रवि दहिया (2020)</b> शामिल हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":31,"local_id":"50031","quid":"Q1000070811","section":"GK","topic":"Static GK: Folk Dances and Festivals","question":{"en":"In which region is the Hemis festival, known for its vibrant masked dances, celebrated? [SSC CGL 28/10/26 Shift 2]","hi":"अपने रंगीन मुखौटा नृत्यों के लिए प्रसिद्ध हेमिस महोत्सव किस क्षेत्र में मनाया जाता है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Sikkim","hi":"सिक्किम"},"2":{"en":"Himachal Pradesh","hi":"हिमाचल प्रदेश"},"3":{"en":"Ladakh","hi":"लद्दाख"},"4":{"en":"Uttarakhand","hi":"उत्तराखंड"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Ladakh</b><br>The <b>Hemis festival</b> is celebrated at the <b>Hemis Gompa in Ladakh</b>, with <b>Cham masked dances</b> performed by monks.<br><br><br><b><u>Important Points:</u></b><br>• Hemis monastery belongs to the <b>Drukpa</b> lineage of Tibetan Buddhism and is the <b>largest and richest monastery of Ladakh</b>, founded in the 17th century.<br>• The festival marks the birth anniversary of <b>Guru Padmasambhava</b> and is held in the Tibetan lunar month, usually in <b>June or July</b>.<br>• Monks wear colourful masks and brocade robes for the <b>Cham</b> dance, and a giant <b>thangka</b> of Guru Padmasambhava is unfurled.<br>• Other famous festivals of Ladakh are <b>Losar, Phyang Tsedup and Sindhu Darshan</b>; Ladakh became a Union Territory in <b>2019</b>.","hi":"<b>सही उत्तर: विकल्प (3) – लद्दाख</b><br><b>हेमिस महोत्सव</b> <b>लद्दाख के हेमिस गोम्पा</b> में मनाया जाता है, जिसमें भिक्षु <b>चाम मुखौटा नृत्य</b> प्रस्तुत करते हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• हेमिस मठ तिब्बती बौद्ध धर्म की <b>द्रुक्पा</b> परंपरा से संबंधित है और <b>लद्दाख का सबसे बड़ा तथा समृद्ध मठ</b> है, जिसकी स्थापना 17वीं शताब्दी में हुई।<br>• यह महोत्सव <b>गुरु पद्मसंभव</b> की जयंती पर मनाया जाता है और तिब्बती चंद्र मास में, सामान्यतः <b>जून या जुलाई</b> में होता है।<br>• भिक्षु <b>चाम</b> नृत्य हेतु रंगीन मुखौटे तथा ब्रोकेड वस्त्र पहनते हैं और गुरु पद्मसंभव का विशाल <b>थंका</b> प्रदर्शित किया जाता है।<br>• लद्दाख के अन्य प्रसिद्ध महोत्सव <b>लोसर, फ्यांग त्सेदुप तथा सिंधु दर्शन</b> हैं; लद्दाख <b>2019</b> में केंद्रशासित प्रदेश बना।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":32,"local_id":"50032","quid":"Q1000070812","section":"GK","topic":"Current Affairs: Awards and Honours (Current)","question":{"en":"Who is the first Indian monk to be honored with the American President’s Volunteer Service Award? [SSC CGL 28/10/26 Shift 2]","hi":"अमेरिकी राष्ट्रपति के स्वयंसेवी सेवा पुरस्कार से सम्मानित पहला भारतीय भिक्षु कौन है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Shantisagar","hi":"शांतिसागर"},"2":{"en":"Jinendra Varni","hi":"जिनेंद्र वर्णी"},"3":{"en":"Jain Acharya Lokesh","hi":"जैन आचार्य लोकेश"},"4":{"en":"Madhvacharya","hi":"मध्वाचार्य"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Jain Acharya Lokesh</b><br><b>Jain Acharya Dr. Lokesh</b>, founder of <b>Ahimsa Vishwa Bharati</b>, became the <b>first Indian monk</b> to receive the <b>American President’s Volunteer Service Award</b>, in recognition of his work for peace and non-violence.<br><br><br><b><u>Important Points:</u></b><br>• The <b>President’s Volunteer Service Award</b> is a United States honour given to individuals for sustained voluntary service to their community.<br>• <b>Acharya Lokesh Muni</b> is known for campaigns against <b>drug addiction, female foeticide and caste discrimination</b> and for inter-faith dialogue.<br>• <b>Ahimsa Vishwa Bharati</b>, founded in <b>2010</b>, works for non-violence, harmony and social reform, and he has also been honoured with the <b>Vishwa Shanti Ratna</b> award.<br>• Other Indian recipients of international honours include <b>Kailash Satyarthi</b> (Nobel Peace Prize, 2014) and <b>Mother Teresa</b> (Nobel Peace Prize, 1979).","hi":"<b>सही उत्तर: विकल्प (3) – जैन आचार्य लोकेश</b><br><b>अहिंसा विश्व भारती</b> के संस्थापक <b>जैन आचार्य डॉ. लोकेश</b> शांति व अहिंसा के क्षेत्र में कार्य हेतु <b>अमेरिकी राष्ट्रपति के स्वयंसेवी सेवा पुरस्कार</b> से सम्मानित होने वाले <b>पहले भारतीय भिक्षु</b> बने।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>प्रेसिडेंट्स वॉलंटियर सर्विस अवार्ड</b> संयुक्त राज्य अमेरिका का सम्मान है, जो समुदाय हेतु निरंतर स्वयंसेवी सेवा पर दिया जाता है।<br>• <b>आचार्य लोकेश मुनि</b> <b>नशा मुक्ति, कन्या भ्रूण हत्या तथा जाति-भेद</b> के विरुद्ध अभियानों तथा अंतर-धार्मिक संवाद के लिए जाने जाते हैं।<br>• <b>अहिंसा विश्व भारती</b> (स्थापना <b>2010</b>) अहिंसा, सद्भाव तथा सामाजिक सुधार हेतु कार्य करती है; उन्हें <b>विश्व शांति रत्न</b> सम्मान भी मिल चुका है।<br>• अंतर्राष्ट्रीय सम्मान पाने वाले अन्य भारतीयों में <b>कैलाश सत्यार्थी</b> (नोबेल शांति पुरस्कार, 2014) तथा <b>मदर टेरेसा</b> (नोबेल शांति पुरस्कार, 1979) हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":33,"local_id":"50033","quid":"Q1000070813","section":"GK","topic":"Static GK: Miscellaneous","question":{"en":"Dalavai Kullayappa is an artist trying to revive which of the following art forms? [SSC CGL 28/10/26 Shift 2]","hi":"दलवाई कुल्लैया निम्नलिखित में से किस कला रूप को पुनर्जीवित करने का प्रयास करने वाले कलाकार हैं? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Kundhei","hi":"कुंधेई"},"2":{"en":"Putul Nach","hi":"पुतुल नाच"},"3":{"en":"Kathputli","hi":"कठपुतली"},"4":{"en":"Tholu Bommalata","hi":"तोलु बोम्मलता"}},"answer":"4","solution":{"en":"<b>Correct Answer: Option (4) – Tholu Bommalata</b><br><b>Tholu Bommalata</b> is the traditional <b>leather shadow puppetry of Andhra Pradesh</b>, and <b>Dalavai Kullayappa</b> is a noted artist working to revive it.<br><br><br><b><u>Important Points:</u></b><br>• Tholu Bommalata puppets are made of <b>goat hide</b>, coloured with vegetable dyes and made translucent so that they glow against a lamp-lit screen.<br>• Its stories are drawn mostly from the <b>Ramayana, Mahabharata and Puranas</b>, accompanied by songs and percussion.<br>• Related puppet forms are <b>Togalu Gombeyaata</b> (Karnataka), <b>Tholpavakoothu</b> (Kerala), <b>Ravanachhaya</b> (Odisha) and <b>Chamadyacha Bahulya</b> (Maharashtra).<br>• <b>Kathputli</b> is the string puppet of Rajasthan, <b>Kundhei</b> a string puppet of Odisha and <b>Putul Nach</b> the rod-and-string puppet tradition of West Bengal.","hi":"<b>सही उत्तर: विकल्प (4) – तोलु बोम्मलता</b><br><b>तोलु बोम्मलता</b> <b>आंध्र प्रदेश की पारंपरिक चमड़े की छाया कठपुतली</b> कला है और <b>दलवाई कुल्लैया</b> इसे पुनर्जीवित करने वाले प्रमुख कलाकार हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• तोलु बोम्मलता की कठपुतलियाँ <b>बकरी की खाल</b> से बनती हैं, वनस्पति रंगों से रँगी जाती हैं तथा पारभासी होती हैं जिससे दीप-प्रकाशित पर्दे पर चमकती हैं।<br>• इनकी कथाएँ मुख्यतः <b>रामायण, महाभारत तथा पुराणों</b> से ली जाती हैं, साथ में गीत व ताल-वाद्य होते हैं।<br>• संबंधित कठपुतली रूप <b>तोगालु गोम्बेयाटा</b> (कर्नाटक), <b>तोल्पावकूथु</b> (केरल), <b>रावणछाया</b> (ओडिशा) तथा <b>चमड़याचा बाहुल्या</b> (महाराष्ट्र) हैं।<br>• <b>कठपुतली</b> राजस्थान की तार-कठपुतली, <b>कुंधेई</b> ओडिशा की तार-कठपुतली तथा <b>पुतुल नाच</b> पश्चिम बंगाल की डंडी-तार कठपुतली परंपरा है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":34,"local_id":"50034","quid":"Q1000070814","section":"GK","topic":"Static GK: Sports(Static & Current)","question":{"en":"Consider the following statements about India’s participation in the <b>1936 Berlin Summer Olympics</b>:<br>1) The men’s hockey team won their third consecutive gold medal.<br>2) Rashid Anwar competed in men’s freestyle wrestling.<br>Which of the above statements are <b>correct</b>? [SSC CGL 28/10/26 Shift 2]","hi":"<b>1936 के बर्लिन ग्रीष्मकालीन ओलंपिक</b> में भारत की भागीदारी के संबंध में निम्नलिखित कथनों पर विचार करें:<br>1) पुरुष हॉकी टीम ने लगातार तीसरा स्वर्ण पदक जीता।<br>2) रशीद अनवर ने पुरुष फ्रीस्टाइल कुश्ती में भाग लिया।<br>उपर्युक्त कथनों में से कौन-से <b>सही</b> हैं? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Only 1 is Correct","hi":"केवल 1 सही है"},"2":{"en":"Only 2 is Correct","hi":"केवल 2 सही है"},"3":{"en":"1 and 2 are Correct","hi":"1 तथा 2 दोनों सही हैं"},"4":{"en":"Neither 1 nor 2 are Correct","hi":"न तो 1 और न ही 2 सही है"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – 1 and 2 are Correct</b><br>India’s <b>hockey team won its third successive Olympic gold</b> at Berlin in <b>1936</b> (after <b>1928 Amsterdam and 1932 Los Angeles</b>), and <b>Rashid Anwar</b> represented India in <b>men’s freestyle wrestling</b> at the same Games.<br><br><br><b><u>Important Points:</u></b><br>• In the <b>1936 final</b> India beat <b>Germany 8-1</b>, with <b>Dhyan Chand</b> as the star of the team.<br>• India’s hockey gold run continued in <b>1948, 1952 and 1956</b>, giving six straight Olympic titles from 1928 to 1956.<br>• The <b>1936 Berlin Games</b> were held under the Nazi regime; <b>Jesse Owens</b> of the USA won four gold medals in athletics.<br>• India’s wrestling at Berlin included <b>Rashid Anwar</b> in the welterweight class, though he did not win a medal.","hi":"<b>सही उत्तर: विकल्प (3) – 1 तथा 2 दोनों सही हैं</b><br>भारत की <b>हॉकी टीम</b> ने <b>1936</b> में बर्लिन में लगातार तीसरा ओलंपिक स्वर्ण जीता (<b>1928 एम्स्टर्डम तथा 1932 लॉस एंजिल्स</b> के बाद) और <b>रशीद अनवर</b> ने उन्हीं खेलों में <b>पुरुष फ्रीस्टाइल कुश्ती</b> में भारत का प्रतिनिधित्व किया।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>1936 के फाइनल</b> में भारत ने <b>जर्मनी को 8-1</b> से हराया, जिसमें <b>ध्यानचंद</b> टीम के प्रमुख खिलाड़ी थे।<br>• भारत का हॉकी स्वर्ण-क्रम <b>1948, 1952 तथा 1956</b> में भी जारी रहा, जिससे 1928 से 1956 तक लगातार छह ओलंपिक खिताब मिले।<br>• <b>1936 के बर्लिन खेल</b> नाजी शासन में हुए; अमेरिका के <b>जेसी ओवेन्स</b> ने एथलेटिक्स में चार स्वर्ण पदक जीते।<br>• बर्लिन में भारतीय कुश्ती में <b>रशीद अनवर</b> वेल्टरवेट वर्ग में शामिल थे, परंतु उन्हें पदक नहीं मिला।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":35,"local_id":"50035","quid":"Q1000070815","section":"GK","topic":"Polity: New Criminal Laws 2023","question":{"en":"Who must be notified during the arrest of a person under Bharatiya Nagarik Suraksha Samhita (BNSS)? [SSC CGL 28/10/26 Shift 2]","hi":"भारतीय नागरिक सुरक्षा संहिता (BNSS) के अंतर्गत किसी व्यक्ति की गिरफ्तारी के समय किसे सूचित किया जाना चाहिए? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"None","hi":"किसी को नहीं"},"2":{"en":"Public Prosecutor","hi":"लोक अभियोजक"},"3":{"en":"Family member or friend","hi":"परिवार के सदस्य या मित्र"},"4":{"en":"Nearest MP","hi":"निकटतम सांसद"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Family member or friend</b><br>Under the <b>BNSS, 2023</b> the police officer making an arrest must <b>inform a friend, relative or other person nominated by the arrested person</b> about the arrest, so the correct answer is a <b>family member or friend</b>.<br><br><br><b><u>Important Points:</u></b><br>• The obligation, earlier in <b>Section 50A of the CrPC</b>, is now carried into the BNSS and the officer must also <b>record the particulars</b> of the person informed in a register.<br>• The arrested person must be informed of the <b>grounds of arrest</b> and of the right to bail, and must be produced before a magistrate within <b>24 hours</b>.<br>• The three new criminal laws, <b>Bharatiya Nyaya Sanhita, BNSS and Bharatiya Sakshya Adhiniyam</b>, replaced the IPC, CrPC and Evidence Act with effect from <b>1 July 2024</b>.<br>• Failure to inform a nominated person is a ground for holding the arrest illegal in writ proceedings, and <b>D. K. Basu v. State of West Bengal (1997)</b> laid down arrest safeguards.","hi":"<b>सही उत्तर: विकल्प (3) – परिवार के सदस्य या मित्र</b><br><b>BNSS, 2023</b> के अंतर्गत गिरफ्तारी करने वाले पुलिस अधिकारी को गिरफ्तार व्यक्ति द्वारा नामित <b>मित्र, संबंधी या अन्य व्यक्ति</b> को सूचित करना होता है, अतः सही उत्तर <b>परिवार का सदस्य या मित्र</b> है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• यह दायित्व पूर्व में <b>दंड प्रक्रिया संहिता की धारा 50A</b> में था और अब BNSS में सम्मिलित है; अधिकारी को सूचित व्यक्ति का <b>विवरण रजिस्टर में दर्ज</b> करना होता है।<br>• गिरफ्तार व्यक्ति को <b>गिरफ्तारी के आधार</b> तथा जमानत के अधिकार की जानकारी दी जानी चाहिए और उसे <b>24 घंटे</b> के भीतर मजिस्ट्रेट के समक्ष प्रस्तुत करना होता है।<br>• तीन नए आपराधिक कानून <b>भारतीय न्याय संहिता, BNSS तथा भारतीय साक्ष्य अधिनियम</b> ने <b>1 जुलाई 2024</b> से IPC, CrPC तथा साक्ष्य अधिनियम का स्थान लिया।<br>• नामित व्यक्ति को सूचित न करना रिट कार्यवाही में गिरफ्तारी को अवैध ठहराने का आधार हो सकता है; <b>डी. के. बासु बनाम पश्चिम बंगाल राज्य (1997)</b> में गिरफ्तारी संबंधी सुरक्षा उपाय निर्धारित हुए।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":36,"local_id":"50036","quid":"Q1000070816","section":"GK","topic":"Economics: Five Year Plan and Industrial Policy Resolution","question":{"en":"Which of the following best describes a limitation of open planning in India? [SSC CGL 28/10/26 Shift 2]","hi":"निम्नलिखित में से कौन भारत में खुली योजना (open planning) की सीमा का सर्वोत्तम वर्णन करता है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"It prevents foreign investment","hi":"यह विदेशी निवेश को रोकती है"},"2":{"en":"It encourages dictatorial decision-making","hi":"यह तानाशाही निर्णय लेने को प्रोत्साहित करती है"},"3":{"en":"It complicates forming an optimal development strategy","hi":"यह सर्वोत्तम विकास रणनीति बनाना जटिल कर देती है"},"4":{"en":"It excludes citizens from policy formation","hi":"यह नीति निर्माण से नागरिकों को बाहर रखती है"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – It complicates forming an optimal development strategy</b><br>In <b>open (indicative) planning</b> the state fixes broad targets and leaves detailed decisions to the market, and with many independent decision-makers the framing of a <b>single optimal development strategy</b> becomes complicated.<br><br><br><b><u>Important Points:</u></b><br>• India shifted from <b>centralised planning</b> to <b>indicative planning</b> with the <b>Eighth Five Year Plan (1992-97)</b>, after the 1991 reforms.<br>• Indicative planning relies on <b>market signals, private investment and incentives</b> rather than direct physical targets and controls.<br>• Its limitations include <b>difficulty of coordination</b> among many actors, weaker control over regional imbalances and a risk that market outcomes ignore equity.<br>• The <b>Planning Commission</b> was replaced by <b>NITI Aayog on 1 January 2015</b>, and the <b>Twelfth Plan (2012-17)</b> was the last Five Year Plan.","hi":"<b>सही उत्तर: विकल्प (3) – यह सर्वोत्तम विकास रणनीति बनाना जटिल कर देती है</b><br><b>खुली (सांकेतिक) योजना</b> में राज्य व्यापक लक्ष्य तय करता है और विस्तृत निर्णय बाजार पर छोड़ देता है; अनेक स्वतंत्र निर्णयकर्ताओं के कारण <b>एक ही सर्वोत्तम विकास रणनीति</b> बनाना जटिल हो जाता है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• भारत ने 1991 के सुधारों के बाद <b>आठवीं पंचवर्षीय योजना (1992-97)</b> से <b>केंद्रीकृत योजना</b> से <b>सांकेतिक योजना</b> की ओर बदलाव किया।<br>• सांकेतिक योजना प्रत्यक्ष भौतिक लक्ष्यों व नियंत्रण के बजाय <b>बाजार संकेतों, निजी निवेश तथा प्रोत्साहनों</b> पर निर्भर करती है।<br>• इसकी सीमाओं में <b>समन्वय में कठिनाई</b>, क्षेत्रीय असंतुलन पर कमजोर नियंत्रण तथा बाजार परिणामों में समता की उपेक्षा का जोखिम शामिल है।<br>• <b>योजना आयोग</b> के स्थान पर <b>1 जनवरी 2015</b> को <b>नीति आयोग</b> बना और <b>बारहवीं योजना (2012-17)</b> अंतिम पंचवर्षीय योजना थी।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":37,"local_id":"50037","quid":"Q1000070817","section":"GK","topic":"Ancient History: Vedic Age","question":{"en":"What are the two primary branches into which the Shukla Yajurveda is divided? [SSC CGL 28/10/26 Shift 2]","hi":"शुक्ल यजुर्वेद के दो प्रमुख शाखाओं/भागों के नाम क्या हैं? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Taittiriya and Katha","hi":"तैत्तिरीय तथा कठ"},"2":{"en":"Shakala and Baskala","hi":"शाकल तथा बाष्कल"},"3":{"en":"Madhyandina and Kanva","hi":"माध्यंदिन तथा काण्व"},"4":{"en":"Shaunaka and Paippalada","hi":"शौनक तथा पिप्पलाद"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Madhyandina and Kanva</b><br>The <b>Shukla (white) Yajurveda</b>, chiefly the <b>Vajasaneyi Samhita</b>, has two recensions - <b>Madhyandina</b> and <b>Kanva</b>.<br><br><br><b><u>Important Points:</u></b><br>• The <b>Yajurveda</b> deals with <b>sacrificial formulas and rituals</b> and exists in two forms - <b>Shukla (white)</b> and <b>Krishna (black)</b>.<br>• The <b>Krishna Yajurveda</b> has branches such as <b>Taittiriya, Maitrayani, Katha and Kapishthala</b>, so the other pairs belong to it.<br>• The Shukla Yajurveda is associated with the sage <b>Yajnavalkya</b>, and its <b>Shatapatha Brahmana</b> explains the sacrificial ritual in detail.<br>• <b>Shakala and Baskala</b> are recensions of the <b>Rigveda</b>, while <b>Shaunaka and Paippalada</b> belong to the <b>Atharvaveda</b>.","hi":"<b>सही उत्तर: विकल्प (3) – माध्यंदिन तथा काण्व</b><br><b>शुक्ल (श्वेत) यजुर्वेद</b>, मुख्यतः <b>वाजसनेयी संहिता</b>, की दो शाखाएँ हैं - <b>माध्यंदिन</b> तथा <b>काण्व</b>।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>यजुर्वेद</b> <b>यज्ञ संबंधी मंत्रों तथा कर्मकांड</b> से संबंधित है और यह <b>शुक्ल (श्वेत)</b> व <b>कृष्ण (काला)</b> दो रूपों में उपलब्ध है।<br>• <b>कृष्ण यजुर्वेद</b> की शाखाएँ <b>तैत्तिरीय, मैत्रायणी, कठ तथा कपिष्ठल</b> हैं, अतः शेष युग्म इसी के हैं।<br>• शुक्ल यजुर्वेद ऋषि <b>याज्ञवल्क्य</b> से संबद्ध है तथा इसका <b>शतपथ ब्राह्मण</b> यज्ञ-विधि का विस्तृत विवरण देता है।<br>• <b>शाकल तथा बाष्कल</b> <b>ऋग्वेद</b> की शाखाएँ हैं, जबकि <b>शौनक तथा पिप्पलाद</b> <b>अथर्ववेद</b> की शाखाएँ हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":38,"local_id":"50038","quid":"Q1000070818","section":"GK","topic":"Polity: DPSP and Fundamental Duties","question":{"en":"According to Article 39(b) of the Indian Constitution, what is the primary objective of distributing the ownership and control of material resources? [SSC CGL 28/10/26 Shift 2]","hi":"भारतीय संविधान के अनुच्छेद 39(b) के अनुसार, भौतिक संसाधनों के स्वामित्व तथा नियंत्रण के वितरण का प्राथमिक उद्देश्य क्या है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"National defence","hi":"राष्ट्रीय रक्षा"},"2":{"en":"Private profit","hi":"निजी लाभ"},"3":{"en":"Common good","hi":"सार्वजनिक हित"},"4":{"en":"Judicial power","hi":"न्यायिक शक्ति"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Common good</b><br><b>Article 39(b)</b> directs the State to ensure that the <b>ownership and control of the material resources of the community</b> are distributed so as to <b>best subserve the common good</b>.<br><br><br><b><u>Important Points:</u></b><br>• Article 39 is part of the <b>Directive Principles of State Policy</b> in <b>Part IV (Articles 36-51)</b>, and Article 39(b) is one of its economic directives.<br>• Article 39(a) speaks of <b>adequate means of livelihood</b>, 39(c) of preventing <b>concentration of wealth</b> and 39(d) of <b>equal pay for equal work</b>.<br>• Directive Principles are <b>not enforceable in courts</b> (Article 37) but are <b>fundamental in the governance</b> of the country.<br>• Article 39(b) and (c) are linked with <b>Article 31C</b>, and the Supreme Court has discussed them in cases such as <b>Minerva Mills (1980)</b> and <b>Property Owners Association (2024)</b>.","hi":"<b>सही उत्तर: विकल्प (3) – सार्वजनिक हित</b><br><b>अनुच्छेद 39(b)</b> राज्य को निर्देश देता है कि <b>समुदाय के भौतिक संसाधनों का स्वामित्व व नियंत्रण</b> इस प्रकार वितरित हो कि वह <b>सार्वजनिक हित</b> को सर्वोत्तम रूप से पूर्ण करे।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• अनुच्छेद 39 <b>भाग IV (अनुच्छेद 36-51)</b> के <b>राज्य के नीति निर्देशक तत्वों</b> का भाग है और अनुच्छेद 39(b) इसका आर्थिक निर्देश है।<br>• अनुच्छेद 39(a) <b>जीवन-यापन के पर्याप्त साधन</b>, 39(c) <b>धन के संकेंद्रण की रोकथाम</b> तथा 39(d) <b>समान कार्य के लिए समान वेतन</b> से संबंधित है।<br>• नीति निर्देशक तत्व <b>न्यायालय में प्रवर्तनीय नहीं</b> हैं (अनुच्छेद 37), परंतु देश के शासन में <b>मूलभूत</b> हैं।<br>• अनुच्छेद 39(b) व (c) <b>अनुच्छेद 31C</b> से जुड़े हैं और सर्वोच्च न्यायालय ने <b>मिनर्वा मिल्स (1980)</b> तथा <b>प्रॉपर्टी ओनर्स एसोसिएशन (2024)</b> जैसे वादों में इन पर विचार किया।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":39,"local_id":"50039","quid":"Q1000070819","section":"GK","topic":"Medieval History: Vijayanagara and Bahmani Kingdom","question":{"en":"Consider these statements regarding the dynasties of Vijayanagara:<br>1. Narasimha Saluva ended the Sangama dynasty and started the Saluva dynasty.<br>2. Vira Narasimha deposed the last Saluva ruler to start the Tuluva dynasty.<br>Which of the above statements is/are <b>correct</b>? [SSC CGL 28/10/26 Shift 2]","hi":"विजयनगर के राजवंशों के संबंध में इन कथनों पर विचार करें:<br>1. नरसिंह सालुव ने संगम राजवंश का अंत कर सालुव राजवंश की स्थापना की।<br>2. वीर नरसिंह ने अंतिम सालुव शासक को हटाकर तुलुव राजवंश आरंभ किया।<br>उपर्युक्त कथनों में से कौन-सा/से <b>सही</b> है/हैं? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"1 only","hi":"केवल 1"},"2":{"en":"2 only","hi":"केवल 2"},"3":{"en":"Both 1 and 2","hi":"1 तथा 2 दोनों"},"4":{"en":"Neither 1 nor 2","hi":"न तो 1 और न ही 2"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Both 1 and 2</b><br><b>Narasimha Saluva</b> overthrew the last Sangama ruler and founded the <b>Saluva dynasty</b>, and <b>Vira Narasimha</b> deposed the last Saluva ruler <b>Immadi Narasimha</b> to start the <b>Tuluva dynasty</b>; hence both statements are correct.<br><br><br><b><u>Important Points:</u></b><br>• The four dynasties of Vijayanagara were the <b>Sangama (1336-1485), Saluva (1485-1505), Tuluva (1505-1570) and Aravidu (1570-1646)</b>.<br>• <b>Harihara and Bukka</b> founded Vijayanagara in <b>1336</b> on the banks of the Tungabhadra, with its capital at Hampi.<br>• The Tuluva dynasty produced <b>Krishnadevaraya (1509-1529)</b>, whose reign was described by the Portuguese traveller <b>Domingo Paes</b>.<br>• Vijayanagara was sacked in the <b>Battle of Talikota (1565)</b> by the Deccan Sultanates, after which the Aravidu dynasty ruled from Penukonda.","hi":"<b>सही उत्तर: विकल्प (3) – 1 तथा 2 दोनों</b><br><b>नरसिंह सालुव</b> ने अंतिम संगम शासक को हटाकर <b>सालुव राजवंश</b> की स्थापना की तथा <b>वीर नरसिंह</b> ने अंतिम सालुव शासक <b>इम्माडि नरसिंह</b> को पदच्युत कर <b>तुलुव राजवंश</b> आरंभ किया; अतः दोनों कथन सही हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• विजयनगर के चार राजवंश <b>संगम (1336-1485), सालुव (1485-1505), तुलुव (1505-1570) तथा अरवीडु (1570-1646)</b> थे।<br>• <b>हरिहर तथा बुक्का</b> ने <b>1336</b> में तुंगभद्रा नदी के तट पर विजयनगर की स्थापना की; इसकी राजधानी हम्पी थी।<br>• तुलुव राजवंश ने <b>कृष्णदेवराय (1509-1529)</b> दिया, जिनके शासन का वर्णन पुर्तगाली यात्री <b>डोमिंगो पेस</b> ने किया।<br>• <b>तालिकोट के युद्ध (1565)</b> में दक्कन सल्तनतों ने विजयनगर को लूटा, उसके बाद अरवीडु राजवंश ने पेनुकोंडा से शासन किया।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":40,"local_id":"50040","quid":"Q1000070820","section":"GK","topic":"Geography: Himalayan River System","question":{"en":"Consider the following statements regarding the river Brahmaputra:<br>1. It originates in the Chemayungdung glacier of the Kailash range.<br>2. It enters India near the Namcha Barwa peak.<br>Which of the statements given above is/are <b>correct</b>? [SSC CGL 28/10/26 Shift 2]","hi":"ब्रह्मपुत्र नदी के संबंध में निम्नलिखित कथनों पर विचार करें:<br>1. यह कैलाश श्रेणी के चेमायुंगडुंग हिमनद से निकलती है।<br>2. यह नामचा बरवा शिखर के निकट भारत में प्रवेश करती है।<br>उपर्युक्त कथनों में से कौन-सा/से <b>सही</b> है/हैं? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Only 1","hi":"केवल 1"},"2":{"en":"Only 2","hi":"केवल 2"},"3":{"en":"Both 1 and 2","hi":"1 तथा 2 दोनों"},"4":{"en":"Neither 1 nor 2","hi":"न तो 1 और न ही 2"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Both 1 and 2</b><br>The <b>Brahmaputra</b> rises in the <b>Chemayungdung glacier</b> near the <b>Kailash range</b> and enters India near <b>Namcha Barwa</b> in Arunachal Pradesh, so both statements are correct.<br><br><br><b><u>Important Points:</u></b><br>• It is known as <b>Tsangpo</b> in Tibet, <b>Siang/Dihang</b> on entering Arunachal Pradesh, <b>Brahmaputra</b> in Assam and <b>Jamuna</b> in Bangladesh, where it joins the Padma.<br>• It takes a <b>hairpin bend</b> at Namcha Barwa (7,756 m) and forms a deep gorge before entering India.<br>• In Assam it builds the <b>Majuli river island</b>, the largest river island in the world, and forms <b>braided channels</b> with many sandbars.<br>• Its tributaries include the <b>Subansiri, Dibang, Lohit, Dhansiri, Manas</b> and the <b>Tista</b>, and it finally joins the Ganga-Padma and empties into the Bay of Bengal.","hi":"<b>सही उत्तर: विकल्प (3) – 1 तथा 2 दोनों</b><br><b>ब्रह्मपुत्र</b> <b>कैलाश श्रेणी</b> के निकट <b>चेमायुंगडुंग हिमनद</b> से निकलती है तथा अरुणाचल प्रदेश में <b>नामचा बरवा</b> के निकट भारत में प्रवेश करती है, अतः दोनों कथन सही हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• इसे तिब्बत में <b>त्सांगपो</b>, अरुणाचल में प्रवेश पर <b>सियांग/दिहांग</b>, असम में <b>ब्रह्मपुत्र</b> तथा बांग्लादेश में <b>जमुना</b> कहा जाता है, जहाँ यह पद्मा में मिलती है।<br>• नामचा बरवा (7,756 मी) पर यह <b>हेयरपिन मोड़</b> लेती है और भारत में प्रवेश से पूर्व गहरी घाटी बनाती है।<br>• असम में यह विश्व का सबसे बड़ा नदी द्वीप <b>माजुली</b> बनाती है तथा अनेक रेतीले टापुओं के साथ <b>गुंफित धाराएँ</b> बनाती है।<br>• इसकी सहायक नदियाँ <b>सुबनसिरी, दिबांग, लोहित, धनसिरी, मानस</b> तथा <b>तीस्ता</b> हैं; अंत में यह गंगा-पद्मा में मिलकर बंगाल की खाड़ी में गिरती है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":41,"local_id":"50041","quid":"Q1000070821","section":"GK","topic":"Polity: State Legislature","question":{"en":"Which Article of the Indian Constitution specifies that a law for the abolition or creation of a Legislative Council is not to be treated as a formal amendment under Article 368? [SSC CGL 28/10/26 Shift 2]","hi":"भारतीय संविधान का कौन-सा अनुच्छेद निर्दिष्ट करता है कि विधान परिषद के उत्सादन अथवा सृजन का कानून अनुच्छेद 368 के अंतर्गत औपचारिक संशोधन नहीं माना जाएगा? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Article 167","hi":"अनुच्छेद 167"},"2":{"en":"Article 172(1)","hi":"अनुच्छेद 172(1)"},"3":{"en":"Article 165(1)","hi":"अनुच्छेद 165(1)"},"4":{"en":"Article 169(3)","hi":"अनुच्छेद 169(3)"}},"answer":"4","solution":{"en":"<b>Correct Answer: Option (4) – Article 169(3)</b><br><b>Article 169(3)</b> states that a law providing for the <b>abolition or creation of a State Legislative Council</b> shall <b>not be deemed to be an amendment of the Constitution</b> for the purposes of Article 368.<br><br><br><b><u>Important Points:</u></b><br>• Article 169 allows Parliament to create or abolish a <b>Legislative Council</b> in a State, but only if the <b>State Legislative Assembly passes a resolution</b> by a <b>special majority</b>.<br>• Article 168 deals with the constitution of the State Legislatures, and Article 171 fixes the <b>composition of Legislative Councils</b>.<br>• Article 167 obliges the <b>Chief Minister</b> to communicate decisions to the Governor, while Article 165 deals with the <b>Advocate General</b>.<br>• Six States currently have Legislative Councils – <b>Uttar Pradesh, Bihar, Maharashtra, Karnataka, Andhra Pradesh and Telangana</b>.","hi":"<b>सही उत्तर: विकल्प (4) – अनुच्छेद 169(3)</b><br><b>अनुच्छेद 169(3)</b> कहता है कि <b>राज्य विधान परिषद के उत्सादन या सृजन</b> का कानून अनुच्छेद 368 के प्रयोजनों के लिए <b>संविधान का संशोधन नहीं</b> माना जाएगा।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• अनुच्छेद 169 संसद को राज्य में <b>विधान परिषद</b> बनाने या हटाने की शक्ति देता है, परंतु इसके लिए <b>राज्य विधान सभा को विशेष बहुमत</b> से प्रस्ताव पारित करना होता है।<br>• अनुच्छेद 168 राज्य विधानमंडलों के गठन तथा अनुच्छेद 171 <b>विधान परिषद की संरचना</b> से संबंधित है।<br>• अनुच्छेद 167 <b>मुख्यमंत्री</b> को राज्यपाल को निर्णय बताने हेतु बाध्य करता है, जबकि अनुच्छेद 165 <b>महाधिवक्ता</b> से संबंधित है।<br>• वर्तमान में छह राज्यों में विधान परिषद है – <b>उत्तर प्रदेश, बिहार, महाराष्ट्र, कर्नाटक, आंध्र प्रदेश तथा तेलंगाना</b>।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":42,"local_id":"50042","quid":"Q1000070822","section":"GK","topic":"Polity: Miscellaneous","question":{"en":"Match the following Constitutional Articles (List I) with their provisions (List II) and select the <b>correct</b> option:<br><table border='1' style='border-collapse:collapse;margin:10px auto;'><tr><th style='padding:6px 10px;text-align:left;'>List I (Articles)</th><th style='padding:6px 10px;text-align:left;'>List II (Provisions)</th></tr><tr><td style='padding:6px 10px;'>I. Article 140</td><td style='padding:6px 10px;'>1. Formation of the Finance Commission</td></tr><tr><td style='padding:6px 10px;'>II. Article 280</td><td style='padding:6px 10px;'>2. Provision for President’s Rule</td></tr><tr><td style='padding:6px 10px;'>III. Article 356</td><td style='padding:6px 10px;'>3. Ancillary powers of the Supreme Court</td></tr></table> [SSC CGL 28/10/26 Shift 2]","hi":"निम्नलिखित संवैधानिक अनुच्छेदों (सूची I) का उनके उपबंधों (सूची II) से मिलान कीजिए तथा <b>सही</b> विकल्प चुनिए:<br><table border='1' style='border-collapse:collapse;margin:10px auto;'><tr><th style='padding:6px 10px;text-align:left;'>सूची I (अनुच्छेद)</th><th style='padding:6px 10px;text-align:left;'>सूची II (उपबंध)</th></tr><tr><td style='padding:6px 10px;'>I. अनुच्छेद 140</td><td style='padding:6px 10px;'>1. वित्त आयोग का गठन</td></tr><tr><td style='padding:6px 10px;'>II. अनुच्छेद 280</td><td style='padding:6px 10px;'>2. राष्ट्रपति शासन का उपबंध</td></tr><tr><td style='padding:6px 10px;'>III. अनुच्छेद 356</td><td style='padding:6px 10px;'>3. सर्वोच्च न्यायालय की अनुषंगिक शक्तियाँ</td></tr></table> [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"I-1, II-2, III-3"},"2":{"en":"I-3, II-1, III-2"},"3":{"en":"I-2, II-3, III-1"},"4":{"en":"I-3, II-2, III-1"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – I-3, II-1, III-2</b><br><b>Article 140</b> gives the <b>ancillary powers</b> of the Supreme Court, <b>Article 280</b> provides for the <b>Finance Commission</b> and <b>Article 356</b> deals with <b>President’s Rule</b>, so the correct pairing is I-3, II-1, III-2.<br><br><br><b><u>Important Points:</u></b><ul><li><b>Article 140</b> lets Parliament confer <b>supplemental powers</b> on the Supreme Court as may be necessary for the efficient working of the Constitution.</li><li><b>Article 280</b> requires the President to constitute a <b>Finance Commission every five years</b> to recommend the distribution of taxes between the Centre and States.</li><li><b>Article 356</b> permits <b>President’s Rule</b> when the constitutional machinery in a State fails; it must be approved by Parliament within <b>two months</b>.</li><li>Related articles are <b>Article 143</b> (advisory jurisdiction), <b>Article 263</b> (Inter-State Council) and <b>Article 360</b> (financial emergency).</li></ul>","hi":"<b>सही उत्तर: विकल्प (2) – I-3, II-1, III-2</b><br><b>अनुच्छेद 140</b> सर्वोच्च न्यायालय की <b>अनुषंगिक शक्तियाँ</b> देता है, <b>अनुच्छेद 280</b> <b>वित्त आयोग</b> का उपबंध करता है तथा <b>अनुच्छेद 356</b> <b>राष्ट्रपति शासन</b> से संबंधित है, अतः सही मिलान I-3, II-1, III-2 है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><ul><li><b>अनुच्छेद 140</b> संसद को सर्वोच्च न्यायालय पर <b>अनुपूरक शक्तियाँ</b> प्रदान करने की अनुमति देता है, जो संविधान के कुशल संचालन हेतु आवश्यक हों।</li><li><b>अनुच्छेद 280</b> के अनुसार राष्ट्रपति प्रत्येक <b>पाँच वर्ष</b> में <b>वित्त आयोग</b> गठित करते हैं, जो केंद्र व राज्यों के मध्य करों के बंटवारे की सिफारिश करता है।</li><li><b>अनुच्छेद 356</b> राज्य में संवैधानिक तंत्र विफल होने पर <b>राष्ट्रपति शासन</b> की अनुमति देता है; संसद से <b>दो माह</b> में अनुमोदन आवश्यक है।</li><li>संबंधित अनुच्छेद <b>अनुच्छेद 143</b> (परामर्शदात्री अधिकारिता), <b>अनुच्छेद 263</b> (अंतर-राज्य परिषद) तथा <b>अनुच्छेद 360</b> (वित्तीय आपात) हैं।</li></ul>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":43,"local_id":"50043","quid":"Q1000070823","section":"GK","topic":"Geography: Agriculture","question":{"en":"Which of the following crops is sown all over India except Punjab? [SSC CGL 28/10/26 Shift 2]","hi":"निम्नलिखित में से कौन-सी फसल पंजाब को छोड़कर पूरे भारत में बोई जाती है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Rice","hi":"चावल"},"2":{"en":"Wheat","hi":"गेहूँ"},"3":{"en":"Maize","hi":"मक्का"},"4":{"en":"Tea","hi":"चाय"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Maize</b><br><b>Maize</b> is grown in almost all parts of India as a <b>kharif</b> crop and is also raised in the rabi season in some States; <b>Punjab</b> is the notable exception where it is hardly sown on a large scale.<br><br><br><b><u>Important Points:</u></b><br>• Maize is called the <b>queen of cereals</b>; it needs <b>21-27°C</b> temperature and <b>50-75 cm</b> rainfall and is grown on about 10 million hectares.<br>• Leading maize producers are <b>Karnataka, Madhya Pradesh, Bihar, Tamil Nadu and Telangana</b>; it is used for food, poultry feed and starch.<br>• <b>Rice</b> is mainly a kharif crop of the east and south, and <b>wheat</b> is chiefly a rabi crop of the north-west, with Punjab among the largest producers.<br>• <b>Tea</b> is a plantation crop restricted to Assam, West Bengal, Tamil Nadu and Kerala, requiring well-drained slopes and heavy rainfall.","hi":"<b>सही उत्तर: विकल्प (3) – मक्का</b><br><b>मक्का</b> भारत के लगभग सभी भागों में <b>खरीफ</b> फसल के रूप में उगाया जाता है तथा कुछ राज्यों में रबी में भी; <b>पंजाब</b> इसका उल्लेखनीय अपवाद है जहाँ यह बड़े पैमाने पर नहीं बोया जाता।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• मक्का को <b>अनाजों की रानी</b> कहा जाता है; इसे <b>21-27°C</b> तापमान तथा <b>50-75 सेमी</b> वर्षा चाहिए और यह लगभग 10 मिलियन हेक्टेयर में उगाया जाता है।<br>• प्रमुख मक्का उत्पादक राज्य <b>कर्नाटक, मध्य प्रदेश, बिहार, तमिलनाडु तथा तेलंगाना</b> हैं; इसका उपयोग भोजन, मुर्गी पालन आहार व स्टार्च हेतु होता है।<br>• <b>चावल</b> मुख्यतः पूर्व व दक्षिण की खरीफ फसल है तथा <b>गेहूँ</b> मुख्यतः उत्तर-पश्चिम की रबी फसल है, जिसमें पंजाब सबसे बड़े उत्पादकों में है।<br>• <b>चाय</b> बागानी फसल है, जो असम, पश्चिम बंगाल, तमिलनाडु तथा केरल तक सीमित है और इसके लिए भलीभाँति निकास वाली ढलानें तथा भारी वर्षा आवश्यक है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":44,"local_id":"50044","quid":"Q1000070824","section":"GK","topic":"Geography: Agriculture","question":{"en":"Which crop is cultivated during all three seasons, Rabi, Kharif, and Zaid, in Southern India? [SSC CGL 28/10/26 Shift 2]","hi":"दक्षिण भारत में किस फसल की खेती रबी, खरीफ तथा जायद - तीनों मौसमों में की जाती है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Fodder","hi":"चारा"},"2":{"en":"Rice","hi":"चावल"},"3":{"en":"Wheat","hi":"गेहूँ"},"4":{"en":"Gram","hi":"चना"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Rice</b><br>In <b>Southern India</b>, with its high temperature and assured irrigation, <b>rice</b> is grown in all three seasons - <b>Kharif, Rabi (or Samba) and Zaid</b>, giving two or three crops a year.<br><br><br><b><u>Important Points:</u></b><br>• In Tamil Nadu the three rice seasons are known as <b>Sornavari (April-July), Samba (August-January) and Navarai (December-March)</b>.<br>• Rice needs <b>above 25°C</b> temperature and <b>100-200 cm</b> rainfall, and it is grown in about <b>40 per cent</b> of India’s cropped area in the east and south.<br>• West Bengal, Uttar Pradesh, Punjab, Odisha, Andhra Pradesh and Telangana are the leading rice producers, and India is the <b>second largest producer</b> after China.<br>• <b>Zaid</b> is the short summer season between rabi and kharif in which crops such as <b>watermelon, cucumber, moong and fodder</b> are grown.","hi":"<b>सही उत्तर: विकल्प (2) – चावल</b><br><b>दक्षिण भारत</b> में उच्च तापमान तथा सुनिश्चित सिंचाई के कारण <b>चावल</b> <b>खरीफ, रबी (या सांबा) तथा जायद</b> - तीनों मौसमों में उगाया जाता है, जिससे वर्ष में दो या तीन फसलें मिलती हैं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• तमिलनाडु में चावल के तीन मौसम <b>सोरनवरी (अप्रैल-जुलाई), सांबा (अगस्त-जनवरी) तथा नवरई (दिसंबर-मार्च)</b> कहलाते हैं।<br>• चावल हेतु <b>25°C से अधिक</b> तापमान तथा <b>100-200 सेमी</b> वर्षा आवश्यक है; यह पूर्व व दक्षिण में भारत के लगभग <b>40 प्रतिशत</b> बोए गए क्षेत्र में उगाया जाता है।<br>• प्रमुख चावल उत्पादक <b>पश्चिम बंगाल, उत्तर प्रदेश, पंजाब, ओडिशा, आंध्र प्रदेश तथा तेलंगाना</b> हैं; भारत चीन के बाद <b>दूसरा सबसे बड़ा उत्पादक</b> है।<br>• <b>जायद</b> रबी व खरीफ के बीच की छोटी ग्रीष्म ऋतु है, जिसमें <b>तरबूज, खीरा, मूंग तथा चारा</b> जैसी फसलें उगाई जाती हैं।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":45,"local_id":"50045","quid":"Q1000070825","section":"GK","topic":"Polity: Fundamental Rights","question":{"en":"Under Article 20(1) of the Indian Constitution, protection against ex post facto laws applies primarily to: [SSC CGL 28/10/26 Shift 2]","hi":"भारतीय संविधान के अनुच्छेद 20(1) के अंतर्गत, पूर्वव्यापी (ex post facto) विधियों से संरक्षण मुख्यतः किस पर लागू होता है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Constitutional amendments only","hi":"केवल संविधान संशोधनों पर"},"2":{"en":"Taxation laws only","hi":"केवल कराधान विधियों पर"},"3":{"en":"Criminal laws only","hi":"केवल आपराधिक विधियों पर"},"4":{"en":"Civil liability only","hi":"केवल दीवानी दायित्व पर"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Criminal laws only</b><br><b>Article 20(1)</b> protects a person against <b>ex post facto criminal laws</b> - conviction only for a violation of a law in force when the act was done, and no penalty greater than that prescribed at that time.<br><br><br><b><u>Important Points:</u></b><br>• The protection is available only in <b>criminal proceedings</b>; the Supreme Court held in <b>Shiv Bahadur Singh v. State of Vindhya Pradesh (1953)</b> that it does not apply to civil or tax laws.<br>• Article 20(2) embodies the rule of <b>double jeopardy</b>, and Article 20(3) protects against <b>self-incrimination</b>.<br>• Article 20 is a <b>fundamental right</b> in Part III and, unlike many other rights, is available to <b>citizens and non-citizens alike</b>.<br>• The <b>retrospective operation of tax laws</b> is therefore generally not hit by Article 20(1), though it may be tested against other constitutional provisions.","hi":"<b>सही उत्तर: विकल्प (3) – केवल आपराधिक विधियों पर</b><br><b>अनुच्छेद 20(1)</b> व्यक्ति को <b>पूर्वव्यापी आपराधिक विधियों</b> से संरक्षण देता है - दंड केवल उस विधि के उल्लंघन पर जो कार्य के समय प्रवृत्त थी, तथा उस समय निर्धारित दंड से अधिक दंड नहीं।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• यह संरक्षण केवल <b>आपराधिक कार्यवाही</b> में उपलब्ध है; सर्वोच्च न्यायालय ने <b>शिव बहादुर सिंह बनाम विंध्य प्रदेश राज्य (1953)</b> में कहा कि यह दीवानी या कर विधियों पर लागू नहीं।<br>• अनुच्छेद 20(2) <b>दोहरे दंड</b> के सिद्धांत का तथा अनुच्छेद 20(3) <b>आत्म-अभिशंसन</b> के विरुद्ध संरक्षण देता है।<br>• अनुच्छेद 20 भाग III का <b>मूल अधिकार</b> है तथा अन्य अनेक अधिकारों के विपरीत यह <b>नागरिकों व विदेशियों दोनों</b> को प्राप्त है।<br>• अतः <b>कर विधियों की पूर्वव्यापी प्रवृत्ति</b> सामान्यतः अनुच्छेद 20(1) के अंतर्गत नहीं आती, यद्यपि उसे अन्य संवैधानिक उपबंधों पर परखा जा सकता है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":46,"local_id":"50046","quid":"Q1000070826","section":"GK","topic":"Polity: New Criminal Laws 2023","question":{"en":"A victim in a serious criminal case wants her privately chosen advocate to actively assist the prosecution alongside the special public prosecutor appointed by the state. Which of the following is <b>correct</b> under the Bharatiya Nagarik Suraksha Sanhita, 2023 in India? [SSC CGL 28/10/26 Shift 2]","hi":"किसी गंभीर आपराधिक मामले में पीड़िता चाहती है कि उसका निजी रूप से चुना गया अधिवक्ता राज्य द्वारा नियुक्त विशेष लोक अभियोजक के साथ अभियोजन में सक्रिय सहायता करे। भारत में भारतीय नागरिक सुरक्षा संहिता, 2023 के अंतर्गत निम्नलिखित में से क्या <b>सही</b> है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Victims have no role once prosecution begins.","hi":"अभियोजन आरंभ होने के बाद पीड़ितों की कोई भूमिका नहीं होती।"},"2":{"en":"A victim’s advocate may assist the prosecution if the court permits.","hi":"न्यायालय की अनुमति होने पर पीड़ित का अधिवक्ता अभियोजन की सहायता कर सकता है।"},"3":{"en":"Only the Public Prosecutor may appear in criminal trials.","hi":"आपराधिक विचारणों में केवल लोक अभियोजक ही उपस्थित हो सकता है।"},"4":{"en":"Victim participation is allowed only in magistrate courts.","hi":"पीड़ित की भागीदारी केवल मजिस्ट्रेट न्यायालयों में अनुमत है।"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – A victim’s advocate may assist the prosecution if the court permits.</b><br>Under the <b>BNSS, 2023</b> the court may permit the <b>advocate engaged by the victim</b> to assist the prosecution, so option 2 is correct.<br><br><br><b><u>Important Points:</u></b><br>• <b>Section 40 of the BNSS</b> provides that the victim’s counsel may assist the prosecution, while the <b>Public Prosecutor conducts the case</b>.<br>• The BNSS defines a <b>victim</b> to include a person who has suffered loss or injury and, where the victim dies, the guardian or legal heir.<br>• The victim must be supplied a <b>copy of the FIR free of cost</b>, and the police must update the victim on the progress of the investigation.<br>• The new laws also provide for <b>zero FIR, e-FIR and audio-video recording of search and seizure</b>, strengthening the position of the victim.","hi":"<b>सही उत्तर: विकल्प (2) – न्यायालय की अनुमति होने पर पीड़ित का अधिवक्ता अभियोजन की सहायता कर सकता है।</b><br><b>BNSS, 2023</b> के अंतर्गत न्यायालय <b>पीड़ित द्वारा नियुक्त अधिवक्ता</b> को अभियोजन में सहायता की अनुमति दे सकता है, अतः विकल्प 2 सही है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>BNSS की धारा 40</b> के अनुसार पीड़ित के अधिवक्ता अभियोजन की सहायता कर सकते हैं, जबकि मामला <b>लोक अभियोजक चलाता</b> है।<br>• BNSS में <b>पीड़ित</b> की परिभाषा में हानि या क्षति भुगतने वाला व्यक्ति तथा पीड़ित की मृत्यु होने पर संरक्षक या विधिक उत्तराधिकारी सम्मिलित हैं।<br>• पीड़ित को <b>प्रथम सूचना रिपोर्ट की निःशुल्क प्रति</b> दी जानी चाहिए और पुलिस को अन्वेषण की प्रगति से पीड़ित को अवगत कराना होता है।<br>• नए कानूनों में <b>जीरो एफआईआर, ई-एफआईआर तथा तलाशी व जब्ती की ऑडियो-वीडियो रिकॉर्डिंग</b> का भी प्रावधान है, जिससे पीड़ित की स्थिति मजबूत होती है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":47,"local_id":"50047","quid":"Q1000070827","section":"GK","topic":"Ancient History: Post-Maurya Dynasties","question":{"en":"Patanjali’s Mahabhashya is a detailed commentary on which ancient Sanskrit grammar text? [SSC CGL 28/10/26 Shift 2]","hi":"पतंजलि का महाभाष्य किस प्राचीन संस्कृत व्याकरण ग्रंथ की विस्तृत टीका है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Manusmriti","hi":"मनुस्मृति"},"2":{"en":"Ashtadhyayi","hi":"अष्टाध्यायी"},"3":{"en":"Arthashastra","hi":"अर्थशास्त्र"},"4":{"en":"Natyashastra","hi":"नाट्यशास्त्र"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – Ashtadhyayi</b><br><b>Patanjali’s Mahabhashya</b> is a detailed commentary (<b>bhashya</b>) on <b>Panini’s Ashtadhyayi</b>, the foundational work of Sanskrit grammar.<br><br><br><b><u>Important Points:</u></b><br>• The <b>Ashtadhyayi</b> of <b>Panini</b> (about 5th-4th century BCE) has <b>eight chapters</b> with nearly 4,000 sutras and is the oldest surviving systematic grammar.<br>• Patanjali, the author of the <b>Mahabhashya</b>, is generally placed in the <b>second century BCE</b> and is identified with the Patanjali of the Yoga Sutras by tradition.<br>• The Mahabhashya also gives valuable references to the <b>Maurya period</b>, including the siege of <b>Saket</b> and the <b>Yavana</b> invasions of that age.<br>• Other ancient grammar works are <b>Katantra</b> and <b>Chandragomin’s grammar</b>, while the <b>Arthashastra</b> is by Kautilya and the <b>Natyashastra</b> by Bharata.","hi":"<b>सही उत्तर: विकल्प (2) – अष्टाध्यायी</b><br><b>पतंजलि का महाभाष्य</b> <b>पाणिनि की अष्टाध्यायी</b> की विस्तृत <b>भाष्य</b> (टीका) है, जो संस्कृत व्याकरण का आधारभूत ग्रंथ है।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>पाणिनि</b> (लगभग 5वीं-4वीं शताब्दी ईसा पूर्व) की <b>अष्टाध्यायी</b> में <b>आठ अध्याय</b> तथा लगभग 4,000 सूत्र हैं और यह प्राचीनतम क्रमबद्ध व्याकरण है।<br>• <b>महाभाष्य</b> के रचयिता पतंजलि सामान्यतः <b>द्वितीय शताब्दी ईसा पूर्व</b> के माने जाते हैं तथा परंपरा में इन्हें योगसूत्र के पतंजलि से एक माना जाता है।<br>• महाभाष्य में <b>मौर्य काल</b> के महत्वपूर्ण संदर्भ भी मिलते हैं, जिनमें <b>साकेत</b> का आक्रमण तथा उस युग के <b>यवन</b> आक्रमण शामिल हैं।<br>• अन्य प्राचीन व्याकरण ग्रंथ <b>कातंत्र</b> तथा <b>चंद्रगोमी का व्याकरण</b> हैं; <b>अर्थशास्त्र</b> कौटिल्य की तथा <b>नाट्यशास्त्र</b> भरत की रचना है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":48,"local_id":"50048","quid":"Q1000070828","section":"GK","topic":"Economics: 1991 Reforms And Industrial policy","question":{"en":"What was the main goal of the indirect tax reforms introduced as part of India’s 1991 economic liberalisation? [SSC CGL 28/10/26 Shift 2]","hi":"भारत के 1991 के आर्थिक उदारीकरण के अंग के रूप में लाए गए अप्रत्यक्ष कर सुधारों का मुख्य लक्ष्य क्या था? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"To promote public sector enterprises","hi":"सार्वजनिक क्षेत्र के उद्यमों को बढ़ावा देना"},"2":{"en":"To facilitate a common national market","hi":"एक साझा राष्ट्रीय बाजार को सुविधाजनक बनाना"},"3":{"en":"To increase agricultural subsidies","hi":"कृषि सब्सिडी बढ़ाना"},"4":{"en":"To reduce foreign investment inflows","hi":"विदेशी निवेश प्रवाह घटाना"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – To facilitate a common national market</b><br>The indirect tax reforms of <b>1991</b> aimed at <b>rationalising and simplifying the tax structure</b> so as to create a <b>common national market</b>, aided later by VAT and the GST.<br><br><br><b><u>Important Points:</u></b><br>• The <b>Chelliah Committee (1991)</b> recommended reducing customs and excise duty rates and simplifying the tariff structure.<br>• Peak customs duty was cut sharply, <b>MODVAT</b> was extended to all commodities and a <b>service tax</b> was introduced in <b>1994</b>.<br>• These steps lowered <b>cascading of taxes</b> and <b>inter-State barriers</b> to trade, and the process culminated in the <b>GST of 1 July 2017</b>.<br>• The 1991 reforms also covered <b>industrial delicensing, liberalisation of foreign investment and financial sector reform</b>.","hi":"<b>सही उत्तर: विकल्प (2) – एक साझा राष्ट्रीय बाजार को सुविधाजनक बनाना</b><br><b>1991</b> के अप्रत्यक्ष कर सुधारों का उद्देश्य <b>कर संरचना का तर्कसंगतीकरण व सरलीकरण</b> करके एक <b>साझा राष्ट्रीय बाजार</b> बनाना था, जिसे बाद में वैट तथा जीएसटी से बल मिला।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• <b>चेलैया समिति (1991)</b> ने सीमा शुल्क व उत्पाद शुल्क दरें घटाने तथा शुल्क संरचना सरल करने की सिफारिश की।<br>• अधिकतम सीमा शुल्क में तीव्र कटौती हुई, <b>मॉडवैट</b> सभी वस्तुओं तक बढ़ाया गया तथा <b>1994</b> में <b>सेवा कर</b> लागू हुआ।<br>• इन कदमों ने <b>करों के भार-संचरण</b> तथा व्यापार की <b>अंतर-राज्यीय बाधाएँ</b> घटाईं; यह प्रक्रिया <b>1 जुलाई 2017 के जीएसटी</b> में पूर्ण हुई।<br>• 1991 के सुधारों में <b>औद्योगिक लाइसेंसिंग की समाप्ति, विदेशी निवेश का उदारीकरण तथा वित्तीय क्षेत्र सुधार</b> भी शामिल थे।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":49,"local_id":"50049","quid":"Q1000070829","section":"GK","topic":"Physics: Motion","question":{"en":"A ring and a solid sphere of equal mass and radius are released from rest on the same inclined plane. If both objects roll without slipping, which one has greater linear acceleration? [SSC CGL 28/10/26 Shift 2]","hi":"समान द्रव्यमान तथा त्रिज्या की एक वलय और एक ठोस गोला एक ही झुके हुए तल पर विराम से छोड़े जाते हैं। यदि दोनों बिना फिसलन के लुढ़कते हैं, तो किसका रेखीय त्वरण अधिक होगा? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"The ring has greater linear acceleration","hi":"वलय का रेखीय त्वरण अधिक होगा"},"2":{"en":"The solid sphere has greater linear acceleration","hi":"ठोस गोले का रेखीय त्वरण अधिक होगा"},"3":{"en":"Both have equal linear acceleration","hi":"दोनों का रेखीय त्वरण समान होगा"},"4":{"en":"Their linear acceleration depends only on the angle of inclination","hi":"उनका रेखीय त्वरण केवल झुकाव कोण पर निर्भर करता है"}},"answer":"2","solution":{"en":"<b>Correct Answer: Option (2) – The solid sphere has greater linear acceleration</b><br>For a body rolling without slipping, \\(a = \\frac{g\\sin\\theta}{1 + \\frac{k^2}{r^2}}\\). For a <b>ring</b> \\(k^2/r^2 = 1\\), giving \\(a = \\frac{g\\sin\\theta}{2}\\); for a <b>solid sphere</b> \\(k^2/r^2 = 2/5\\), giving \\(a = \\frac{5}{7}g\\sin\\theta\\).<br><br><br><b><u>Important Points:</u></b><br>• Since \\(\\frac{5}{7} > \\frac{1}{2}\\), the <b>solid sphere</b> rolls down with the greater linear acceleration and reaches the bottom first.<br>• The same expression shows that for a <b>disc</b> \\(a = \\frac{2}{3}g\\sin\\theta\\), while for a <b>hollow sphere</b> \\(a = \\frac{3}{5}g\\sin\\theta\\).<br>• The result does not depend on the <b>mass or radius</b>; only the <b>radius of gyration</b> and the angle of inclination matter.<br>• Friction is essential for rolling without slipping; it does <b>no work</b> in pure rolling, and mechanical energy is conserved.","hi":"<b>सही उत्तर: विकल्प (2) – ठोस गोले का रेखीय त्वरण अधिक होगा</b><br>बिना फिसलन लुढ़कते पिंड के लिए \\(a = \\frac{g\\sin\\theta}{1 + \\frac{k^2}{r^2}\\)। <b>वलय</b> हेतु \\(k^2/r^2 = 1\\) होने से \\(a = \\frac{g\\sin\\theta}{2}\\) तथा <b>ठोस गोले</b> हेतु \\(k^2/r^2 = 2/5\\) होने से \\(a = \\frac{5}{7}g\\sin\\theta\\)।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• चूँकि \\(\\frac{5}{7} > \\frac{1}{2}\\) है, <b>ठोस गोला</b> अधिक रेखीय त्वरण से नीचे लुढ़कता है और पहले तल पर पहुँचता है।<br>• इसी व्यंजक से <b>चकती</b> हेतु \\(a = \\frac{2}{3}g\\sin\\theta\\) तथा <b>खोखले गोले</b> हेतु \\(a = \\frac{3}{5}g\\sin\\theta\\) मिलता है।<br>• यह परिणाम <b>द्रव्यमान या त्रिज्या</b> पर निर्भर नहीं; केवल <b>परिभ्रमण त्रिज्या</b> तथा झुकाव कोण महत्वपूर्ण हैं।<br>• बिना फिसलन लुढ़कने हेतु घर्षण आवश्यक है; शुद्ध लुढ़कन में यह <b>कोई कार्य नहीं</b> करता और यांत्रिक ऊर्जा संरक्षित रहती है।"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":50,"local_id":"50050","quid":"Q1000070830","section":"GK","topic":"Modern History: Gandhian Era","question":{"en":"Which incident prompted Mahatma Gandhi to withdraw the Non-Cooperation Movement? [SSC CGL 28/10/26 Shift 2]","hi":"किस घटना ने महात्मा गांधी को असहयोग आंदोलन वापस लेने के लिए प्रेरित किया? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Jallianwala Bagh","hi":"जलियाँवाला बाग"},"2":{"en":"Kakori Case","hi":"काकोरी कांड"},"3":{"en":"Chauri Chaura","hi":"चौरी-चौरा"},"4":{"en":"Bardoli Satyagraha","hi":"बारडोली सत्याग्रह"}},"answer":"3","solution":{"en":"<b>Correct Answer: Option (3) – Chauri Chaura</b><br>Gandhi withdrew the <b>Non-Cooperation Movement</b> on <b>12 February 1922</b> after the <b>Chauri Chaura</b> incident in Gorakhpur district, where a crowd set fire to a police station and killed policemen.<br><br><br><b><u>Important Points:</u></b><br>• The Non-Cooperation Movement was launched on <b>1 August 1920</b> and supported the <b>Khilafat</b> cause, with the slogan of attaining <b>Swaraj within a year</b>.<br>• Chauri Chaura convinced Gandhi that the masses were <b>not yet ready for non-violent struggle</b>, so he called off the movement.<br>• <b>Jallianwala Bagh (13 April 1919)</b> preceded the movement, while the <b>Kakori Case (1925)</b> and <b>Bardoli Satyagraha (1928)</b> happened later.<br>• The withdrawal was criticised by leaders such as <b>Motilal Nehru, C. R. Das and Jawaharlal Nehru</b>, and <b>Swaraj Party</b> was formed in 1923 to enter the councils.","hi":"<b>सही उत्तर: विकल्प (3) – चौरी-चौरा</b><br>गोरखपुर जिले के <b>चौरी-चौरा</b> में भीड़ द्वारा थाने में आग लगाए जाने तथा पुलिसकर्मियों की मृत्यु के बाद गांधी ने <b>12 फरवरी 1922</b> को <b>असहयोग आंदोलन</b> वापस ले लिया।<br><br><br><b><u>महत्वपूर्ण बिंदु:</u></b><br>• असहयोग आंदोलन <b>1 अगस्त 1920</b> को आरंभ हुआ, इसे <b>खिलाफत</b> के समर्थन के साथ चलाया गया और इसमें <b>एक वर्ष में स्वराज</b> का नारा था।<br>• चौरी-चौरा ने गांधी को विश्वास दिलाया कि जनता <b>अहिंसक संघर्ष हेतु अभी तैयार नहीं</b> है, अतः उन्होंने आंदोलन स्थगित किया।<br>• <b>जलियाँवाला बाग (13 अप्रैल 1919)</b> इस आंदोलन से पूर्व की घटना है, जबकि <b>काकोरी कांड (1925)</b> तथा <b>बारडोली सत्याग्रह (1928)</b> बाद के हैं।<br>• इस वापसी की आलोचना <b>मोतीलाल नेहरू, सी. आर. दास तथा जवाहरलाल नेहरू</b> जैसे नेताओं ने की और परिषदों में प्रवेश हेतु 1923 में <b>स्वराज पार्टी</b> बनी।"},"marks":{"correct":2,"negative":0.5},"has_image":false}]},"MATH":{"seconds":900,"questions":[{"no":51,"local_id":"50051","quid":"Q1000070831","section":"MATH","topic":"Mensuration (3D)","question":{"en":"What will be the total surface area of a hemispherical bowl of radius 14 cm? [SSC CGL 28/10/26 Shift 2]","hi":"14 cm त्रिज्या वाले एक अर्धगोलाकार कटोरे का कुल पृष्ठीय क्षेत्रफल क्या होगा? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"3488 cm²"},"2":{"en":"1788 cm²"},"3":{"en":"1848 cm²"},"4":{"en":"2848 cm²"}},"answer":"3","solution":{"en":"<svg width=\"212\" height=\"158\" viewBox=\"0 0 212 158\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 52A80 80 0 0 0 186 52\"/><path stroke-dasharray=\"4 3\" d=\"M106 52L186 52\"/><ellipse cx=\"106\" cy=\"52\" rx=\"80\" ry=\"26\"/><circle cx=\"106\" cy=\"52\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"150\" y=\"48\" font-size=\"11\">r = 14 cm</text></g></svg><br>Total surface area of a hemispherical bowl \\(= 3\\pi r^2\\)<br>\\(= 3 \\times \\frac{22}{7} \\times 14 \\times 14 = 3 \\times 616\\)<br>\\(= \\boxed{1848\\ \\text{cm}^2}\\)<br><br><b>Hence, the correct answer is option (3): 1848 cm².</b>","hi":"<svg width=\"212\" height=\"158\" viewBox=\"0 0 212 158\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 52A80 80 0 0 0 186 52\"/><path stroke-dasharray=\"4 3\" d=\"M106 52L186 52\"/><ellipse cx=\"106\" cy=\"52\" rx=\"80\" ry=\"26\"/><circle cx=\"106\" cy=\"52\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"150\" y=\"48\" font-size=\"11\">r = 14 cm</text></g></svg><br>अर्धगोलाकार कटोरे का कुल पृष्ठीय क्षेत्रफल \\(= 3\\pi r^2\\)<br>\\(= 3 \\times \\frac{22}{7} \\times 14 \\times 14 = 3 \\times 616\\)<br>\\(= \\boxed{1848\\ \\text{cm}^2}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 1848 cm² है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":52,"local_id":"50052","quid":"Q1000070832","section":"MATH","topic":"Mensuration (3D)","question":{"en":"The number of vertices in a rectangular parallelepiped is: [SSC CGL 28/10/26 Shift 2]","hi":"एक आयताकार समांतर षट्फलक (rectangular parallelepiped) में शीर्षों की संख्या है: [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"6"},"2":{"en":"8"},"3":{"en":"12"},"4":{"en":"10"}},"answer":"2","solution":{"en":"A rectangular parallelepiped (cuboid) has 8 vertices — 4 on the top face and 4 on the bottom face<br>It also has 12 edges and 6 faces<br>So the number of vertices \\(= \\boxed{8}\\)<br><br><b>Hence, the correct answer is option (2): 8.</b>","hi":"एक आयताकार समांतर षट्फलक (घनाभ) में 8 शीर्ष होते हैं — ऊपरी सतह पर 4 और निचली सतह पर 4<br>इसमें 12 किनारे और 6 फलक भी होते हैं<br>अतः शीर्षों की संख्या \\(= \\boxed{8}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 8 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":53,"local_id":"50053","quid":"Q1000070833","section":"MATH","topic":"Mensuration (2D)","question":{"en":"The sides of a triangle are in the ratio 3:4:5. If the perimeter is 36 cm, what is its area? [SSC CGL 28/10/26 Shift 2]","hi":"एक त्रिभुज की भुजाएँ 3:4:5 के अनुपात में हैं। यदि परिमाप 36 cm है, तो उसका क्षेत्रफल क्या है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"54 cm²"},"2":{"en":"60 cm²"},"3":{"en":"72 cm²"},"4":{"en":"108 cm²"}},"answer":"1","solution":{"en":"<svg width=\"201\" height=\"222\" viewBox=\"-21 0 201 222\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 26L26 196L154 196ZM35 196L35 187L26 187\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"21\" y=\"17\">A</text><text x=\"17\" y=\"211\">B</text><text x=\"166\" y=\"208\">C</text><text x=\"0\" y=\"115\">12 cm</text><text x=\"90\" y=\"212\">9 cm</text><text x=\"109\" y=\"100\">15 cm</text></g></svg><br>Let the sides be \\(3k, 4k, 5k\\), so \\(12k = 36 \\Rightarrow k = 3\\)<br>Sides are 9 cm, 12 cm, 15 cm — a right triangle (9² + 12² = 15²)<br>Area \\(= \\frac{1}{2} \\times 9 \\times 12 = \\boxed{54\\ \\text{cm}^2}\\)<br><br><b>Hence, the correct answer is option (1): 54 cm².</b>","hi":"<svg width=\"201\" height=\"222\" viewBox=\"-21 0 201 222\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 26L26 196L154 196ZM35 196L35 187L26 187\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"21\" y=\"17\">A</text><text x=\"17\" y=\"211\">B</text><text x=\"166\" y=\"208\">C</text><text x=\"0\" y=\"115\">12 cm</text><text x=\"90\" y=\"212\">9 cm</text><text x=\"109\" y=\"100\">15 cm</text></g></svg><br>मान लीजिए भुजाएँ \\(3k, 4k, 5k\\) हैं, अतः \\(12k = 36 \\Rightarrow k = 3\\)<br>भुजाएँ 9 cm, 12 cm, 15 cm — यह समकोण त्रिभुज है (9² + 12² = 15²)<br>क्षेत्रफल \\(= \\frac{1}{2} \\times 9 \\times 12 = \\boxed{54\\ \\text{cm}^2}\\)<br><br><b>अतः सही उत्तर विकल्प (1): 54 cm² है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":54,"local_id":"50054","quid":"Q1000070834","section":"MATH","topic":"Progression","question":{"en":"Find the sum of cubes of first 10 odd natural numbers. [SSC CGL 28/10/26 Shift 2]","hi":"प्रथम 10 विषम प्राकृत संख्याओं के घनों का योग ज्ञात कीजिए। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"21800"},"2":{"en":"19900"},"3":{"en":"24200"},"4":{"en":"19800"}},"answer":"2","solution":{"en":"Sum of cubes of the first \\(n\\) odd numbers \\(= n^2(2n^2 - 1)\\)<br>For \\(n = 10\\): \\(= 100 \\times (200 - 1) = 100 \\times 199\\)<br>\\(= \\boxed{19900}\\)<br>Check: \\(1^3 + 3^3 + \\dots + 19^3 = 19900\\)<br><br><b>Hence, the correct answer is option (2): 19900.</b>","hi":"प्रथम \\(n\\) विषम संख्याओं के घनों का योग \\(= n^2(2n^2 - 1)\\)<br>\\(n = 10\\) के लिए: \\(= 100 \\times (200 - 1) = 100 \\times 199\\)<br>\\(= \\boxed{19900}\\)<br>जाँच: \\(1^3 + 3^3 + \\dots + 19^3 = 19900\\)<br><br><b>अतः सही उत्तर विकल्प (2): 19900 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":55,"local_id":"50055","quid":"Q1000070835","section":"MATH","topic":"Time Speed and Distance","question":{"en":"A student goes to coaching at 6 km/hr and returns at 4 km/hr. If the total journey takes 4 hours, find the distance between home and coaching center. [SSC CGL 28/10/26 Shift 2]","hi":"एक विद्यार्थी कोचिंग जाने में 6 km/घंटा और वापस आने में 4 km/घंटा की चाल से चलता है। यदि कुल यात्रा में 4 घंटे लगते हैं, तो घर और कोचिंग केंद्र के बीच की दूरी ज्ञात कीजिए। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"6.5 km"},"2":{"en":"9.6 km"},"3":{"en":"10.50 km"},"4":{"en":"12.45 km"}},"answer":"2","solution":{"en":"Let the distance be \\(d\\) km<br>\\(\\frac{d}{6} + \\frac{d}{4} = 4 \\Rightarrow \\frac{2d + 3d}{12} = 4\\)<br>\\(\\frac{5d}{12} = 4 \\Rightarrow d = \\frac{48}{5} = \\boxed{9.6\\ \\text{km}}\\)<br><br><b>Hence, the correct answer is option (2): 9.6 km.</b>","hi":"मान लीजिए दूरी \\(d\\) km है<br>\\(\\frac{d}{6} + \\frac{d}{4} = 4 \\Rightarrow \\frac{2d + 3d}{12} = 4\\)<br>\\(\\frac{5d}{12} = 4 \\Rightarrow d = \\frac{48}{5} = \\boxed{9.6\\ \\text{km}}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 9.6 km है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":56,"local_id":"50056","quid":"Q1000070836","section":"MATH","topic":"Simplification and Approximation","question":{"en":"What is the simplified value of \\(\\frac{3.6 \\times 0.48 \\times 2.5}{0.12 \\times 0.09 \\times 0.5}\\) ? [SSC CGL 28/10/26 Shift 2]","hi":"\\(\\frac{3.6 \\times 0.48 \\times 2.5}{0.12 \\times 0.09 \\times 0.5}\\) का सरलीकृत मान क्या है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"500"},"2":{"en":"800"},"3":{"en":"600"},"4":{"en":"200"}},"answer":"2","solution":{"en":"\\(\\frac{3.6}{0.12} = 30\\), \\(\\frac{0.48}{0.09} = \\frac{48}{9} = \\frac{16}{3}\\), \\(\\frac{2.5}{0.5} = 5\\)<br>Product \\(= 30 \\times \\frac{16}{3} \\times 5 = 10 \\times 16 \\times 5\\)<br>\\(= \\boxed{800}\\)<br><br><b>Hence, the correct answer is option (2): 800.</b>","hi":"\\(\\frac{3.6}{0.12} = 30\\), \\(\\frac{0.48}{0.09} = \\frac{48}{9} = \\frac{16}{3}\\), \\(\\frac{2.5}{0.5} = 5\\)<br>गुणनफल \\(= 30 \\times \\frac{16}{3} \\times 5 = 10 \\times 16 \\times 5\\)<br>\\(= \\boxed{800}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 800 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":57,"local_id":"50057","quid":"Q1000070837","section":"MATH","topic":"Algebra","question":{"en":"For what value of \\(x\\) is the statement \\(\\left(\\frac{x}{12}\\right)\\left(\\frac{x}{48}\\right) = 1\\) true? [SSC CGL 28/10/26 Shift 2]","hi":"\\(x\\) के किस मान के लिए कथन \\(\\left(\\frac{x}{12}\\right)\\left(\\frac{x}{48}\\right) = 1\\) सत्य है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"34"},"2":{"en":"36"},"3":{"en":"24"},"4":{"en":"26"}},"answer":"3","solution":{"en":"\\(\\frac{x}{12} \\times \\frac{x}{48} = 1 \\Rightarrow \\frac{x^2}{576} = 1\\)<br>\\(x^2 = 576 \\Rightarrow x = 24\\) (positive value)<br>\\(x = \\boxed{24}\\)<br><br><b>Hence, the correct answer is option (3): 24.</b>","hi":"\\(\\frac{x}{12} \\times \\frac{x}{48} = 1 \\Rightarrow \\frac{x^2}{576} = 1\\)<br>\\(x^2 = 576 \\Rightarrow x = 24\\) (धनात्मक मान)<br>\\(x = \\boxed{24}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 24 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":58,"local_id":"50058","quid":"Q1000070838","section":"MATH","topic":"Geometry","question":{"en":"In \\(\\triangle PQR\\), the medians intersect at centroid G. If the segment PG is 15 cm, what is the total length of the median PD? [SSC CGL 28/10/26 Shift 2]","hi":"\\(\\triangle PQR\\) में माध्यिकाएँ केन्द्रक G पर प्रतिच्छेद करती हैं। यदि खंड PG = 15 cm है, तो माध्यिका PD की कुल लंबाई क्या है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"22.5 cm"},"2":{"en":"19.5 cm"},"3":{"en":"27 cm"},"4":{"en":"17 cm"}},"answer":"1","solution":{"en":"<svg width=\"282\" height=\"213\" viewBox=\"0 0 282 213\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M87 26L26 187L256 187ZM87 26L141 187M84 182l0 10M198 182l0 10\"/><circle cx=\"123\" cy=\"133\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"83\" y=\"17\">P</text><text x=\"12\" y=\"198\">Q</text><text x=\"271\" y=\"196\">R</text><text x=\"141\" y=\"198\">D</text><text x=\"129\" y=\"139\" text-anchor=\"start\">G</text><text x=\"99\" y=\"84\" text-anchor=\"end\" font-size=\"11\">15</text><text x=\"122\" y=\"111\" text-anchor=\"start\" font-size=\"11\">PD = ?</text></g></svg><br>The centroid divides each median in the ratio \\(2 : 1\\) from the vertex<br>So \\(PG : GD = 2 : 1 \\Rightarrow PG = \\frac{2}{3}\\,PD\\)<br>\\(15 = \\frac{2}{3}\\,PD \\Rightarrow PD = \\frac{45}{2} = \\boxed{22.5\\ \\text{cm}}\\)<br><br><b>Hence, the correct answer is option (1): 22.5 cm.</b>","hi":"<svg width=\"282\" height=\"213\" viewBox=\"0 0 282 213\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M87 26L26 187L256 187ZM87 26L141 187M84 182l0 10M198 182l0 10\"/><circle cx=\"123\" cy=\"133\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"83\" y=\"17\">P</text><text x=\"12\" y=\"198\">Q</text><text x=\"271\" y=\"196\">R</text><text x=\"141\" y=\"198\">D</text><text x=\"129\" y=\"139\" text-anchor=\"start\">G</text><text x=\"99\" y=\"84\" text-anchor=\"end\" font-size=\"11\">15</text><text x=\"122\" y=\"111\" text-anchor=\"start\" font-size=\"11\">PD = ?</text></g></svg><br>केन्द्रक प्रत्येक माध्यिका को शीर्ष से \\(2 : 1\\) के अनुपात में विभाजित करता है<br>अतः \\(PG : GD = 2 : 1 \\Rightarrow PG = \\frac{2}{3}\\,PD\\)<br>\\(15 = \\frac{2}{3}\\,PD \\Rightarrow PD = \\frac{45}{2} = \\boxed{22.5\\ \\text{cm}}\\)<br><br><b>अतः सही उत्तर विकल्प (1): 22.5 cm है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":59,"local_id":"50059","quid":"Q1000070839","section":"MATH","topic":"Number System","question":{"en":"If the number 483x7 is divisible by 3, what is the smallest possible value for x? [SSC CGL 28/10/26 Shift 2]","hi":"यदि संख्या 483x7, 3 से विभाज्य है, तो x का न्यूनतम संभावित मान क्या है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"1"},"2":{"en":"0"},"3":{"en":"2"},"4":{"en":"3"}},"answer":"3","solution":{"en":"A number is divisible by 3 when the sum of its digits is divisible by 3<br>\\(4 + 8 + 3 + x + 7 = 22 + x\\)<br>For divisibility, \\(22 + x\\) must be a multiple of 3; the smallest digit is obtained for \\(x = 2\\) (24)<br>\\(x = \\boxed{2}\\)<br><br><b>Hence, the correct answer is option (3): 2.</b>","hi":"कोई संख्या 3 से विभाज्य होती है जब उसके अंकों का योग 3 से विभाज्य हो<br>\\(4 + 8 + 3 + x + 7 = 22 + x\\)<br>विभाज्यता के लिए \\(22 + x\\), 3 का गुणज होना चाहिए; न्यूनतम अंक \\(x = 2\\) (24) के लिए मिलता है<br>\\(x = \\boxed{2}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 2 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":60,"local_id":"50060","quid":"Q1000070840","section":"MATH","topic":"Number System","question":{"en":"How many numbers between 100 and 400 are divisible by 13? [SSC CGL 28/10/26 Shift 2]","hi":"100 और 400 के बीच 13 से विभाज्य कितनी संख्याएँ हैं? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"56"},"2":{"en":"23"},"3":{"en":"45"},"4":{"en":"65"}},"answer":"2","solution":{"en":"First multiple above 100: \\(13 \\times 8 = 104\\)<br>Last multiple below 400: \\(13 \\times 30 = 390\\)<br>Count \\(= 30 - 8 + 1 = \\boxed{23}\\)<br><br><b>Hence, the correct answer is option (2): 23.</b>","hi":"100 से बड़ा पहला गुणज: \\(13 \\times 8 = 104\\)<br>400 से छोटा अंतिम गुणज: \\(13 \\times 30 = 390\\)<br>संख्या \\(= 30 - 8 + 1 = \\boxed{23}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 23 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":61,"local_id":"50061","quid":"Q1000070841","section":"MATH","topic":"Time Speed and Distance","question":{"en":"A train travels a certain distance at a uniform speed. If the speed of the train is increased by 10 km/h, it takes 2 hours less than the scheduled time. If the speed of the train is further increased by another 10 km/h, it takes a further 45 minutes less than the reduced time. Find the distance (in km) covered by the train. [SSC CGL 28/10/26 Shift 2]","hi":"एक रेलगाड़ी एक निश्चित दूरी एकसमान चाल से तय करती है। यदि रेलगाड़ी की चाल 10 km/घंटा बढ़ा दी जाए तो निर्धारित समय से 2 घंटे कम लगते हैं। यदि चाल में 10 km/घंटा और बढ़ा दी जाए तो घटे हुए समय से 45 मिनट और कम लगते हैं। रेलगाड़ी द्वारा तय की गई दूरी (km में) ज्ञात कीजिए। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"48.5 km"},"2":{"en":"52.8 km"},"3":{"en":"58.6 km"},"4":{"en":"60.5 km"}},"answer":"2","solution":{"en":"Let the speed be \\(v\\) and the distance be \\(D\\)<br>\\(\\frac{D}{v} - \\frac{D}{v+10} = 2\\) and \\(\\frac{D}{v+10} - \\frac{D}{v+20} = \\frac{45}{60} = \\frac{3}{4}\\)<br>Writing \\(D = \\frac{2v(v+10)}{10}\\) in the second equation: \\(\\frac{2v(v+10)}{10}\\left(\\frac{1}{v+10} - \\frac{1}{v+20}\\right) = \\frac{3}{4}\\)<br>\\(\\frac{2v}{10} \\times \\frac{10}{v+20} = \\frac{3}{4} \\Rightarrow \\frac{2v}{v+20} = \\frac{3}{4}\\)<br>\\(8v = 3v + 60 \\Rightarrow v = 12\\) km/h, so \\(D = \\frac{2(12)(22)}{10} = \\boxed{52.8\\ \\text{km}}\\)<br><br><b>Hence, the correct answer is option (2): 52.8 km.</b>","hi":"मान लीजिए चाल \\(v\\) और दूरी \\(D\\) है<br>\\(\\frac{D}{v} - \\frac{D}{v+10} = 2\\) तथा \\(\\frac{D}{v+10} - \\frac{D}{v+20} = \\frac{45}{60} = \\frac{3}{4}\\)<br>पहले से \\(D = \\frac{2v(v+10)}{10}\\) रखने पर: \\(\\frac{2v(v+10)}{10}\\left(\\frac{1}{v+10} - \\frac{1}{v+20}\\right) = \\frac{3}{4}\\)<br>\\(\\frac{2v}{10} \\times \\frac{10}{v+20} = \\frac{3}{4} \\Rightarrow \\frac{2v}{v+20} = \\frac{3}{4}\\)<br>\\(8v = 3v + 60 \\Rightarrow v = 12\\) km/h, अतः \\(D = \\frac{2(12)(22)}{10} = \\boxed{52.8\\ \\text{km}}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 52.8 km है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":62,"local_id":"50062","quid":"Q1000070842","section":"MATH","topic":"Mensuration (3D)","question":{"en":"The height of a right circular cone is 8 cm and its slant height is 10 cm. Find its curved surface area. [SSC CGL 28/10/26 Shift 2]","hi":"एक लंब वृत्तीय शंकु की ऊँचाई 8 cm और तिर्यक ऊँचाई 10 cm है। उसका वक्र पृष्ठीय क्षेत्रफल ज्ञात कीजिए। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"75π cm²"},"2":{"en":"70π cm²"},"3":{"en":"60π cm²"},"4":{"en":"65π cm²"}},"answer":"3","solution":{"en":"<svg width=\"202\" height=\"176\" viewBox=\"0 0 202 176\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 126A75 24 0 0 0 176 126M26 126L101 26L176 126M107 126L107 120L101 120\"/><path stroke-dasharray=\"4 3\" d=\"M26 126A75 24 0 0 1 176 126M101 26L101 126M101 126L176 126\"/><circle cx=\"101\" cy=\"126\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"106\" y=\"85\" text-anchor=\"start\" font-size=\"11\">8 cm</text><text x=\"138\" y=\"140\" font-size=\"11\">r</text><text x=\"44\" y=\"65\">10 cm</text></g></svg><br>Radius \\(r = \\sqrt{l^2 - h^2} = \\sqrt{100 - 64} = 6\\) cm<br>Curved surface area \\(= \\pi r l = \\pi \\times 6 \\times 10\\)<br>\\(= \\boxed{60\\pi\\ \\text{cm}^2}\\)<br><br><b>Hence, the correct answer is option (3): 60π cm².</b>","hi":"<svg width=\"202\" height=\"176\" viewBox=\"0 0 202 176\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 126A75 24 0 0 0 176 126M26 126L101 26L176 126M107 126L107 120L101 120\"/><path stroke-dasharray=\"4 3\" d=\"M26 126A75 24 0 0 1 176 126M101 26L101 126M101 126L176 126\"/><circle cx=\"101\" cy=\"126\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"106\" y=\"85\" text-anchor=\"start\" font-size=\"11\">8 cm</text><text x=\"138\" y=\"140\" font-size=\"11\">r</text><text x=\"44\" y=\"65\">10 cm</text></g></svg><br>त्रिज्या \\(r = \\sqrt{l^2 - h^2} = \\sqrt{100 - 64} = 6\\) cm<br>वक्र पृष्ठीय क्षेत्रफल \\(= \\pi r l = \\pi \\times 6 \\times 10\\)<br>\\(= \\boxed{60\\pi\\ \\text{cm}^2}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 60π cm² है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":63,"local_id":"50063","quid":"Q1000070843","section":"MATH","topic":"Trigonometry","question":{"en":"If \\(A + B = C\\), find the value of \\(\\tan A \\tan B \\tan C + \\tan A + \\tan B\\). [SSC CGL 28/10/26 Shift 2]","hi":"यदि \\(A + B = C\\) है, तो \\(\\tan A \\tan B \\tan C + \\tan A + \\tan B\\) का मान ज्ञात कीजिए। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"tan C"},"2":{"en":"tan A + tan B"},"3":{"en":"\\(\\frac{1}{\\tan C}\\)"},"4":{"en":"\\(\\frac{1}{\\tan A + \\tan B}\\)"}},"answer":"1","solution":{"en":"Since \\(A + B = C\\), \\(\\tan(A + B) = \\tan C\\)<br>\\(\\frac{\\tan A + \\tan B}{1 - \\tan A\\tan B} = \\tan C\\)<br>\\(\\tan A + \\tan B = \\tan C - \\tan A\\tan B\\tan C\\)<br>So \\(\\tan A\\tan B\\tan C + \\tan A + \\tan B = \\boxed{\\tan C}\\)<br><br><b>Hence, the correct answer is option (1): tan C.</b>","hi":"चूँकि \\(A + B = C\\), अतः \\(\\tan(A + B) = \\tan C\\)<br>\\(\\frac{\\tan A + \\tan B}{1 - \\tan A\\tan B} = \\tan C\\)<br>\\(\\tan A + \\tan B = \\tan C - \\tan A\\tan B\\tan C\\)<br>अतः \\(\\tan A\\tan B\\tan C + \\tan A + \\tan B = \\boxed{\\tan C}\\)<br><br><b>अतः सही उत्तर विकल्प (1): tan C है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":64,"local_id":"50064","quid":"Q1000070844","section":"MATH","topic":"Algebra","question":{"en":"If \\(x + \\frac{1}{x} = 5\\), then find the value of \\(\\frac{x^2 - 1}{x}\\). [SSC CGL 28/10/26 Shift 2]","hi":"यदि \\(x + \\frac{1}{x} = 5\\) है, तो \\(\\frac{x^2 - 1}{x}\\) का मान ज्ञात कीजिए। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"\\(\\pm\\sqrt{21}\\)"},"2":{"en":"\\(\\pm\\sqrt{31}\\)"},"3":{"en":"\\(\\pm\\sqrt{41}\\)"},"4":{"en":"\\(\\pm\\sqrt{51}\\)"}},"answer":"1","solution":{"en":"\\(\\frac{x^2 - 1}{x} = x - \\frac{1}{x}\\)<br>\\(\\left(x - \\frac{1}{x}\\right)^2 = \\left(x + \\frac{1}{x}\\right)^2 - 4 = 25 - 4 = 21\\)<br>\\(x - \\frac{1}{x} = \\boxed{\\pm\\sqrt{21}}\\)<br><br><b>Hence, the correct answer is option (1): \\(\\pm\\sqrt{21}\\).</b>","hi":"\\(\\frac{x^2 - 1}{x} = x - \\frac{1}{x}\\)<br>\\(\\left(x - \\frac{1}{x}\\right)^2 = \\left(x + \\frac{1}{x}\\right)^2 - 4 = 25 - 4 = 21\\)<br>\\(x - \\frac{1}{x} = \\boxed{\\pm\\sqrt{21}}\\)<br><br><b>अतः सही उत्तर विकल्प (1): \\(\\pm\\sqrt{21}\\) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":65,"local_id":"50065","quid":"Q1000070845","section":"MATH","topic":"Geometry","question":{"en":"A circle has a radius of 10 cm. A chord is drawn at a distance of 6 cm from the center. What is the length of the chord? [SSC CGL 28/10/26 Shift 2]","hi":"एक वृत्त की त्रिज्या 10 cm है। केंद्र से 6 cm की दूरी पर एक जीवा खींची गई है। जीवा की लंबाई क्या है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"8 cm"},"2":{"en":"12 cm"},"3":{"en":"14 cm"},"4":{"en":"16 cm"}},"answer":"4","solution":{"en":"<svg width=\"232\" height=\"232\" viewBox=\"0 0 232 232\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M44 170L188 170M116 116L116 170M123 170L123 163L116 163\"/><path stroke-dasharray=\"4 3\" d=\"M116 116L188 170\"/><circle cx=\"116\" cy=\"116\" r=\"90\"/><circle cx=\"116\" cy=\"116\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"108\" y=\"110\">O</text><text x=\"32\" y=\"182\">A</text><text x=\"200\" y=\"182\">B</text><text x=\"116\" y=\"186\">M</text><text x=\"111\" y=\"147\" text-anchor=\"end\" font-size=\"11\">6</text><text x=\"152\" y=\"186\" font-size=\"11\">x</text><text x=\"146\" y=\"155\">10</text></g></svg><br>The perpendicular from the centre bisects the chord, so half the chord \\(= \\sqrt{10^2 - 6^2}\\)<br>\\(= \\sqrt{100 - 36} = \\sqrt{64} = 8\\) cm<br>Chord \\(= 2 \\times 8 = \\boxed{16\\ \\text{cm}}\\)<br><br><b>Hence, the correct answer is option (4): 16 cm.</b>","hi":"<svg width=\"232\" height=\"232\" viewBox=\"0 0 232 232\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M44 170L188 170M116 116L116 170M123 170L123 163L116 163\"/><path stroke-dasharray=\"4 3\" d=\"M116 116L188 170\"/><circle cx=\"116\" cy=\"116\" r=\"90\"/><circle cx=\"116\" cy=\"116\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"108\" y=\"110\">O</text><text x=\"32\" y=\"182\">A</text><text x=\"200\" y=\"182\">B</text><text x=\"116\" y=\"186\">M</text><text x=\"111\" y=\"147\" text-anchor=\"end\" font-size=\"11\">6</text><text x=\"152\" y=\"186\" font-size=\"11\">x</text><text x=\"146\" y=\"155\">10</text></g></svg><br>केंद्र से डाला गया लंब जीवा को समद्विभाजित करता है, अतः आधी जीवा \\(= \\sqrt{10^2 - 6^2}\\)<br>\\(= \\sqrt{100 - 36} = \\sqrt{64} = 8\\) cm<br>जीवा \\(= 2 \\times 8 = \\boxed{16\\ \\text{cm}}\\)<br><br><b>अतः सही उत्तर विकल्प (4): 16 cm है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":66,"local_id":"50066","quid":"Q1000070846","section":"MATH","topic":"Mensuration (3D)","question":{"en":"A solid metallic hemisphere has a total surface area of 166.32 cm². If it is melted and recast into a solid sphere, what will be the approximate radius of the resulting sphere? (Use π = 22/7) [SSC CGL 28/10/26 Shift 2]","hi":"एक ठोस धात्विक अर्धगोले का कुल पृष्ठीय क्षेत्रफल 166.32 cm² है। यदि उसे पिघलाकर एक ठोस गोले में ढाला जाए, तो बनने वाले गोले की अनुमानित त्रिज्या क्या होगी? (π = 22/7 लीजिए) [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"2.1 cm"},"2":{"en":"4.2 cm"},"3":{"en":"3.3 cm"},"4":{"en":"5.6 cm"}},"answer":"3","solution":{"en":"For the hemisphere: \\(3\\pi r^2 = 166.32 \\Rightarrow 3 \\times \\frac{22}{7} r^2 = 166.32\\)<br>\\(r^2 = \\frac{166.32 \\times 7}{66} = 17.64 \\Rightarrow r = 4.2\\) cm<br>Volume of hemisphere \\(= \\frac{2}{3}\\pi r^3\\) = volume of the new sphere of radius \\(R\\)<br>\\(\\frac{4}{3}\\pi R^3 = \\frac{2}{3}\\pi (4.2)^3 \\Rightarrow R = \\frac{4.2}{2^{1/3}} \\approx 3.33\\) cm<br>\\(R \\approx \\boxed{3.3\\ \\text{cm}}\\)<br><br><b>Hence, the correct answer is option (3): 3.3 cm.</b>","hi":"अर्धगोले के लिए: \\(3\\pi r^2 = 166.32 \\Rightarrow 3 \\times \\frac{22}{7} r^2 = 166.32\\)<br>\\(r^2 = \\frac{166.32 \\times 7}{66} = 17.64 \\Rightarrow r = 4.2\\) cm<br>अर्धगोले का आयतन \\(= \\frac{2}{3}\\pi r^3\\) = नए गोले (त्रिज्या \\(R\\)) के आयतन के बराबर<br>\\(\\frac{4}{3}\\pi R^3 = \\frac{2}{3}\\pi (4.2)^3 \\Rightarrow R = \\frac{4.2}{2^{1/3}} \\approx 3.33\\) cm<br>\\(R \\approx \\boxed{3.3\\ \\text{cm}}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 3.3 cm है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":67,"local_id":"50067","quid":"Q1000070847","section":"MATH","topic":"Geometry","question":{"en":"PA and PB are two tangents from an external point P to a circle with center O. If ∠APB = 70°, what is the measure of ∠OAB? [SSC CGL 28/10/26 Shift 2]","hi":"PA और PB, केंद्र O वाले वृत्त के बाहरी बिंदु P से दो स्पर्श रेखाएँ हैं। यदि ∠APB = 70° है, तो ∠OAB का माप क्या है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"15°"},"2":{"en":"25°"},"3":{"en":"35°"},"4":{"en":"55°"}},"answer":"3","solution":{"en":"<svg width=\"258\" height=\"202\" viewBox=\"0 0 258 202\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M232 101L144 40M101 101L144 40M232 101L144 162M140 45L146 49L150 44M144 40L144 162M214 88A22 22 0 0 0 214 114\"/><path stroke-dasharray=\"4 3\" d=\"M101 101L144 162M101 101L232 101\"/><circle cx=\"101\" cy=\"101\" r=\"75\"/><circle cx=\"101\" cy=\"101\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"91\" y=\"105\">O</text><text x=\"242\" y=\"105\">P</text><text x=\"152\" y=\"32\">A</text><text x=\"152\" y=\"178\">B</text><text x=\"200\" y=\"105\" font-size=\"11\">70°</text></g></svg><br>\\(OA \\perp PA\\), so \\(\\angle OAP = 90°\\) and by symmetry \\(\\angle PAB = \\frac{180° - 70°}{2} = 55°\\)<br>\\(\\angle OAB = \\angle OAP - \\angle PAB = 90° - 55°\\)<br>\\(= \\boxed{35°}\\)<br><br><b>Hence, the correct answer is option (3): 35°.</b>","hi":"<svg width=\"258\" height=\"202\" viewBox=\"0 0 258 202\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M232 101L144 40M101 101L144 40M232 101L144 162M140 45L146 49L150 44M144 40L144 162M214 88A22 22 0 0 0 214 114\"/><path stroke-dasharray=\"4 3\" d=\"M101 101L144 162M101 101L232 101\"/><circle cx=\"101\" cy=\"101\" r=\"75\"/><circle cx=\"101\" cy=\"101\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"91\" y=\"105\">O</text><text x=\"242\" y=\"105\">P</text><text x=\"152\" y=\"32\">A</text><text x=\"152\" y=\"178\">B</text><text x=\"200\" y=\"105\" font-size=\"11\">70°</text></g></svg><br>\\(OA \\perp PA\\), अतः \\(\\angle OAP = 90°\\) तथा सममिति से \\(\\angle PAB = \\frac{180° - 70°}{2} = 55°\\)<br>\\(\\angle OAB = \\angle OAP - \\angle PAB = 90° - 55°\\)<br>\\(= \\boxed{35°}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 35° है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":68,"local_id":"50068","quid":"Q1000070848","section":"MATH","topic":"Mensuration (2D)","question":{"en":"If the minute hand of a clock is 14 cm long, what area (in cm²) does it sweep in 20 minutes? (Use π = 22/7) [SSC CGL 28/10/26 Shift 2]","hi":"यदि घड़ी की मिनट सुई 14 cm लंबी है, तो यह 20 मिनट में कितने क्षेत्रफल (cm² में) को घूम जाती है? (π = 22/7 लीजिए) [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"106.8 cm²"},"2":{"en":"154.2 cm²"},"3":{"en":"205.3 cm²"},"4":{"en":"250.7 cm²"}},"answer":"3","solution":{"en":"<svg width=\"232\" height=\"156\" viewBox=\"0 0 232 156\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M206 78L116 130L26 78M206 78A104 104 0 0 0 26 78M132 121A18 18 0 0 0 100 121\"/><circle cx=\"116\" cy=\"130\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"116\" y=\"104\" font-size=\"11\">120°</text><text x=\"171\" y=\"125\">14 cm</text><text x=\"61\" y=\"125\">14 cm</text><text x=\"116\" y=\"144\">O</text></g></svg><br>In 20 minutes the hand turns through \\(\\frac{20}{60} = \\frac{1}{3}\\) of the circle<br>Area swept \\(= \\frac{1}{3}\\pi r^2 = \\frac{1}{3} \\times \\frac{22}{7} \\times 196\\)<br>\\(= \\frac{1}{3} \\times 616 = 205.33 \\approx \\boxed{205.3\\ \\text{cm}^2}\\)<br><br><b>Hence, the correct answer is option (3): 205.3 cm².</b>","hi":"<svg width=\"232\" height=\"156\" viewBox=\"0 0 232 156\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M206 78L116 130L26 78M206 78A104 104 0 0 0 26 78M132 121A18 18 0 0 0 100 121\"/><circle cx=\"116\" cy=\"130\" r=\"2\" fill=\"#000\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"116\" y=\"104\" font-size=\"11\">120°</text><text x=\"171\" y=\"125\">14 cm</text><text x=\"61\" y=\"125\">14 cm</text><text x=\"116\" y=\"144\">O</text></g></svg><br>20 मिनट में सुई वृत्त का \\(\\frac{20}{60} = \\frac{1}{3}\\) भाग घूमती है<br>घूमा गया क्षेत्रफल \\(= \\frac{1}{3}\\pi r^2 = \\frac{1}{3} \\times \\frac{22}{7} \\times 196\\)<br>\\(= \\frac{1}{3} \\times 616 = 205.33 \\approx \\boxed{205.3\\ \\text{cm}^2}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 205.3 cm² है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":69,"local_id":"50069","quid":"Q1000070849","section":"MATH","topic":"Time and Work","question":{"en":"Vrinda takes half of the time taken by Raunaq to finish a particular task. Raunaq takes thrice the time taken by Vrinda and Parul working together to complete the task. If Raunaq takes 4.5 days more than that taken by the three of them working together to complete the task, how many days are required by Parul to complete the task alone? [SSC CGL 28/10/26 Shift 2]","hi":"वृंदा कोई कार्य पूरा करने में रौनक द्वारा लिए गए समय का आधा समय लेती है। रौनक, वृंदा और पारुल के साथ मिलकर लिए गए समय का तीन गुना समय लेता है। यदि रौनक, तीनों के साथ मिलकर लिए गए समय से 4.5 दिन अधिक लेता है, तो पारुल अकेले कार्य पूरा करने में कितने दिन लेगी? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"7 days","hi":"7 दिन"},"2":{"en":"6 days","hi":"6 दिन"},"3":{"en":"5.5 days","hi":"5.5 दिन"},"4":{"en":"4.5 days","hi":"4.5 दिन"}},"answer":"2","solution":{"en":"Let the time taken by Vrinda and Parul working together be \\(T\\) days<br>Raunaq takes thrice of it: Raunaq \\(= 3T\\), and Vrinda takes half of Raunaq's time: Vrinda \\(= \\frac{3T}{2}\\)<br>So \\(\\frac{1}{P} = \\frac{1}{T} - \\frac{1}{1.5T} = \\frac{1}{T} - \\frac{2}{3T} = \\frac{1}{3T} \\Rightarrow P = 3T\\)<br>Time taken by all three together: \\(\\frac{1}{S} = \\frac{2}{3T} + \\frac{1}{3T} + \\frac{1}{3T} = \\frac{4}{3T} \\Rightarrow S = \\frac{3T}{4}\\)<br>Given Raunaq takes 4.5 days more than the three together: \\(3T - \\frac{3T}{4} = 4.5 \\Rightarrow \\frac{9T}{4} = 4.5 \\Rightarrow T = 2\\)<br>Parul alone \\(= 3T = 3 \\times 2 = \\boxed{6\\ \\text{days}}\\)<br><br><b>Hence, the correct answer is option (2): 6 days.</b>","hi":"मान लीजिए वृंदा और पारुल मिलकर \\(T\\) दिन लेती हैं<br>रौनक उसका तीन गुना समय लेता है: रौनक \\(= 3T\\), और वृंदा रौनक के समय का आधा: वृंदा \\(= \\frac{3T}{2}\\)<br>अतः \\(\\frac{1}{P} = \\frac{1}{T} - \\frac{1}{1.5T} = \\frac{1}{T} - \\frac{2}{3T} = \\frac{1}{3T} \\Rightarrow P = 3T\\)<br>तीनों मिलकर लिया गया समय: \\(\\frac{1}{S} = \\frac{2}{3T} + \\frac{1}{3T} + \\frac{1}{3T} = \\frac{4}{3T} \\Rightarrow S = \\frac{3T}{4}\\)<br>दिया है कि रौनक, तीनों के साथ लिए गए समय से 4.5 दिन अधिक लेता है: \\(3T - \\frac{3T}{4} = 4.5 \\Rightarrow \\frac{9T}{4} = 4.5 \\Rightarrow T = 2\\)<br>पारुल अकेले \\(= 3T = 3 \\times 2 = \\boxed{6\\ \\text{दिन}}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 6 दिन है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":70,"local_id":"50070","quid":"Q1000070850","section":"MATH","topic":"Time and Work","question":{"en":"Ritesh can complete a piece of work in 20 days and Genelia can complete it in 30 days. They work on alternate days starting with Ritesh on the first day. However, on every third day of the overall working schedule, it is noticed that whoever is working on that day feels fatigued and works at exactly half of their normal efficiency. How many days will it take them to complete the work? [SSC CGL 28/10/26 Shift 2]","hi":"रितेश एक कार्य 20 दिनों में और जेनेलिया उसी कार्य को 30 दिनों में पूरा कर सकती है। वे पहले दिन रितेश से शुरू करते हुए एकांतर दिनों में कार्य करते हैं। परंतु, कार्य-अनुसूची के प्रत्येक तीसरे दिन जो भी व्यक्ति कार्य कर रहा होता है, वह थकान महसूस करता है और अपनी सामान्य कार्यक्षमता के ठीक आधे से कार्य करता है। उन्हें कार्य पूरा करने में कितने दिन लगेंगे? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"25 days","hi":"25 दिन"},"2":{"en":"27.5 days","hi":"27.5 दिन"},"3":{"en":"28.5 days","hi":"28.5 दिन"},"4":{"en":"30 days","hi":"30 दिन"}},"answer":"3","solution":{"en":"One day's work: Ritesh \\(= \\frac{1}{20}\\), Genelia \\(= \\frac{1}{30}\\); on every 3rd day the worker gives half output<br>Day 1 (Ritesh) \\(= \\frac{1}{20}\\), Day 2 (Genelia) \\(= \\frac{1}{30}\\), Day 3 (Ritesh, half) \\(= \\frac{1}{40}\\) \\(\\Rightarrow \\frac{13}{120}\\) in 3 days<br>Day 4 (Genelia) \\(= \\frac{1}{30}\\), Day 5 (Ritesh) \\(= \\frac{1}{20}\\), Day 6 (Genelia, half) \\(= \\frac{1}{60}\\) \\(\\Rightarrow \\frac{12}{120}\\) in next 3 days<br>Work in 6 days \\(= \\frac{25}{120} = \\frac{5}{24}\\); in 24 days \\(= 4 \\times \\frac{25}{120} = \\frac{100}{120} = \\frac{5}{6}\\), remaining \\(\\frac{1}{6} = \\frac{20}{120}\\)<br>Day 25 (Ritesh) \\(= \\frac{6}{120}\\), left \\(\\frac{14}{120}\\); Day 26 (Genelia) \\(= \\frac{4}{120}\\), left \\(\\frac{10}{120}\\); Day 27 (Ritesh, half) \\(= \\frac{3}{120}\\), left \\(\\frac{7}{120}\\); Day 28 (Genelia) \\(= \\frac{4}{120}\\), left \\(\\frac{3}{120}\\)<br>Day 29 (Ritesh, full rate \\(\\frac{6}{120}\\)) needs only half of the day to finish \\(\\frac{3}{120}\\)<br>Total \\(= 28 + \\frac{1}{2} = \\boxed{28.5\\ \\text{days}}\\)<br><br><b>Hence, the correct answer is option (3): 28.5 days.</b>","hi":"एक दिन का कार्य: रितेश \\(= \\frac{1}{20}\\), जेनेलिया \\(= \\frac{1}{30}\\); प्रत्येक तीसरे दिन कार्य करने वाला आधा कार्य करता है<br>दिन 1 (रितेश) \\(= \\frac{1}{20}\\), दिन 2 (जेनेलिया) \\(= \\frac{1}{30}\\), दिन 3 (रितेश, आधा) \\(= \\frac{1}{40}\\) \\(\\Rightarrow\\) 3 दिनों में \\(\\frac{13}{120}\\)<br>दिन 4 (जेनेलिया) \\(= \\frac{1}{30}\\), दिन 5 (रितेश) \\(= \\frac{1}{20}\\), दिन 6 (जेनेलिया, आधा) \\(= \\frac{1}{60}\\) \\(\\Rightarrow\\) अगले 3 दिनों में \\(\\frac{12}{120}\\)<br>6 दिनों में कार्य \\(= \\frac{25}{120} = \\frac{5}{24}\\); 24 दिनों में \\(= 4 \\times \\frac{25}{120} = \\frac{5}{6}\\), शेष \\(\\frac{1}{6} = \\frac{20}{120}\\)<br>दिन 25 (रितेश) \\(= \\frac{6}{120}\\), शेष \\(\\frac{14}{120}\\); दिन 26 (जेनेलिया) \\(= \\frac{4}{120}\\), शेष \\(\\frac{10}{120}\\); दिन 27 (रितेश, आधा) \\(= \\frac{3}{120}\\), शेष \\(\\frac{7}{120}\\); दिन 28 (जेनेलिया) \\(= \\frac{4}{120}\\), शेष \\(\\frac{3}{120}\\)<br>दिन 29 (रितेश, पूर्ण दर \\(\\frac{6}{120}\\)) को केवल आधा दिन लगेगा \\(\\frac{3}{120}\\) पूरा करने में<br>कुल \\(= 28 + \\frac{1}{2} = \\boxed{28.5\\ \\text{दिन}}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 28.5 दिन है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":71,"local_id":"50071","quid":"Q1000070851","section":"MATH","topic":"Trigonometry","question":{"en":"If \\(\\tan A + \\cot B = 2\\) and \\(A + B = 90°\\), find A. [SSC CGL 28/10/26 Shift 2]","hi":"यदि \\(\\tan A + \\cot B = 2\\) और \\(A + B = 90°\\) है, तो A ज्ञात कीजिए। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"90°"},"2":{"en":"30°"},"3":{"en":"60°"},"4":{"en":"45°"}},"answer":"4","solution":{"en":"Since \\(A + B = 90°\\), \\(\\cot B = \\tan A\\)<br>\\(2\\tan A = 2 \\Rightarrow \\tan A = 1\\)<br>\\(A = \\boxed{45°}\\)<br><br><b>Hence, the correct answer is option (4): 45°.</b>","hi":"चूँकि \\(A + B = 90°\\), अतः \\(\\cot B = \\tan A\\)<br>\\(2\\tan A = 2 \\Rightarrow \\tan A = 1\\)<br>\\(A = \\boxed{45°}\\)<br><br><b>अतः सही उत्तर विकल्प (4): 45° है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":72,"local_id":"50072","quid":"Q1000070852","section":"MATH","topic":"Algebra","question":{"en":"If \\(p - q = 13\\) and \\(pq = 27\\), find \\((p + q)^2\\). [SSC CGL 28/10/26 Shift 2]","hi":"यदि \\(p - q = 13\\) और \\(pq = 27\\) है, तो \\((p + q)^2\\) ज्ञात कीजिए। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"40"},"2":{"en":"168"},"3":{"en":"277"},"4":{"en":"312"}},"answer":"3","solution":{"en":"\\((p + q)^2 = (p - q)^2 + 4pq\\)<br>\\(= 169 + 108\\)<br>\\(= \\boxed{277}\\)<br><br><b>Hence, the correct answer is option (3): 277.</b>","hi":"\\((p + q)^2 = (p - q)^2 + 4pq\\)<br>\\(= 169 + 108\\)<br>\\(= \\boxed{277}\\)<br><br><b>अतः सही उत्तर विकल्प (3): 277 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":73,"local_id":"50073","quid":"Q1000070853","section":"MATH","topic":"Simplification and Approximation","question":{"en":"Evaluate: \\(\\left(3\\frac{2}{7}\\right) \\times \\left(2\\frac{1}{3}\\right) \\div \\left(1\\frac{5}{6}\\right)\\). Express as a mixed number. [SSC CGL 28/10/26 Shift 2]","hi":"मान ज्ञात कीजिए: \\(\\left(3\\frac{2}{7}\\right) \\times \\left(2\\frac{1}{3}\\right) \\div \\left(1\\frac{5}{6}\\right)\\)। मिश्रित संख्या के रूप में व्यक्त कीजिए। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"\\(4\\frac{4}{11}\\)"},"2":{"en":"\\(4\\frac{2}{3}\\)"},"3":{"en":"\\(4\\frac{2}{11}\\)"},"4":{"en":"\\(3\\frac{22}{33}\\)"}},"answer":"3","solution":{"en":"\\(3\\frac{2}{7} = \\frac{23}{7}\\), \\(2\\frac{1}{3} = \\frac{7}{3}\\), \\(1\\frac{5}{6} = \\frac{11}{6}\\)<br>\\(\\frac{23}{7} \\times \\frac{7}{3} \\div \\frac{11}{6} = \\frac{23}{3} \\times \\frac{6}{11} = \\frac{46}{11}\\)<br>\\(= \\boxed{4\\frac{2}{11}}\\)<br><br><b>Hence, the correct answer is option (3): \\(4\\frac{2}{11}\\).</b>","hi":"\\(3\\frac{2}{7} = \\frac{23}{7}\\), \\(2\\frac{1}{3} = \\frac{7}{3}\\), \\(1\\frac{5}{6} = \\frac{11}{6}\\)<br>\\(\\frac{23}{7} \\times \\frac{7}{3} \\div \\frac{11}{6} = \\frac{23}{3} \\times \\frac{6}{11} = \\frac{46}{11}\\)<br>\\(= \\boxed{4\\frac{2}{11}}\\)<br><br><b>अतः सही उत्तर विकल्प (3): \\(4\\frac{2}{11}\\) है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":74,"local_id":"50074","quid":"Q1000070854","section":"MATH","topic":"Height and Distance","question":{"en":"A vertical building stands on horizontal ground. From a point A, the angle of elevation of the top of the building is 30°. After walking 50 m towards the building to a point B, the angle of elevation becomes 45°. From point B, the angle of elevation of the top of a vertical antenna fixed on top of the building is 60°.<br><br>Find the height of the antenna. [SSC CGL 28/10/26 Shift 2]","hi":"एक ऊर्ध्वाधर भवन क्षैतिज भूमि पर खड़ा है। एक बिंदु A से भवन के शिखर का उन्नयन कोण 30° है। भवन की ओर 50 m चलकर बिंदु B पर पहुँचने पर उन्नयन कोण 45° हो जाता है। बिंदु B से भवन के ऊपर लगे ऊर्ध्वाधर एंटीना के शिखर का उन्नयन कोण 60° है।<br><br>एंटीना की ऊँचाई ज्ञात कीजिए। [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"25 m"},"2":{"en":"50 m"},"3":{"en":"\\(50\\sqrt{2}\\) m"},"4":{"en":"\\(25(\\sqrt{3} + 1)\\) m"}},"answer":"2","solution":{"en":"<svg width=\"257\" height=\"222\" viewBox=\"-35 0 257 222\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 196L196 196M26 196L26 98M26 98L26 26M196 196L26 98M124 196L26 98M124 196L26 26M34 196L34 188L26 188M172 196A24 24 0 0 1 175 184M108 196A16 16 0 0 1 113 185M88 196A36 36 0 0 1 106 165\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"161\" y=\"191\" font-size=\"11\">30°</text><text x=\"98\" y=\"191\" font-size=\"11\">45°</text><text x=\"94\" y=\"163\" font-size=\"11\">60°</text><text x=\"14\" y=\"151\">h</text><text x=\"-7\" y=\"66\">antenna</text><text x=\"75\" y=\"212\">x</text><text x=\"160\" y=\"212\">50 m</text><text x=\"196\" y=\"210\">A</text><text x=\"124\" y=\"210\">B</text></g></svg><br>Let the height of the building be \\(h\\) and \\(AB = 50\\) m<br>From A: \\(\\tan 30° = \\frac{h}{x + 50} \\Rightarrow x + 50 = h\\sqrt{3}\\)<br>From B: \\(\\tan 45° = \\frac{h}{x} \\Rightarrow x = h\\)<br>So \\(h + 50 = h\\sqrt{3} \\Rightarrow h(\\sqrt{3} - 1) = 50 \\Rightarrow h = 25(\\sqrt{3} + 1)\\) m, \\(x = h\\)<br>Let the antenna be \\(a\\) m tall: \\(\\tan 60° = \\frac{h + a}{x} = \\frac{h + a}{h} = \\sqrt{3}\\)<br>\\(a = h(\\sqrt{3} - 1) = 25(\\sqrt{3} + 1)(\\sqrt{3} - 1) = 25 \\times 2 = \\boxed{50\\ \\text{m}}\\)<br><br><b>Hence, the correct answer is option (2): 50 m.</b>","hi":"<svg width=\"257\" height=\"222\" viewBox=\"-35 0 257 222\" fill=\"none\" stroke=\"#000\" stroke-width=\"1.5\" font-size=\"12\"><path d=\"M26 196L196 196M26 196L26 98M26 98L26 26M196 196L26 98M124 196L26 98M124 196L26 26M34 196L34 188L26 188M172 196A24 24 0 0 1 175 184M108 196A16 16 0 0 1 113 185M88 196A36 36 0 0 1 106 165\"/><g fill=\"#000\" stroke=\"#fff\" stroke-width=\"3\" paint-order=\"stroke\" stroke-linejoin=\"round\" text-anchor=\"middle\"><text x=\"161\" y=\"191\" font-size=\"11\">30°</text><text x=\"98\" y=\"191\" font-size=\"11\">45°</text><text x=\"94\" y=\"163\" font-size=\"11\">60°</text><text x=\"14\" y=\"151\">h</text><text x=\"-7\" y=\"66\">antenna</text><text x=\"75\" y=\"212\">x</text><text x=\"160\" y=\"212\">50 m</text><text x=\"196\" y=\"210\">A</text><text x=\"124\" y=\"210\">B</text></g></svg><br>मान लीजिए भवन की ऊँचाई \\(h\\) और \\(AB = 50\\) m है<br>A से: \\(\\tan 30° = \\frac{h}{x + 50} \\Rightarrow x + 50 = h\\sqrt{3}\\)<br>B से: \\(\\tan 45° = \\frac{h}{x} \\Rightarrow x = h\\)<br>अतः \\(h + 50 = h\\sqrt{3} \\Rightarrow h(\\sqrt{3} - 1) = 50 \\Rightarrow h = 25(\\sqrt{3} + 1)\\) m, \\(x = h\\)<br>मान लीजिए एंटीना \\(a\\) m ऊँचा है: \\(\\tan 60° = \\frac{h + a}{x} = \\frac{h + a}{h} = \\sqrt{3}\\)<br>\\(a = h(\\sqrt{3} - 1) = 25(\\sqrt{3} + 1)(\\sqrt{3} - 1) = 25 \\times 2 = \\boxed{50\\ \\text{m}}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 50 m है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":75,"local_id":"50075","quid":"Q1000070855","section":"MATH","topic":"Geometry","question":{"en":"Two circles with radii 10 cm and 6 cm intersect at two distinct points. What is the total number of common tangents that can be drawn to these circles? [SSC CGL 28/10/26 Shift 2]","hi":"10 cm और 6 cm त्रिज्या वाले दो वृत्त दो भिन्न बिंदुओं पर प्रतिच्छेद करते हैं। इन वृत्तों पर खींची जा सकने वाली कुल उभयनिष्ठ स्पर्श रेखाओं की संख्या क्या है? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"3"},"2":{"en":"2"},"3":{"en":"4"},"4":{"en":"1"}},"answer":"2","solution":{"en":"When two circles intersect at two distinct points, they have 2 direct common tangents<br>The transverse common tangents do not exist in this case<br>Total common tangents \\(= \\boxed{2}\\)<br><br><b>Hence, the correct answer is option (2): 2.</b>","hi":"जब दो वृत्त दो भिन्न बिंदुओं पर प्रतिच्छेद करते हैं, तो उनकी 2 सीधी उभयनिष्ठ स्पर्श रेखाएँ होती हैं<br>इस स्थिति में तिर्यक उभयनिष्ठ स्पर्श रेखाएँ नहीं होतीं<br>कुल उभयनिष्ठ स्पर्श रेखाएँ \\(= \\boxed{2}\\)<br><br><b>अतः सही उत्तर विकल्प (2): 2 है।</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false}]},"ENGLISH":{"seconds":900,"questions":[{"no":76,"local_id":"50076","quid":"Q1000070856","section":"ENGLISH","topic":"Passage","question":{"en":"Read the passage and answer the questions:<br><br>The Big Bang Theory, far from being a mere speculative construct, stands as the most widely endorsed cosmological model explaining the origin and evolution of the universe. Approximately 13.8 billion years ago, the universe emerged from an unimaginably dense and hot singularity—a state where conventional physics collapses under extreme conditions. Within fractions of a second, an exponential inflationary expansion occurred, smoothing out initial irregularities and setting the stage for cosmic structure formation.<br><br>As the universe expanded, it cooled, permitting the formation of subatomic particles and, eventually, simple atomic nuclei during the epoch of nucleosynthesis. Several hundred thousand years later, the universe cooled enough for electrons and nuclei to combine into neutral atoms, an event known as recombination, thereby rendering the universe transparent to radiation. The residual glow from this era, observable today as the Cosmic Microwave Background (CMB) radiation, offers profound empirical support for the Big Bang model.<br><br>However, the theory does not escape philosophical and scientific quandaries. It leaves unanswered the very genesis of the singularity itself and cannot yet reconcile quantum mechanics with general relativity at cosmic scales. Furthermore, anomalies within the CMB, the existence of dark matter and dark energy, and the precise rate of cosmic expansion (Hubble tension) continue to perplex scientists.<br><br>In essence, while the Big Bang Theory illuminates the universe's evolution post-singularity with remarkable coherence, it simultaneously unveils deep epistemological and empirical mysteries, suggesting that humanity's understanding of cosmic origins remains tantalizingly incomplete.<br><br><br>In the sentence “The Big Bang Theory, far from being a mere speculative construct, stands as the most widely endorsed cosmological model...”, identify the grammatical role of the phrase “far from being a mere speculative construct.” [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Adverbial phrase modifying “stands”"},"2":{"en":"Adjective phrase modifying “Theory”"},"3":{"en":"Noun phrase acting as the subject"},"4":{"en":"Adverbial phrase modifying “construct”"}},"answer":"1","solution":{"en":"<b>Rule: “Far from + gerund” is an adverbial phrase of contrast that qualifies the verb.</b><br>“Far from being a mere speculative construct” tells us in what manner the theory <i>stands</i> – not as speculation, but as the most endorsed model.<br>It is set off by commas and contrasts with the predicate “stands as the most widely endorsed cosmological model”.<br>It is not the subject, and “construct” is a noun inside the phrase, so options 3 and 4 are wrong.<br><br><b>Hence, the correct answer is option (1): Adverbial phrase modifying “stands”.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":77,"local_id":"50077","quid":"Q1000070857","section":"ENGLISH","topic":"Passage","question":{"en":"Read the passage and answer the questions:<br><br>The Big Bang Theory, far from being a mere speculative construct, stands as the most widely endorsed cosmological model explaining the origin and evolution of the universe. Approximately 13.8 billion years ago, the universe emerged from an unimaginably dense and hot singularity—a state where conventional physics collapses under extreme conditions. Within fractions of a second, an exponential inflationary expansion occurred, smoothing out initial irregularities and setting the stage for cosmic structure formation.<br><br>As the universe expanded, it cooled, permitting the formation of subatomic particles and, eventually, simple atomic nuclei during the epoch of nucleosynthesis. Several hundred thousand years later, the universe cooled enough for electrons and nuclei to combine into neutral atoms, an event known as recombination, thereby rendering the universe transparent to radiation. The residual glow from this era, observable today as the Cosmic Microwave Background (CMB) radiation, offers profound empirical support for the Big Bang model.<br><br>However, the theory does not escape philosophical and scientific quandaries. It leaves unanswered the very genesis of the singularity itself and cannot yet reconcile quantum mechanics with general relativity at cosmic scales. Furthermore, anomalies within the CMB, the existence of dark matter and dark energy, and the precise rate of cosmic expansion (Hubble tension) continue to perplex scientists.<br><br>In essence, while the Big Bang Theory illuminates the universe's evolution post-singularity with remarkable coherence, it simultaneously unveils deep epistemological and empirical mysteries, suggesting that humanity's understanding of cosmic origins remains tantalizingly incomplete.<br><br><br>Which of the following best encapsulates the central limitation of the Big Bang Theory according to the passage? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Its inability to explain chemical evolution"},"2":{"en":"Its dependence solely on mathematical modeling"},"3":{"en":"Its failure to explain the singularity and reconcile major physical theories"},"4":{"en":"Its disregard for observational evidence like the CMB"}},"answer":"3","solution":{"en":"<b>Text evidence: The theory leaves the singularity’s genesis unanswered.</b><br>It also cannot reconcile quantum mechanics with general relativity.<br>CMB evidence supports rather than undermines the model.<br>The limitation is therefore theoretical, not chemical or merely mathematical.<br><br><b>Hence, the correct answer is option (3): Its failure to explain the singularity and reconcile major physical theories.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":78,"local_id":"50078","quid":"Q1000070858","section":"ENGLISH","topic":"Passage","question":{"en":"Read the passage and answer the questions:<br><br>The Big Bang Theory, far from being a mere speculative construct, stands as the most widely endorsed cosmological model explaining the origin and evolution of the universe. Approximately 13.8 billion years ago, the universe emerged from an unimaginably dense and hot singularity—a state where conventional physics collapses under extreme conditions. Within fractions of a second, an exponential inflationary expansion occurred, smoothing out initial irregularities and setting the stage for cosmic structure formation.<br><br>As the universe expanded, it cooled, permitting the formation of subatomic particles and, eventually, simple atomic nuclei during the epoch of nucleosynthesis. Several hundred thousand years later, the universe cooled enough for electrons and nuclei to combine into neutral atoms, an event known as recombination, thereby rendering the universe transparent to radiation. The residual glow from this era, observable today as the Cosmic Microwave Background (CMB) radiation, offers profound empirical support for the Big Bang model.<br><br>However, the theory does not escape philosophical and scientific quandaries. It leaves unanswered the very genesis of the singularity itself and cannot yet reconcile quantum mechanics with general relativity at cosmic scales. Furthermore, anomalies within the CMB, the existence of dark matter and dark energy, and the precise rate of cosmic expansion (Hubble tension) continue to perplex scientists.<br><br>In essence, while the Big Bang Theory illuminates the universe's evolution post-singularity with remarkable coherence, it simultaneously unveils deep epistemological and empirical mysteries, suggesting that humanity's understanding of cosmic origins remains tantalizingly incomplete.<br><br><br>What does the word “epistemological” most nearly mean as used in the passage? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Concerned with physical laws"},"2":{"en":"Pertaining to theories of knowledge"},"3":{"en":"Related to the structure of matter"},"4":{"en":"Connected to temporal events"}},"answer":"2","solution":{"en":"<b>Epistemological (ज्ञान-मीमांसा-संबंधी) = concerning knowledge and its limits.</b><br>The passage describes mysteries about what humanity can know of cosmic origins.<br>Physical laws, matter and time are related subjects but not the definition.<br><br><b>Hence, the correct answer is option (2): Pertaining to theories of knowledge.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":79,"local_id":"50079","quid":"Q1000070859","section":"ENGLISH","topic":"Passage","question":{"en":"Read the passage and answer the questions:<br><br>The Big Bang Theory, far from being a mere speculative construct, stands as the most widely endorsed cosmological model explaining the origin and evolution of the universe. Approximately 13.8 billion years ago, the universe emerged from an unimaginably dense and hot singularity—a state where conventional physics collapses under extreme conditions. Within fractions of a second, an exponential inflationary expansion occurred, smoothing out initial irregularities and setting the stage for cosmic structure formation.<br><br>As the universe expanded, it cooled, permitting the formation of subatomic particles and, eventually, simple atomic nuclei during the epoch of nucleosynthesis. Several hundred thousand years later, the universe cooled enough for electrons and nuclei to combine into neutral atoms, an event known as recombination, thereby rendering the universe transparent to radiation. The residual glow from this era, observable today as the Cosmic Microwave Background (CMB) radiation, offers profound empirical support for the Big Bang model.<br><br>However, the theory does not escape philosophical and scientific quandaries. It leaves unanswered the very genesis of the singularity itself and cannot yet reconcile quantum mechanics with general relativity at cosmic scales. Furthermore, anomalies within the CMB, the existence of dark matter and dark energy, and the precise rate of cosmic expansion (Hubble tension) continue to perplex scientists.<br><br>In essence, while the Big Bang Theory illuminates the universe's evolution post-singularity with remarkable coherence, it simultaneously unveils deep epistemological and empirical mysteries, suggesting that humanity's understanding of cosmic origins remains tantalizingly incomplete.<br><br><br>Choose the correct form to complete the sentence from the passage:<br>“As the universe expanded, it ___ cooler, allowing atomic structures to form.” [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"becomes"},"2":{"en":"became"},"3":{"en":"become"},"4":{"en":"had become"}},"answer":"2","solution":{"en":"<b>Rule: Simple past “became” parallels the past verb “expanded.”</b><br>The cooling occurred as the early universe expanded.<br>Present forms do not fit the historical narrative.<br>Past perfect would require an earlier reference point.<br><br><b>Hence, the correct answer is option (2): became.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":80,"local_id":"50080","quid":"Q1000070860","section":"ENGLISH","topic":"Passage","question":{"en":"Read the passage and answer the questions:<br><br>The Big Bang Theory, far from being a mere speculative construct, stands as the most widely endorsed cosmological model explaining the origin and evolution of the universe. Approximately 13.8 billion years ago, the universe emerged from an unimaginably dense and hot singularity—a state where conventional physics collapses under extreme conditions. Within fractions of a second, an exponential inflationary expansion occurred, smoothing out initial irregularities and setting the stage for cosmic structure formation.<br><br>As the universe expanded, it cooled, permitting the formation of subatomic particles and, eventually, simple atomic nuclei during the epoch of nucleosynthesis. Several hundred thousand years later, the universe cooled enough for electrons and nuclei to combine into neutral atoms, an event known as recombination, thereby rendering the universe transparent to radiation. The residual glow from this era, observable today as the Cosmic Microwave Background (CMB) radiation, offers profound empirical support for the Big Bang model.<br><br>However, the theory does not escape philosophical and scientific quandaries. It leaves unanswered the very genesis of the singularity itself and cannot yet reconcile quantum mechanics with general relativity at cosmic scales. Furthermore, anomalies within the CMB, the existence of dark matter and dark energy, and the precise rate of cosmic expansion (Hubble tension) continue to perplex scientists.<br><br>In essence, while the Big Bang Theory illuminates the universe's evolution post-singularity with remarkable coherence, it simultaneously unveils deep epistemological and empirical mysteries, suggesting that humanity's understanding of cosmic origins remains tantalizingly incomplete.<br><br><br>What is the best synonym for “anomalies” as used in the passage? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Patterns"},"2":{"en":"Deviations"},"3":{"en":"Explanations"},"4":{"en":"Confirmations"}},"answer":"2","solution":{"en":"<b>Anomalies (विसंगतियाँ) = deviations from what is expected.</b><br>The CMB contains unexplained irregularities that perplex scientists.<br>“Deviations” is the closest synonym.<br>Patterns, explanations and confirmations do not express irregularity.<br><br><b>Hence, the correct answer is option (2): Deviations.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":81,"local_id":"50081","quid":"Q1000070861","section":"ENGLISH","topic":"Spelling Check","question":{"en":"Fill in the blank with the correctly spelt word.<br>She was praised for her ___ handling of the sensitive situation. [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"diplomattic"},"2":{"en":"diplomatik"},"3":{"en":"diplomatic"},"4":{"en":"diplometic"}},"answer":"3","solution":{"en":"<b>Diplomatic (कूटनीतिक) = tactful and sensitive.</b><br>The correct spelling is “diplomatic.”<br><b>Diplomattic</b> doubles “t”; <b>diplomatik</b> uses “k.”<br><b>Diplometic</b> changes the vowel and omits “a.”<br><br><b>Hence, the correct answer is option (3): diplomatic.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":82,"local_id":"50082","quid":"Q1000070862","section":"ENGLISH","topic":"One Word Substitution","question":{"en":"What is the custom of having many wives called? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Misogamy"},"2":{"en":"Polygamy"},"3":{"en":"Bigamy"},"4":{"en":"Monogamy"}},"answer":"2","solution":{"en":"<b>Polygamy (बहुविवाह) = the practice of having multiple spouses.</b><br>The intended custom of multiple wives falls under polygamy.<br><b>Misogamy</b> = hatred of marriage<br><b>Bigamy</b> = marriage to two people illegally; <b>monogamy</b> = one spouse<br><br><b>Hence, the correct answer is option (2): Polygamy.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":83,"local_id":"50083","quid":"Q1000070863","section":"ENGLISH","topic":"Fill in the Blanks","question":{"en":"Fill in the blank with the appropriate adverb.<br>The scholar spoke ___, preferring depth to flamboyance. [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"within"},"2":{"en":"onward"},"3":{"en":"amiss"},"4":{"en":"thus"}},"answer":"4","solution":{"en":"<b>Thus (इस प्रकार) = in this manner.</b><br>The scholar spoke in the manner described: with depth rather than flamboyance.<br>“Within” refers to location, “onward” to forward movement.<br>“Amiss” means wrongly.<br><br><b>Hence, the correct answer is option (4): thus.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":84,"local_id":"50084","quid":"Q1000070864","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Rearrange the parts of the sentence in the correct order.<br>As women's sports gained increasing global recognition,<br>P. sparking discussions on the long-term impact of these changes on gender equality in athletics,<br>Q. while governing bodies introduced policies to ensure equal prize money in certain competitions,<br>R. major broadcasting networks and corporate sponsors started investing heavily in female athletes,<br>S. despite ongoing disparities in media coverage and sponsorship deals compared to men’s sports [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"SPQR"},"2":{"en":"RSQP"},"3":{"en":"RPQS"},"4":{"en":"PQSR"}},"answer":"3","solution":{"en":"<b>Order: RPQS</b><br>R states the increased investment in female athletes.<br>P gives its consequence: discussions of gender equality.<br>Q adds equal-prize policies, and S acknowledges remaining disparities.<br><br><b>Hence, the correct answer is option (3): RPQS.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":85,"local_id":"50085","quid":"Q1000070865","section":"ENGLISH","topic":"Phrasal Verbs","question":{"en":"Fill in the blank with an appropriate phrasal verb.<br>The committee decided to ___ the controversial proposal until after the elections. [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"put forward"},"2":{"en":"put off"},"3":{"en":"put out"},"4":{"en":"put up"}},"answer":"2","solution":{"en":"<b>Put off (टालना) = postpone.</b><br>The committee postponed the proposal until after the elections.<br><b>Put forward</b> = propose; <b>put out</b> = extinguish<br><b>Put up</b> = erect or accommodate<br><br><b>Hence, the correct answer is option (2): put off.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":86,"local_id":"50086","quid":"Q1000070866","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Rearrange the parts of the sentence in the correct order.<br>The nature of consciousness<br>P. has long been a subject of philosophical inquiry,<br>Q. integrating perspectives from neuroscience and artificial intelligence<br>R. as scholars attempt to decipher its origins and mechanisms<br>S. while exploring the boundaries between cognition and perception [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"PQRS"},"2":{"en":"PRSQ"},"3":{"en":"SRPQ"},"4":{"en":"QPRS"}},"answer":"2","solution":{"en":"<b>Order: PRSQ</b><br>P supplies the main predicate.<br>R explains scholars’ efforts to understand consciousness.<br>S adds exploration of cognition and perception, and Q identifies integrated disciplines.<br><br><b>Hence, the correct answer is option (2): PRSQ.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":87,"local_id":"50087","quid":"Q1000070867","section":"ENGLISH","topic":"Idioms and Phrases","question":{"en":"Choose the correct idiom for the word highlighted in bold.<br>Having no arguments to defend his point, the Manager began to <b>beat about the bush</b>. [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"To avoid coming to the main point"},"2":{"en":"To directly address the issue"},"3":{"en":"To make a false statement"},"4":{"en":"To strongly defend one's argument"}},"answer":"1","solution":{"en":"<b>Beat about the bush (इधर-उधर की बात करना) = avoid the main issue.</b><br>The manager spoke indirectly because he lacked a defence.<br>Directly addressing the issue is the opposite.<br>The idiom does not necessarily involve lying.<br><br><b>Hence, the correct answer is option (1): To avoid coming to the main point.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":88,"local_id":"50088","quid":"Q1000070868","section":"ENGLISH","topic":"Spotting Errors","question":{"en":"Identify the word in this sentence that contains an error.<br>She was married <b>with</b> a diplomat from Spain. [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"married"},"2":{"en":"Spain"},"3":{"en":"with"},"4":{"en":"diplomat"}},"answer":"3","solution":{"en":"<b>Rule: “Married to someone” is the standard construction.</b><br>Correct sentence: “She was married <b>to</b> a diplomat from Spain.”<br>The erroneous word is “with.”<br>The other words are correct.<br><br><b>Hence, the correct answer is option (3): with.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":89,"local_id":"50089","quid":"Q1000070869","section":"ENGLISH","topic":"Sentence Improvement","question":{"en":"Choose the option that best improves the sentence using the correct collocation highlighted in bold.<br>After analyzing the data, we can <b>make a conclusion</b> about the results. [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"draw a conclusion"},"2":{"en":"reach a conclusion"},"3":{"en":"create a conclusion"},"4":{"en":"find a conclusion"}},"answer":"1","solution":{"en":"<b>Collocation: “Draw a conclusion” means form a judgment from evidence.</b><br>The data analysis allows us to draw a conclusion.<br>“Create” and “find” are not standard in this context.<br>The keyed option is “draw a conclusion.”<br><br><b>Hence, the correct answer is option (1): draw a conclusion.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":90,"local_id":"50090","quid":"Q1000070870","section":"ENGLISH","topic":"Idioms and Phrases","question":{"en":"What does the idiom “to be pressed for time” mean? [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"To have plenty of free time"},"2":{"en":"To be in a hurry due to a lack of time"},"3":{"en":"To waste time on unnecessary things"},"4":{"en":"To manage time effectively"}},"answer":"2","solution":{"en":"<b>Pressed for time (समय की कमी होना) = rushed because time is short.</b><br>Example: “I can’t talk now; I’m pressed for time.”<br>Plenty of free time is the opposite.<br>Wasting or managing time is not implied.<br><br><b>Hence, the correct answer is option (2): To be in a hurry due to a lack of time.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":91,"local_id":"50091","quid":"Q1000070871","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Which of the given options arranges the following sentences in the most logical sequence to form a meaningful paragraph?<br>1. According to Kant, individuals must treat others as ends in themselves, not merely as means to an end.<br>2. The Categorical Imperative is a moral law that commands individuals to act in ways that could be made a universal law.<br>3. Immanuel Kant's ethical theory is based on the idea of the Categorical Imperative, which dictates that actions must be universally applicable.<br>4. Kant believed that morality is not based on the consequences of actions, but on the principle behind them.<br>5. Thus, the Categorical Imperative is a key component of Kant’s deontological ethics, which emphasizes duty over outcomes. [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"3-2-4-1-5"},"2":{"en":"4-3-1-2-5"},"3":{"en":"5-1-2-3-4"},"4":{"en":"4-3-1-5-2"}},"answer":"1","solution":{"en":"<b>Order: 3-2-4-1-5</b><br>Sentence 3 introduces Kant’s theory, and sentence 2 defines its moral law.<br>Sentence 4 contrasts principles with consequences, and sentence 1 adds treating people as ends.<br>Sentence 5 concludes with deontological duty.<br><br><b>Hence, the correct answer is option (1): 3-2-4-1-5.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":92,"local_id":"50092","quid":"Q1000070872","section":"ENGLISH","topic":"Para Jumbles (PQRS)","question":{"en":"Which of the given options arranges the following sentences in the most logical sequence to form a meaningful paragraph?<br>1. With the help of allies and through personal growth, the hero ultimately conquers the ordeal and returns home with a gift or knowledge.<br>2. The hero receives a call to adventure, often from a mentor or supernatural source, prompting them to leave their ordinary world.<br>3. The hero's return marks the completion of their transformation and reintegration into society.<br>4. The Hero's Journey is a narrative pattern that involves a hero who goes on an adventure, faces a crisis, and returns home transformed.<br>5. After a series of challenges, the hero faces a major ordeal, often involving life or death situations. [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"3-5-1-2-4"},"2":{"en":"4-2-5-1-3"},"3":{"en":"2-4-1-5-3"},"4":{"en":"5-1-4-3-2"}},"answer":"2","solution":{"en":"<b>Order: 4-2-5-1-3</b><br>Sentence 4 introduces the narrative pattern.<br>The call to adventure, major ordeal and victorious return follow in narrative order.<br>Sentence 3 concludes with reintegration into society.<br><br><b>Hence, the correct answer is option (2): 4-2-5-1-3.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":93,"local_id":"50093","quid":"Q1000070873","section":"ENGLISH","topic":"Active Passive Voice","question":{"en":"Change the following from active to passive:<br>Security forces are monitoring the situation closely. [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"The situation is being closely monitored by security forces."},"2":{"en":"The situation was closely monitored by security forces."},"3":{"en":"The situation is being monitored by the forces closely."},"4":{"en":"The situation was being closely monitored."}},"answer":"1","solution":{"en":"<b>Rule: Present continuous passive = is/are being + past participle.</b><br>The singular object “situation” takes “is being monitored.”<br>“Closely” naturally modifies “monitored,” and the agent is retained.<br>The other options change tense or adverb placement.<br><br><b>Hence, the correct answer is option (1): The situation is being closely monitored by security forces.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":94,"local_id":"50094","quid":"Q1000070874","section":"ENGLISH","topic":"Synonym","question":{"en":"Select the most appropriate synonym of the given word: <b>LUGUBRIOUS</b> [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Bright"},"2":{"en":"Mournful"},"3":{"en":"Happy"},"4":{"en":"Hopeful"}},"answer":"2","solution":{"en":"<b>Lugubrious (शोकपूर्ण) = sad and mournful.</b><br><b>Bright (उज्ज्वल)</b> = cheerful or shining<br><b>Mournful (शोकपूर्ण)</b> = sorrowful ✔<br><b>Happy (प्रसन्न)</b> = joyful; <b>hopeful (आशावान)</b> = optimistic.<br><br><b>Hence, the correct answer is option (2): Mournful.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":95,"local_id":"50095","quid":"Q1000070875","section":"ENGLISH","topic":"Synonym","question":{"en":"Select the most appropriate synonym of the given word: <b>INDEMNIFY</b> [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Charge"},"2":{"en":"Remunerate"},"3":{"en":"Tax"},"4":{"en":"Fine"}},"answer":"2","solution":{"en":"<b>Indemnify (क्षतिपूर्ति करना) = compensate for loss or damage.</b><br><b>Charge (शुल्क लेना)</b> = demand payment<br><b>Remunerate (पारिश्रमिक देना)</b> = pay or compensate ✔<br><b>Tax (कर लगाना)</b> = levy; <b>fine (जुर्माना)</b> = penalize.<br><br><b>Hence, the correct answer is option (2): Remunerate.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":96,"local_id":"50096","quid":"Q1000070876","section":"ENGLISH","topic":"Antonym","question":{"en":"Select the most appropriate antonym of the given word. <b>Apathy</b> [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Indifference"},"2":{"en":"Passion"},"3":{"en":"Disinterest"},"4":{"en":"Detachment"}},"answer":"2","solution":{"en":"<b>Apathy (उदासीनता) = lack of interest or feeling.</b><br><b>Indifference (उदासीनता)</b> = unconcern<br><b>Passion (जुनून)</b> = intense feeling ✔<br><b>Disinterest (अरुचि)</b> = lack of interest; <b>detachment (अलगाव)</b> = emotional distance.<br><br><b>Hence, the correct answer is option (2): Passion.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":97,"local_id":"50097","quid":"Q1000070877","section":"ENGLISH","topic":"Spelling Check","question":{"en":"Spot the correct spelling of a term meaning “state of self-rule or independence”. [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Autonomy"},"2":{"en":"Autonamy"},"3":{"en":"Autonnomy"},"4":{"en":"Autonimy"}},"answer":"1","solution":{"en":"<b>Autonomy (स्वायत्तता) = self-government or independence.</b><br>The correct spelling is “autonomy.”<br><b>Autonamy</b> replaces “o” with “a.”<br><b>Autonnomy</b> doubles “n”; <b>autonimy</b> uses “i.”<br><br><b>Hence, the correct answer is option (1): Autonomy.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":98,"local_id":"50098","quid":"Q1000070878","section":"ENGLISH","topic":"Homophones and Homonyms","question":{"en":"Select the sentence containing the homonym of the highlighted word:<br>The treasure was hidden inside the ancient <b>vault</b>. [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"The vault was made of reinforced steel."},"2":{"en":"He placed the bag in the vault."},"3":{"en":"The gymnast executed a perfect vault."},"4":{"en":"The guards opened the vault with a key."}},"answer":"3","solution":{"en":"<b>Vault = a secure chamber, or a gymnastic leap.</b><br>The original uses the storage-chamber meaning.<br>Option C uses the gymnastic meaning.<br>The other options retain the secure-room meaning.<br><br><b>Hence, the correct answer is option (3): The gymnast executed a perfect vault.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":99,"local_id":"50099","quid":"Q1000070879","section":"ENGLISH","topic":"Sentence Improvement","question":{"en":"Choose the most suitable option to replace the highlighted part of the sentence:<br>He <b>is one of the best player</b> in the team. [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"one of best players"},"2":{"en":"one of the better player"},"3":{"en":"one of the best players"},"4":{"en":"one of the most player"}},"answer":"3","solution":{"en":"<b>Rule: “One of the + superlative + plural noun” is required.</b><br>Correct wording: “one of <b>the best players</b>.”<br>“Player” must be plural because he belongs to a group.<br>The other options omit the article or use incorrect forms.<br><br><b>Hence, the correct answer is option (3): one of the best players.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false},{"no":100,"local_id":"50100","quid":"Q1000070880","section":"ENGLISH","topic":"Antonym","question":{"en":"Choose the most appropriate antonym of the underlined word.<br>The editor praised the columnist for the <b>brevity</b> of her political analysis. [SSC CGL 28/10/26 Shift 2]"},"options":{"1":{"en":"Prolixity"},"2":{"en":"Conciseness"},"3":{"en":"Pithiness"},"4":{"en":"Terse"}},"answer":"1","solution":{"en":"<b>Brevity (संक्षिप्तता) = concise expression.</b><br><b>Prolixity (शब्दाडंबर)</b> = excessive wordiness ✔<br><b>Conciseness (संक्षिप्तता)</b> = brevity<br><b>Pithiness (सारगर्भितता)</b> = concise force; <b>terse (संक्षिप्त)</b> = brief<br><br><b>Hence, the correct answer is option (1): Prolixity.</b>"},"marks":{"correct":2,"negative":0.5},"has_image":false}]}}};